quests[27124] = { id = 27124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die offene Rechnung der Gordok", description = "Nun Ihr de' König sein, vielleicht Ihr kriegen zurück wertvolles Artefakt der Gordok von Wächter Mol'dar! König vor Euch hat versagt, so wie alle Könige seit Tortheldrin - de' gruselige Elf - es gestohlen hat, von damaligen Gordokkönig!\n\nArtefakt heißen Stulpen der Gordokmacht. Alte Zeit Geschichten sagen, nur de' wahre König de' Gordok kann sie zurückholen. Alte Zeit Geschichten sagen auch, de' gruselige Elf ist immer noch hier - Ihr finden es und es werden Eure mächtigen Stulpen, für immer! Yar, ich zeigen!", sourceObjective = "Sprecht mit Wache Mol'dar in Düsterbruch.", completion = "Wow... Ihr SEID de' wahre König! Alter König niemals auch nur nach Stulpen gefragt!\n\nGuckt - dieses Zeichen auf de' Stulpen ist ein sehr sehr SEHR altes Zeitsymbol. Älter als Gordok, sagen sie. Nun, als kleiner Oger bekommen eins beigebracht: Wie man machen Zeichen wieder lebendig, um geben den Stulpen die Kraft zurück!\n\nIch werde es für Euch tun, König! Hier, nehmen Stulpen und herrschen AUF EWIG!", sourceObjectiveStatus = "unverified-source-field" }
quests[27125] = { id = 27125, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "König der Gordok", description = "Bei den Gordok, ist der stärkste Krieger der König. Wenn jemand, egal ob Oger oder sonstwer, den amtierenden König tötet, wird er automatisch als neuer König begrüßt.\n\nDer neue König erhält Tribut von allen lebenden Wachen, Stampfer Kreeg und Hauptmann Krombruch. Findet und tötet König Gordok, aber tötet so wenig der anderen Anführer wie möglich. Ihr werdet nicht nur eine reiche Belohnung erhalten, sondern könnt Eure Macht als König benutzen, um die Invasion der Gordok ohne Konflikt zu verhindern!", sourceObjective = "Tötet König Gordok.", completion = "Ja! Ich sehe, Ihr wart erfolgreich. Ihr habt Euren Tribut erhalten, den Vormarsch der Gordok gibt es nicht mehr und die Gordok haben von all dem keine Ahnung! Das ist das Szenario eines Gewinners, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27126] = { id = 27126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eilige Lieferung", description = "Spitz Schleifsteins Team hatte irgendwo im Westen eine Panne.\n\nMeint Ihr, Ihr könnt Euch zur Abwechslung mal nützlich machen und einige Ersatzteile zu ihnen hinausbringen, {race}?", sourceObjective = "Liefert die Katapultteile bei Spitz Schleifstein an der Zerrissenen Front in Tiefenheim ab.", progress = "Habt Ihr da die Ersatzteile?", completion = "Ich kann Euch nicht genug danken, {class}. Dann lasst uns mal sehen, ob wir das Katapult wieder in Bewegung bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27128] = { id = 27128, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "König der Gordok", description = "Du tötest Anführer der Gordok, du neuer Ogerkönig. Wenn du König, dann überlebende Ogeranführer wie Kromcrush und Kreeg zahlen großen Tribut und du beendest Gordokinvasion. Wenn du das tust, dann ich sehr glücklicher Oger und wir nehmen Düsterbruch FÜR DIE HORDE!!!\n\nGeht, kleiner {race}! Tötet hässlichen Gordok Ogerkönig und vielleicht das hier neue Steinbrecherfestung! Yar!", sourceObjective = "Tötet König Gordok.", completion = "Kleiner {race} hat es geschafft! Horde jetzt mächtiger denn je! YAR!", sourceObjectiveStatus = "unverified-source-field" }
quests[27129] = { id = 27129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wucherborke retten", description = "Direkt im Ostflügel von Düsterbruch lebt eines der Urtume der Wucherborken, Furugs Wucherborke, noch vollkommen unverdorben. Ihr müsst dorthin reisen und ihm helfen, die furchtbaren Kreaturen zu vertreiben, die alles für sich einnehmen. Düsterbruch einzunehmen wäre ein Riesenfortschritt, Feralas für unser Volk wieder zurückzuerobern.\n\nIhr findet Düsterbruch südöstlich von hier.", sourceObjective = "Sprecht mit Furgus Wucherborke.", completion = "Seid Ihr in letzter Zeit einem Druiden der Kralle begegnet, {class}? Die Anwesenheit eines solchen Druiden hängt in der Luft.", sourceObjectiveStatus = "unverified-source-field" }
quests[27130] = { id = 27130, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wucherborke retten", description = "Direkt im Ostflügel von Düsterbruch lebt eines der Urtume der Wucherborken, Furugs Wucherborke, noch vollkommen unverdorben. Ihr müsst dorthin reisen und ihm helfen, die furchtbaren Kreaturen zu vertreiben, die alles für sich einnehmen bevor sie Camp Mojache entdecken. Vielleicht können wir uns seiner Hilfe für später versichern, um unsere Anwesenheit in Feralas zu sichern, wo wir doch von Feinden umzingelt sind.", sourceObjective = "Sprecht mit Furgus Wucherborke.", completion = "In Eurem Gesicht sehe ich Anzeichen für einen verzweifelten Kampf. Eure Gegenwart ehrt mich, mutiger {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27131] = { id = 27131, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hochgeborene", description = "Estulan, ein mächtiger und unverdorbener Hochgeborener, hat sich Zutritt zum westlichen Flügel von Düsterbruch verschafft und bittet um Mithilfe, diesen zu säubern. Ungeachtet Eurer persönlichen Ansichten über die Hochgeborenen, muss ich diese Bemühung zum Wohle von Feralas gutheißen. Möge der Wind Euren Geist mit großer Geschwindigkeit dorthintragen.\n\nIhr findet Düsterbruch südöstlich von hier.", sourceObjective = "Sprecht mit Estulan.", completion = "Ich spürte auf dem ganzen Weg von Träumersruh, dass Ihr kommen würdet. Eure Hilfe wäre mir sehr willkommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27132] = { id = 27132, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hochgeborene", description = "Estulan, ein mächtiger und unverdorbener Hochgeborener, hat sich Zutritt zum westlichen Flügel von Düsterbruch verschafft und bittet um Mithilfe, diesen zu säubern. Ungeachtet Eurer persönlichen Ansichten über die Hochgeborenen, muss ich diese Bemühung zu unserem Wohle gutheißen. Bitte beeilt Euch - wir brauchen jeden Fuß in der Tür von Feralas, den wir bekommen können.\n\nIhr findet Düsterbruch im Westen.", sourceObjective = "Sprecht mit Estulan.", completion = "Ich spürte auf dem ganzen Weg von Camp Mojache, dass Ihr kommen würdet. Eure Hilfe wäre mir sehr willkommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27133] = { id = 27133, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blick zum Himmel", description = "Die schlimmste und am besten organisierte Gefahr in Feralas stellen für uns die Oger der Gordok am nördlichen Flügel von Düsterbruch dar. Ich habe einen Druiden der Kralle beauftragt, sich dorthin zu begeben und die Lage zu erkunden. Meldet Euch bei ihm, falls er noch am Leben ist. Er wird Euch befehligen, um die Gordok aufzuhalten, bevor sie sich zum Angriff entscheiden.\n\nDas ist ein Befehl, {class}.", sourceObjective = "Sprecht mit dem Druiden der Kralle.", completion = "Sprecht leise, {name}. Die Gordok sind zwar nicht sehr schlau, aber sie sind trotzdem gefährliche Krieger.", sourceObjectiveStatus = "unverified-source-field" }
quests[27134] = { id = 27134, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oger im Feld", description = "Die schlimmste und am besten organisierte Gefahr in Feralas stellen für uns die Oger der Gordok am nördlichen Flügel von Düsterbruch dar. Wenn wir sie auslöschen und Düsterbruch für die Horde in Anspruch nehmen, könnten wir unsere Machtposition in dieser artefaktreichen Gegend enorm stärken. Ich habe vor kurzer Zeit eine kleine Truppe Oger der Steinbrecher losgeschickt. Sprecht mit möglichen Überlebenden und beendet, was begonnen wurde.\n\nDas ist ein Befehl, {class}.", sourceObjective = "Sprecht mit dem Oger der Steinbrecher.", completion = "Diese Oger keine Knallschoten. Hilf mir, Orhans Aufgabe zu vollenden, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27135] = { id = 27135, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Etwas, das brennt", description = "Also, wir brauchen etwas, mit dem das Präparat in die Luft fliegt - KABUMM!\n\nIch habe kein Schießpulver mehr, aber ich habe eine Idee, was wir stattdessen verwenden können ... das Herz meines Feuerelementars!\n\nHier, nehmt mein Feuertotem mit nach Osten auf Eurem Weg zum Blutpfad. Betätigt es dort in der Nähe der Lavaseen, und Magmazahn sollte erscheinen. Bringt mir sein Herz, dann unterhalten wir uns weiter.", sourceObjective = "Erhaltet das brennende Herz.", progress = "Habt Ihr das Herz schon?", completion = "Oha. Es scheint, als hätte die Situation ihn nicht gerade erfreut. Wie hätte ich das wissen können? Ich bin doch nur ein Initiand.\n\nWie dem auch sei. Über Magmazahn sorge ich mich später.", sourceObjectiveStatus = "unverified-source-field" }
quests[27136] = { id = 27136, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elementarenergie", description = "Wir müssen unsere ganze Kraft aufbringen, um die Stabilität des Reichs in der Abwesenheit der Weltensäule sichern zu können.\n\nAls Schamanen können wir direkt die Energien der Elementare von Tiefenheim anzapfen und zur Heilung für vom Riss verursachten Schaden nutzen.\n\nNehmt dieses Totem und platziert es außen auf dem Boden. Alle aufgeladenen Geoden oder zerstörten Leitsteinelementare in der Nähe werden es mit der Energie füllen, die wir benötigen.", sourceObjective = "Zerstört 8 aufgeladene Geoden oder Leitsteinelementare in der Nähe des erschöpften Totems.", completion = "Ich danke Euch, {name}. Wir benötigen alle Kraft, die wir aufbringen können, um die Stabilität von Tiefenheim zu sichern.", sourceObjectiveStatus = "unverified-source-field" }
quests[27139] = { id = 27139, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hobart braucht Euch", description = "He da, Boss! Hobart Wurfhammer möchte mit Euch sprechen. Er sagt, es wäre eine Angelegenheit von höchster Dringlichkeit!", sourceObjective = "Sprecht mit Hobart Wurfhammer in Instastadt auf den Verlorenen Inseln.", completion = "Da seid Ihr ja, mein Junge! Ich habe etwas äußerst Wichtiges, was Ihr für mich erledigen müsst.", sourceObjectiveStatus = "unverified-source-field" }
quests[27140] = { id = 27140, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alexis Gambit", description = "Ich benötige Eure Hilfe, {class}. Findet den Untoten Magier Vectus und den Krieger Marduk hier in den Tiefen. Sie sind mit der Operation des verseuchten Drachen der Geißel beschäftigt und müssen aufgehalten werden.\n\nPlatziert das Gambit in dem Vorführraum, in dem sie sich befinden. Hoffentlich entsteht eine Reaktion mit ihren Kräften und zerstört sie!\n\nOh, Vectus und Marduk danach zu bewältigen dürfte auch kein Problem darstellen, oder?", sourceObjective = "Platziert das Gambit im Vorführraum und tötet Vectus und Marduk.", completion = "Ihr habt es geschafft! Sie sind besiegt! Und das Gambit - hat es funktioniert?\n\nSehr interessant. Ihr habt gute Arbeit geleistet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27141] = { id = 27141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Explosiv", description = "Was für ein Fund!\n\nGenau hier... genau an der Stelle, die in meinen Notizen vorhergesagt wurde.\n\nMit ein wenig Glück werden sich in dieser Kammer Hinweise zum Verbleib der legendären Lade der Verheißung finden lassen.\n\nJa, das stimmt, {name}. Es ist nicht nur eine Legende. Ich glaube, dass es die Lade wirklich gibt.\n\nIch werde Euch später mehr erklären. Helft mir jetzt erstmal mit diesen Sprengsätzen.", sourceObjective = "Helft Harrison Jones am Grab des Khartut.", completion = "Schüttelt es ab, Kleiner.\n\nPassiert mir ständig...", sourceObjectiveStatus = "unverified-source-field" }
quests[27142] = { id = 27142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Lich Ras Frostraunen", description = "Einer der Studenten, denen Kel'Thuzad viel Vertrauen schenkt, leitet die Operationen in Scholomance. Tretet dem Lich Ras Frostraunen in seinem Unterschlupf gegenüber. Die hintere Tür im Vorführraum führt in seine Kammer.\n\nZerstört ihn, {name}. Löscht jeglichen Nachweis seiner Existenz aus, so dass er nie wieder solche Schrecken in unsere Welt bringen kann.", sourceObjective = "Vernichtet Ras Frostraunen.", completion = "Abertausende Seelen schreien im Einklang aus, {name}. Ihr habt mit einem tödlichen Schlag die Geißel und ihre Meister vernichtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[27143] = { id = 27143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Familienvermögen der Barovs", description = "Das Familienvermögen der Barovs liegt in Scholomance. Alexi und ich sind die beiden letzten verbliebenen Erben des Hauses Barov.\n\nIch bin jedoch der letzte Barov, der am Leben ist, und somit ist das ganze Reich der Barovfamilie mein! Findet die Besitzurkunden für Darrowehr, Brill, Tarrens Mühle und Süderstade, und ich werde Euch mit großem Reichtum belohnen. Der Besitz der Barov wird endlich wieder in voller Blüte stehen!", sourceObjective = "Findet die Besitzurkunde für Darrowehr, die Besitzurkunde für Brill, die Besitzurkunde für Tarrens Mühle und die Besitzurkunde für Süderstade.", progress = "Verneigt Euch in meiner Gegenwart, {race}. Ich bin immerhin von Adel, und Ihr seid nur ein armer Bauer.", completion = "Ihr habt vorzügliche Arbeit geleistet, {race}. Für diese Torheit verdient Alexi kein Lob.", sourceObjectiveStatus = "unverified-source-field" }
quests[27144] = { id = 27144, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Abrechnung", description = "Ihr habt eine vortreffliche Leistung vollbracht. Ihr erfüllt die Verlassenen mit Stolz, was ich von Kriegsherr Koltira Todesweber nicht behaupten kann.\n\nIch habe vor, ein ernstes Wörtchen mit diesem Todesritter zu wechseln. Er hat Schande über sich und das, wofür er steht, gebracht.", sourceObjective = "Wartet, bis Fürstin Sylvanas Windläufer mit Koltira Todesweber gesprochen hat.", completion = "Ich habe nichts gegen die Ritter der Schwarzen Klinge, aber Koltira muss sich im Klaren darüber sein, für wen er arbeitet. Seine Loyalität muss einzig und allein der Horde gelten.\n\nGenauer gesagt, den Verlassenen.\n\nIch würde mich nicht darauf verlassen, Koltira bald wieder zu sehen. Jetzt, da ich ihn habe ... könnt Ihr Euch sicher sein, dass alle seine Verbindungen zu irgendwelchen Allianzlern vollständig zerstört werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27145] = { id = 27145, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verseuchte Jungtiere ... im Moment", description = "Eines der aktuellen 'Projekte' ist der verseuchte Drachenschwarm. Glücklicherweise handelt es sich dabei um Jungtiere, aber wenn wir noch länger warten, werden sie zu einer der mächtigsten Waffen im Arsenal der Geißel und eine ernst zu nehmende Gefahr für Azeroth, und vor allem für die Ländereien meiner Familie.\n\nErschlagt zehn der Jungtiere und vergesst nicht, Euch auch um Blutrippe zu kümmern. Ihr findet ihn in der Nähe der Behausung der Jungtiere, wo er Nahrungsergänzungen zubereitet, die das Wachstum ankurbeln sollen. Beeilt Euch - bevor sie noch größer werden!", sourceObjective = "Tötet 10 verseuchte Jungtiere und Blutrippe.", completion = "Gute Arbeit, {name}. Es wird lange dauern, bis unser Feind eine neue Generation dieser Drachen züchten kann.\n\n... Zumindest hoffe ich das!", sourceObjectiveStatus = "unverified-source-field" }
quests[27146] = { id = 27146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doktor Theolen Krastinov, der Schlächter", description = "Doktor Theolen Krastinov ist für die Tode Tausender verantwortlich. Seinen Spitznamen 'der Schlächter' hat er sich mit den Gräueltaten, die ihm so viel Freude bereiten, redlich verdient. Er muss im Namen der Gerechtigkeit bestraft werden.\n\nSucht ihn und bringt jene Qual über ihn, die er über zahllose Unschuldige wie mich und meinem Ehemann gebracht hat. Wenn er vernichtet ist, verbrennt unsere Überreste. Verwandelt sie in Asche, {name}. Befreit unsere schmerzenden Seelen.", sourceObjective = "Vernichtet Doktor Theolen Krastinov, und verbrennt die Überreste von Eva Sarkhoff und die Überreste von Lucien Sarkhoff.", completion = "Ich fühle, wie mein Geist heilt, {name}. Ihr habt meinem Ehemann und mir einen großen Dienst erwiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27147] = { id = 27147, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kirtonos der Herold", description = "Mit Blut lässt Kirtonos sich anlocken. Also wird es Blut sein, das Kirtonos zerstören wird.\n\nIn der Kammer der Beschwörung werdet Ihr eine Kohlenpfanne finden, über der Ihr einen Tropfen Eures eigenen Blutes vergießen müsst. Kirtonos wird erscheinen - er kann nicht widerstehen. Entfesselt sobald er auftaucht den Zorn und Furor Tausender Unschuldiger.\n\nSollte Ihr erfolgreich sein, werdet Ihr mehr als nur unseren Dank erhalten.", sourceObjective = "Zerstört Kirtonos.", completion = "Mit dem Tod Kirtonos wird ein schreckliches Kapitel der Geschichte von Scholomance abgeschlossen. Ihr habt für Euren Mut nun für immer meine tiefste Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[27148] = { id = 27148, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hurra, die Schule brennt", description = "Dunkelmeister Gandling ist der Direktor von Scholomance und daher für die zahllosen Tode verantwortlich, die seine Schüler für ihn ausführten. Dafür muss er bestraft werden.\n\nEr wird nicht so einfach aus seinem Arbeitszimmer kommen. Lockt ihn heraus, indem Ihr die sechs Professoren tötet, deren Zimmer zum Arbeitszimmer des Direktors führen. Seid vorsichtig, denn wenn der letzte Professor erledigt ist, wird er mehr als erzürnt erscheinen und mit überwältigender Magie angreifen. Seht zu, dass er es nicht aus dem Arbeitszimmer schafft.", sourceObjective = "Tötet Dunkelmeister Gandling.", completion = "Ohne einen Direktor wird die Schule im Chaos versinken, und es werden nicht noch mehr dieser abscheulichen ‚Studenten‘ ausgebildet. Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[27149] = { id = 27149, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schule der Verdammten", description = "Seid gegrüßt! Wie Ihr sehen könnt, sind die Westlichen Pestländer von beinahe allen Restposten der Geißel befreit. Allerdings ist Scholomance, die Schule der Totenbeschwörung, noch voller junger Seelen, die nur darauf warten, ihre Ausbildung zu Zauberern der Geißel abzuschließen. Unsere Arbeit wird umsonst gewesen sein, wenn wir dem ständigen Nachrücken immer neue - und vorallem auch mächtiger - Totenbeschwörer kein Ende setzen.\n\nReist südöstlich nach Scholomance und sucht Weldon Barov. Er ist der letzte lebende Nachkomme der Familie Barov, der einst alle diese Ländereien gehörten, und er ist unser Kontakt vor Ort.", sourceObjective = "Sprecht mit Weldon Barov in Scholomance.", sourceObjectiveStatus = "unverified-source-field" }
quests[27150] = { id = 27150, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Stätte der Heiler", description = "Wahrscheinlich wird die Schlacht um Andorhal bald wieder wüten. In der Zwischenzeit solltet Ihr Eure Fähigkeiten als {class} verfeinern.\n\nÖstlich von hier befindet sich ein großer Bauernhof, der von der Argentumdämmerung und dem Zirkel des Cenarius eingenommen worden ist. Ich bezweifle nicht, dass Ihr dort Arbeit finden werdet.", sourceObjective = "Meldet Euch bei Außenagent Kaartish in der Stätte der Heiler in den Westlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[27151] = { id = 27151, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taelan Fordrings Vermächtnis", description = "Seid gegrüßt. Wie geht es Euch? Mein Name ist Daria.\n\nIch bin eine der Priesterinnen, die für den Erhalt des Friedens hier in Herdweiler zuständig ist. Eine meiner Aufgaben ist die Verwaltung des Turms entlang des Wegs südöstlich von Herdweiler. Dieser Turm ist von persönlicher Bedeutung für den Hochlord. Sein Sohn wurde dort getötet.\n\nDie Verwaltung des Turms bereitet jedoch aufgrund des feindlichen Einfalls der Gnolle vor Kurzem zunehmend Schwierigkeiten. Könnt Ihr mir helfen, den Weg von den Vandalen der Gnolle zu räumen, sodass ich meinen Pflichten nachkommen kann?", sourceObjective = "Tötet 10 Plünderer der Rotkiefer.", sourceObjectiveStatus = "unverified-source-field" }
quests[27152] = { id = 27152, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungewöhnliches Verhalten ... selbst für Gnolle", description = "Ich muss mich kurz konzentrieren.\n\n<Ihr fühlt, wie Darias Gedankensicht einen anderen Ort aufsucht, und dann wieder zu Euch zurückkehrt.>\n\nSüdlich des Turm von Taelan haben die Gnolle einen Ort der Zusammenkunft errichtet - folgt dem Weg, und haltet Euch östlich der Hauptstraße. Dort geht etwas vor sich ... aber ich bin nicht sicher, was es ist. Wir sollten mehr darüber in Erfahrung bringen. Ich werde nach ungewöhnlichen Ereignissen Ausschau halten ... Ihr solltet Euch damit beschäftigen, Euch zu schützen.", sourceObjective = "Erkundet das Versteck der Gnolle entlang des Wegs nach Herdweiler in den Westlichen Pestländern.", completion = "Gnolle und Totenbeschwörung? Das ist eine Überraschung! Und ich dachte, dass hier in den Westlichen Pestländern diese dunklen Tage der Vergangenheit angehören würden.\n\n<Ihr spürt, wie Daria etwas auf dem Boden genau betrachtet.>\n\nWartet ... was ist DAS?", sourceObjectiveStatus = "unverified-source-field" }
quests[27153] = { id = 27153, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die braven Bürger von Herdweiler", description = "Seht Ihr die Reagenzien dort drüben? Und diese Ladungen hier? Es handelt sich dabei um das Eigentum der Argentumkreuzfahrer.\n\nGnolle sind für das Stehlen von Gütern bekannt, aber meines Wissens gab es in Herdweiler seit dem Einfall der Rotkiefer keine Vorfälle mehr. Das ist sehr merkwürdig.\n\nIch habe ein paar Kontakte in Herdweiler, die Euch helfen könnten: Morris Vant, Ausstatter Mendelev, Bree Eisenstock und der Hohe Kleriker Alphus. Ihr könnt ihnen vertrauen, und sie haben gute Verbindungen. Befragt sie, um herauszufinden, ob sie etwas über die verlorengegangenen Ladungen wissen.", sourceObjective = "Sprecht mit Morris Vant, Ausstatter Mendelev, Bree Eisenstock und dem Hohen Kleriker Alphus in Herdweiler.", sourceObjectiveStatus = "unverified-source-field" }
quests[27154] = { id = 27154, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bisp festsetzen", description = "Magus Bisp ist einer der renommiertesten Arkanisten von Herdweiler. Die Vorstellung, dass er sich mit Gnollen abgibt ... und sich in der Totenbeschwörung versucht? Undenkbar.\n\nIhr werdet Ihn oben im Turm in der Nähe des Haupttors von Herdweiler finden können. Hoffentlich hat er eine Erklärung für das Ganze. Falls nicht, dann... In jedem Fall solltet Ihr den Magierturm nicht unvorbereitet betreten, {name}.", sourceObjective = "Sprecht mit Magier Bisp im oberen Teil des Magierturms in Herdweiler.", progress = "Hey!", completion = "Ich glaube, wir können seine Aggression als Schuldgeständnis auffassen. Seid Ihr in Ordnung, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[27155] = { id = 27155, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sich stellen", description = "So... Ihr habt also einen Argentumkreuzfahrer getötet, mitten in Herdweiler. Normalerweise wird so was nicht so einfach abgetan, selbst wenn es sich um Selbstverteidigung handelt.\n\nIch schlage vor, Ihr folgt mir nach Burg Mardenholde und stellt Euch Hochlord Fordring. Wenn Ihr Glück habt, wird er Euch anhören und Verständnis für Eure Situation zeigen. Ich hoffe, ich habe Euch nicht in Schwierigkeiten gebracht.", sourceObjective = "Meldet Euch bei Hochlord Tirion Fordring in Herdweiler in den Westlichen Pestländern.", completion = "Mir sind Eure Taten bekannt, {name}. Ich heiße Euch in meiner Stadt willkommen, gebe Euch meinen Segen und was macht Ihr?\n\nIhr tötet den Verräter, den wir schon seit Wochen jagen. Gut gemacht. Euer Heldenmut erblüht viel früher, als ich erwartet hatte.", sourceObjectiveStatus = "unverified-source-field" }
quests[27156] = { id = 27156, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es wird langsam Zeit!", description = "Endlich! Ihr seid hier! Fangt mit der Arbeit an!\n\nMeine Männer haben schon zu lange nur mit diesen hölzernen Trainingsattrappen gekämpft. Sicherlich lässt sich das Schwingen eines Schwertes auch mit einer Trainingsattrappe erlernen, doch für den Kampf bedarf es eines echten Kämpfers.\n\nHmmm... Ich hatte ausdrücklich nach jemand mit einer eindrucksvollen Statur gefragt, aber in diesem Fall muss wohl <ein/eine:r> {race} mit dünnen Ärmchen herhalten.\n\nKommt her und zeigt meinen Männern, wie man kämpft!", sourceObjective = "Fordert 7 Lehrlinge von Herdweiler zum Kampf heraus und besiegt sie.", completion = "Ich sehe gerade meine Unterlagen durch, und hier steht, dass ein {race} hier eintreffen soll. Ihr seht nicht gerade aus wie, ähm ...\n\n\n\nEgal. Es scheint, als wärt Ihr nicht die Person, die ich ursprünglich beauftragt hatte, aber Ihr habt gute Arbeit geleistet. Ich werde Euch also bezahlen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27157] = { id = 27157, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Akkordarbeiter... <Seufz>", description = "Oh, mir ist Euer Name entgangen. {name}? Es freut mich, Eure Bekanntschaft zu schließen, {name}.\n\nIch habe noch ein anderes Problem, bei dem ich Hilfe gebrauchen könnte, und Ihr habt etwas an Euch, dass gerade danach schreit, nach Hilfe gefragt zu werden.\n\nAm nördlichen Rand von Herdweiler ist eine kleine Mine, aus der wir den Großteil des für unsere Stadt benötigten Erz beziehen. Die Akkordarbeiter in der Mine verrichten normalerweise gute Arbeit.\n\nAllerdings scheint es leider, als habe eine überdurchschnittlich große Spinne sich in der Höhle häuslich eingerichtet. Meint Ihr, Ihr könnt Euch der Sache annehmen?", sourceObjective = "Tötet Shadril in der Mine in Herdweiler.", completion = "Gute Arbeit! Wenn ich zurückblicke, bin ich fast froh, dass dieser andere {class} nicht aufgetaucht ist ... Ihr habt Euch als Lösung all meiner Probleme herausgestellt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27158] = { id = 27158, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht um Andorhal", description = "Beeilt Euch, {name}... es gilt, keine Zeit zu verlieren.\n\nDie Stadt Andorhal befindet sich inmitten eines Krieges zwischen den Verlassenen, der Allianz und der Geißel. König Wrynn hat den Stein ins Rollen gebracht und einen Todesritter geschickt, um den Angriff in die Wege zu leiten. Ich bin aber sicher, dass er alle Hilfe brauchen wird, die er kriegen kann. Mit dem Tod von Arthas ist die Zeit für die Allianz gekommen, Lordaeron zurückzuerobern.\n\nMeldet Euch bei Greifenmeister Bibilfaz Federpfiff, wenn Ihr bereit seid, und er wird Euch mit dem nächsten Greifen losschicken.", sourceObjective = "Meldet Euch bei Thassarian in Andorhal in den Westlichen Pestländern.", completion = "Endlich seid Ihr hier, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27159] = { id = 27159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erst die Geißel ... dann die Horde", description = "Dunkelmeister Gandling vom Kult der Verdammten führt die Offensive der Geißel hier in Andorhal an. Mein ehemaliger Mitstreiter Koltira leitet die Streitkräfte der Verlassenen. Um Andorhal einzunehmen, müssen wir beide Streitmächte besiegen. Eine Niederlage ist gewiss, wenn wir versuchen, uns beiden auf einmal zu stellen.\n\nIch kenne Koltira gut genug, um zu wissen, dass er sich zuerst auf die Geißel konzentrieren wird. Wir werden es ihm gleichtun.\n\nSetzt die schwächeren, vertrockneten Geißeldiener außer Gefecht, um ihre Zahlen zu schwächen. Die Verlassenen werden darauf warten müssen, unseren Zorn zu spüren.", sourceObjective = "Tötet 15 ausgedörrte Geißeldiener in Andorhal.", completion = "Ihr reagiert zwar nicht schnell, doch immerhin enttäuscht Ihr mich nicht.\n\nNun gut. Ich werde eine noch wichtigere Aufgabe für Euch haben, {name}, wenn die Zeit reif ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[27160] = { id = 27160, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kriegsmaschinen", description = "Vertrocknete Geißel... schwach. Monstrositäten... stark.\n\nWir besiegen starke Monstrositäten... wir gewinnen Krieg.", sourceObjective = "Zerstört 6 aufgeschlitzte Ungetüme in Andorhal.", completion = "Monstrositäten ... stark.\n\n{name} ... stärker.", sourceObjectiveStatus = "unverified-source-field" }
quests[27161] = { id = 27161, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der unendliche Fluss", description = "Araj der Beschwörer verstärkt die Verteidigung der Geißel mit einfachen Skeletten ... eine Armee von Schwächlingen, die Euch eher überrennen als überwältigen wird. Er hat Animi in den nördlichen Türmen Andorhals versammelt, die diese Skelette in einer erschreckenden Geschwindigkeit hervorrufen können. Ich habe aber eine Lösung!\n\n<Lang reicht Euch ein paar Granaten.>\n\nIhre Funktion ist einfach. Wenn diese Granaten auf einen Knochenanimus - oder in unserem Fall einen Haufen Skelette - geworfen werden, wird nicht mehr als Splitter von ihnen übrig bleiben.", sourceObjective = "Benutzt Langs Handgranaten und tötet 5 Berserker der Klapperknochen und zerstört einen Knochenanimus der Geißel.", progress = "Ich kenne das Geräusch, das diese Dinger bei der Explosion machen ... und ich habe das Geräusch noch nicht gehört. Geht zurück an die Arbeit, {name}.", completion = "Diese Granaten sind Sprengstoff, mehr nicht. Ich bin zwar kein Gobliningenieur ... aber ich weiß, dass es sehr nützlich sein kann, ab und an mal Sachen in die Luft zu sprengen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27162] = { id = 27162, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scholomancer", description = "Scholomance ist eine der letzten verbleibenden Bastionen der Geißel im Westen des Thondroril. Der Direktor von Scholomance, ein Kultist namens Dunkelmeister Gandling, ist auf dem Schlachtfeld erschienen.\n\nDas wird der letzte Fehler sein, der ihm unterläuft.\n\nIhr werdet Gandling auf einem Platz in der Nähe des südlichen Stadtrands finden. Ich möchte, dass Ihr mit Gandling kämpft und ihn schwächt. Ich werde Euch beistehen, damit er sein Ende findet.", sourceObjective = "Tötet Dunkelmeister Gandling in Andorhal.", completion = "Ausgezeichnete Arbeit, {name}. Jetzt, da der Anführer der Streitmächte der Geißel nicht länger in Andorhal sein Unwesen treibt, müssen wir den richtigen Augenblick abwarten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27163] = { id = 27163, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rohe Gewalt", description = "Gandling hat seinen Leutnant Blutrippe zur Unterstützung mitgebracht. Dieser rasselnde Schrecken ist viel gefährlicher als jede andere Geißel und Monstrosität, die Euch auf dem Schlachtfeld begegnen wird.\n\nBlutrippe befindet sich im alten Rathaus, in der Nähe der Stadtmitte. Ich empfehle Umsicht, bevor Ihr mit ihm kämpft, {name}. Er ist kein leichter Gegner.", sourceObjective = "Tötet Blutrippe in Andorhal.", completion = "Ausgezeichnete Arbeit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27164] = { id = 27164, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Araj der Beschwörer", description = "Nun da der Animus besiegt ist, ist der nächste logische Schritt die Auslöschung Arajs und der Erhalt einer Scherbe seines Phylakteriums. Ihr habt ihn wahrscheinlich schon am Brunnen in der Stadtmitte herumlümmeln sehen.\n\nNehmt meine Granaten mit. Sie werden Araj keinen Schaden zufügen, aber Ihr könnt sie benutzen, wenn er auf die Idee kommt, Skelette zu beschwören, und diese damit in die Luft jagen. Ihr wisst ja, wie das geht.", sourceObjective = "Tötet Araj den Beschwörer. Ihr könnt Langs Handgranaten benutzen, um die Berserker der Klapperknochen zu zerstören.", progress = "Araj ist ein ausgezeichneter Gegner. Ihr solltet gut vorbereitet sein.", completion = "Araj ist tot... das ist gut. Dieser Gnom hat bei unserem Sieg eine Rolle gespielt. Und Ihr auch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27165] = { id = 27165, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sieg, im Moment", description = "Die Allianz hat gesiegt und unsere Streitmächte sind noch immer stark. Im Rahmen unserer Kriegsplanung müssen wir die Verlassenen jetzt angreifen, da sie sich noch vom Kampf erholen und nicht mit einem Angriff rechnen. Ich habe allerdings ein Abkommen geschlossen...\n\nWir werden warten. Wir greifen Koltira und seine Truppen an, wenn der richtige Zeitpunkt gekommen ist. Sprecht in der Zwischenzeit mit Ginny Siegesfroh und begebt Euch zum Zugwindlager südlich von hier. Kommandant Ashlam Ehrenschlag wird Euch über Eure nächste Aufgabe unterrichten.\n\nVon mir werdet Ihr wieder hören, sobald Ihr in Andorhal gebraucht werdet.", sourceObjective = "Meldet Euch bei Kommandant Ashlam Ehrenschlag in Zugwindlager in den Westlichen Pestländern.", completion = "Die Neuigkeiten erreichten uns kurz vor Euch, {name}. Dass die Geißel aus Andorhal vertrieben wurde, bedeutet, dass wir der Rückeroberung von Lordaeron einen Schritt näher gekommen sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[27166] = { id = 27166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pfeile machen!", description = "Wir müssen immer auf den Kampf vorbereitet sein, {name}. Ob dieser Kampf gegen die Verlassenen in Andorhal, gegen die Geißel im Osten, oder gegen einen noch unbekannten Feind ausgetragen wird, steht noch in der Zukunft geschrieben. Wir wissen nur, dass wir bereit sein müssen.\n\nUns gehen die Pfeile aus. Ich kann Schäfte und Pfeilspitzen besorgen, aber ich benötige Federn. Die Vögel, die nordwestlich von hier kreisen, sind zu dieser Jahreszeit normalerweise in der Mauser. Könntet Ihr Euch dorthin begeben und für unser Lager einige dieser Federn sammeln?", sourceObjective = "Erhaltet 9 Braunfederkiele.", progress = "Es ist gut, Euch wieder zu sehen, {name}.", completion = "Meine Pfeilmacher werden sich gleich an die Arbeit machen.\n\nEs ist gut zu sehen, dass Ihr Euch so nützlich macht, {name}. Vielleicht habe ich später noch aufregendere Aufgaben für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[27167] = { id = 27167, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magenknurren", description = "Ich komme aus Westfall, weit im Süden. Auch diese Männer, die mit mir reisen, sind von dort. Wir sind nicht mehr als Bauersleute.\n\nMir wurde gesagt, dass Lordaeron geheilt wurde und der Boden bestellt werden kann. Dieser \"Kommandant\" meint jetzt allerdings, dass es zu gefährlich ist, diese Arbeit vorzunehmen. Er meint, es tobe ein Krieg, und dass die Pestländer noch nicht geheilt sind.\n\nWie dem auch sei, was ich wirklich brauche, ist Essen in den Mägen meiner Männer. Es ist egal, was. Es scheint, als seien Bären hier reichlich vorhanden.", sourceObjective = "Beschafft Euch 5 Stücke Bärenfleisch von struppigen Schwarzbären in den Westlichen Pestländern.", progress = "Wir haben eine weite Reise hinter uns. Jeder Bissen, den Ihr übrig habt, ist eine Wohltat für uns.", completion = "Ihr jagt, wie nur ein echter {class} jagen kann. Selbst wenn wir unsere Behausungen noch nicht errichten können, so haben wir wenigstens etwas zu essen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27168] = { id = 27168, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer nicht loslassen kann", description = "Trauerhügel nordöstlich von hier war einer der ersten Orte, den die Argentumkreuzfahrer und der Zirkel des Cenarius heilen konnten. Dieses Gebiet ist nun von der Geißel befreit.\n\nAllerdings finden sich dort immer noch Schreckgespenster der Vergangenheit, die aus irgendwelchen Gründen den Weltenübergang nicht vollbracht haben. Vielleicht trauern sie, oder sie haben noch eine Aufgabe zu erledigen... oder sie haben sich einfach nur verirrt.\n\nNehmt mein Weihrauchfass und läutert sie mit dem heiligen Weihrauch. Auf die eine oder andere Weise wird ihnen das beim Weltenübergang helfen.", sourceObjective = "Benutzt das Heilige Weihrauchfass bei 12 zurückgezogenen Geistern in Trauerhügel, und tötet sie, falls ihre Reaktion dies verlangt.", completion = "Ich hoffe, dass den meisten der Übergang in Frieden gelungen ist. Ich danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27169] = { id = 27169, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uthers Segen", description = "Diese Bauern aus dem Süden wollen sich der Bauernhöfe annehmen, aber ich kann nicht zulassen, dass sie die Pestländer unvorbereitet betreten. Auch jetzt, wo die Geißel nicht mehr hier ist, lauert immer noch Gefahr - durch die Verlassenen. Nein, wir müssen bereit sein, zu kämpfen, und das schließt unsere Besucher ein.\n\nBevor wir irgendetwas anderes tun, würde ich allerdings vorschlagen, dass Ihr nach Osten zu Uthers Grabmal reist und diesen Tribut vor seiner Statue niederlegt, um seinen Segen zu erbitten. Sprecht danach mit dem Priester, der sich um das Grabmal kümmert.", sourceObjective = "Begebt Euch zu Uthers Grabmal und verwendet den Eiswindtribut vor seiner Statue.", progress = "Uther war ein wahrer Held. Es ist mir eine Ehre, ihm zu dienen, nach allem, was er erlitten hat.", completion = "Ihr und die Menschen von Zugwindlager möchtet Andorhal zurückerlangen? Ich wünsche Euch viel Glück.", sourceObjectiveStatus = "unverified-source-field" }
quests[27170] = { id = 27170, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die verlassene Gruft", description = "Wenn Ihr die Schlacht um Andorhal wirklich vorantreiben möchtet, kann ich Euch vielleicht helfen.\n\nÖstlich von hier befindet sich eine große Gruft. Der untere Teil der Gruft wurde einst für die Aufbewahrung von Waffen und Rüstung benutzt - bis die Geißel kam. Jetzt, da die Untoten nicht mehr hier sind, können diese Waffen benutzt werden.\n\nDie meisten Waffen sind wohl rostig und alt, aber trotzdem besser für unsere Zwecke geeignet als Tuniken und Heugabeln.", sourceObjective = "Findet die Waffenkiste unten in der Gruft in den Westlichen Pestländern.", completion = "Auf der untersten Ebene der Gruft findet Ihr zerstörte Kisten am Boden verstreut, in denen sich einst Waffen und Rüstung befanden.\n\nJemand scheint Euch zuvorgekommen zu sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[27171] = { id = 27171, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinterhalt!", description = "Als Ihr Euch umdreht, seht Ihr die Silhoutten der torkelnden Skelette auf den Stufen.\n\nDie Untoten haben die Gruft nicht verlassen. Sie haben hier gewartet! Außerdem scheinen sie die Waffen zu tragen, wegen denen Ihr hier seid.\n\nIhr müsst aus der Gruft fliehen. Versucht, auf dem Weg nach draußen so viel Ausrüstung wie möglich zu ergattern.", sourceObjective = "Erhaltet 4 abgenutzte Brustplatten und 4 verrostete Schwerter.", progress = "Was ist an Uthers Grabmal passiert, {name}?", completion = "Von Geistern angegriffen? Das ist seltsam. Die Gruft wurde wohl doch nicht vollständig geheilt.\n\nIhr habt gerade Thurman Grant verpasst - Ihr wisst schon, der Bauerntrampel, der vorhin schon mal hier war. Er hat seine Männer zusammengerufen und hat sich mit ihnen zum nächsten Bauernhof aufgemacht ... gegen meinen Befehl.", sourceObjectiveStatus = "unverified-source-field" }
quests[27172] = { id = 27172, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Trostlose Feld", description = "Die Bauern haben sich aufgemacht zum Trostlosen Feld, einem alten Bauernhof nordöstlich von hier, auf der anderen Seite des Flusses. Jemand muss sie im Auge behalten.\n\nBringt ihnen diese rostigen Waffen und die Rüstungen, die Ihr gefunden habt. Wir können nicht zulassen, dass sie mit Heugabeln kämpfen.", sourceObjective = "Bringt die ramponierten Waffen und Rüstungen zu Thurman Grant zum Trostlosen Feld in den Westlichen Pestländern.", progress = "Hat Ehrenschlag Euch geschickt? Dieser Kommandant weiß nicht, wann es genug ist, oder?", completion = "Nun, da Ihr hier seid, werden wir Euch die Rüstungen dankbar abnehmen.\n\nAber die Waffen könnt Ihr behalten. Diese Männer würden nicht wissen, an welchem Ende sie sie halten müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27173] = { id = 27173, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dies ist unsere Armee", description = "Ich habe Kommandant Ehrenschlag darüber unterrichtet, dass wir uns selbst verteidigen können, und das haben wir auch vor. Ich hatte auf meinem Weg hierher ein kurzes Gespräch mit Thassarian, diesem Kriegsherrn der Todesritter. Wir Bauern haben vor, auf unsere eigene Art und Weise zu helfen.\n\nWir werden diesen Bauernhof einnehmen, das Land kultivieren ... und wenn die Schlacht um Andorhal beginnt, werden wir die Verlassenen vom Hinterland aus angreifen. Damit werden sie nicht rechnen.\n\nZuerst müssen wir uns der Vorhut der Verlassenen widmen. Tötet einige von ihnen, und kommt dann wieder zu mir.", sourceObjective = "Tötet 10 Streitkräfte der Vorhut der Verlassenen.", progress = "Meine Männer brauchen Eure Hilfe, {name}.", completion = "Ihr seid gut im Kampf, {race}. Ein erfahrener {class} wie Ihr könnte meinen Männern einige Kniffe beibringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27174] = { id = 27174, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampftraining", description = "Vielleicht könnt Ihr tatsächlich ein paar meiner Männer ausbilden. Ihr habt wahrscheinlich die Monstrosität da draußen bemerkt. Wir haben zuerst versucht, sie zu bekämpfen, aber sie hat sich nicht gewehrt. Es scheint, als ob sie auf dem Bauernhof helfen möchte.\n\nNehmt vier meiner Männer und fordert die Monstrosität zum Kampf heraus. Sie scheint stark zu sein, aber eine Monstrosität gegen fünf von Euch sollte Euch doch Chancen auf einen Sieg geben.", sourceObjective = "Sprecht mit Gory im Trostlosen Feld und fordert ihn zum Kampf heraus.", completion = "Nun können wir die Sache selbst in die Hand nehmen. Ich danke Euch für Eure Hilfe, {name}.\n\nDas nächste Mal, wenn wir uns sehen, werden wir uns wohl im Kampf befinden. Passt solange auf Euch auf. Wir können alle Hilfe gebrauchen, die wir bekommen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[27175] = { id = 27175, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Stätte der Heiler", description = "Die Männer und Frauen in Zugwindlager haben ehrenhafte Ziele, doch letztendlich ist der Krieg ihre Absicht. Ich möchte Euch die Möglichkeit geben, friedlichere Ziele zu verfolgen.\n\nNördlich vom kriegsgebeutelten Andorhal befindet sich die Stätte der Heiler. Der Argentumkreuzzug hat sich dort mit dem Zirkel des Cenarius verbündet. Zusammen arbeiten wir daran, das Land von der Seuche zu heilen, die hier so lange herrschte.\n\nSeid Ihr daran interessiert, Euch unserer Sache zu widmen, {class}?", sourceObjective = "Meldet Euch bei Außenagent Kaartish in der Stätte der Heiler in den Westlichen Pestländern.", completion = "Willkommen, {class}. Wie Ihr sehen könnt, besteht unser Lager aus einer Gemeinschaftsexpedition des Argentumkreuzzugs und Druiden des Zirkels des Cenarius. Wir heißen jedoch alle willkommen, die bei der Heilung des Landes helfen wollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27176] = { id = 27176, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine seltsame Scheibe", description = "Die Gravuren an der Oberfläche dieser Scheibe deuten daraufhin, dass sie uralten Ursprungs ist, und doch zeigt sie keinerlei Anzeichen von Abnutzung.\n\nDas Loch am Rand ist voll mit Holzsplittern, was darauf hindeutet, dass sie dafür vorgesehen war, an einer Art Holzstab angebracht zu werden.\n\nBevor ihr sie Dr. Jones zeigt, solltet Ihr das andere Teil finden.", sourceObjective = "Erhaltet den Stab des Sultans und benutzt die aufwendige Scheibe, um den Schaft der Sterne zu erstellen.", progress = "Ja, {name}?", completion = "<Doktor Jones setzt seine Brille auf.>\n\nLasst uns das genauer betrachten, ja?", sourceObjectiveStatus = "unverified-source-field" }
quests[27177] = { id = 27177, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bergungsaktion", description = "Unsere Flotte wurde durch die Horde und die Naga stark geschwächt. Wir können die Männer, die ihr Leben dem Meer gelassen haben, nicht zurück zum Leben erwecken, aber nur über meine ertrunkene Leiche werde ich zulassen, dass alle unsere Ladungen auf immer verloren gehen.\n\nSchwimmt zum Obsidianbrecher südwestlich von Hochufer und bergt die Ladungen der gesunkenen Schiffe vom Meeresboden.", sourceObjective = "Bergt 8 wiedergefundene Vorräte aus den durchnässten Kisten in Obsidianbrecher.", progress = "Wie viele der Vorräte konntet Ihr bergen?", completion = "Da seht her! Ihr konntet mehr bergen, als ich zu hoffen gewagt hatte. Damit können wir einen ganzen Trupp Marinesoldaten versorgen.\n\nWir haben die Ausrüstung. Wenn wir nun nur irgendwie unseren Kämpfern hier in Hochland Mut machen könnten ...", sourceObjectiveStatus = "unverified-source-field" }
quests[27178] = { id = 27178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verstärkung der Naga", description = "Sie kommen aus der Tiefe des Ozeans angeglitscht, {name}. Die Naga. Ich denke, sie haben vor, die Bastion des Zwielichts zu verstärken, und werden wahrscheinlich den Verrall nutzen, um weiter ins Land vorzudringen. Wir dürfen das nicht geschehen lassen!\n\nZeigt ihnen, dass die Ufer nun die unseren sind, und sorgt dafür, dass sie schnell wieder zurück in die dunklen Tiefen huschen.\n\nTötet die Schwarzschuppen-Naga, die sich ihren Weg durch Obsidianbrecher bahnen!", sourceObjective = "Tötet 10 Myrmidone der Schwarzschuppen oder Seerufer der Schwarzschuppen.", completion = "Das wird ihnen eine Lehre gewesen sein, {name}! Cho'gall wird sich in diesem Kampf nicht auf die Naga verlassen können. Von jetzt an sind wir gegen den Schattenhammer auf uns gestellt.\n\n\n\n... Und gegen die Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[27179] = { id = 27179, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feldarbeit", description = "Dieser bedauernswerte Pygmäe war zur falschen Zeit am falschen Ort.\n\nAls Ihr über sein Unglück sinniert, bemerkt Ihr die Symbole auf seinem Schild. Sie sind viel zu aufwendig für Pygmäengekritzel.\n\nIhr seid davon überzeugt, dass Doktor Jones ein Objekt wie dieses hochinteressant finden wird, und macht Euch auf, um weitere Fragmente wie dieses zu finden.", sourceObjective = "Sammelt 10 uralte Tafelfragmente.", progress = "Was haben wir denn hier, mein Freund?", completion = "Diese Tafeln sind übersäht mit titanischen Schriftzeichen. Hier steht noch Unbekanntes geschrieben, {name}!\n\nFehlende Teile eines uralten Rätsels...\n\nGute Arbeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[27180] = { id = 27180, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehret die Toten", description = "Ein Konvoi erfahrener Truppen und Katapulte der Verlassenen wurden heute aus dem Hinterhalt angegriffen, als sie Olsens Acker südlich von hier überqueren wollten. Ein Totalschaden: alle Einheiten wurden getötet und alle Katapulte vernichtet.\n\nDas Rudel von Blutfang ist für den Hinterhalt verantwortlich, allerdings sind sie wohl längst wieder in die Hügel geflüchtet, um sich auf ihren nächsten feigen Angriff vorzubereiten. Ihre Zeit wird kommen. Jetzt allerdings möchte ich, dass Ihr zu Olsens Acker geht und die Gefallenen ehrt.\n\nFindet die Insignien der Verlassenen.", sourceObjective = "Findet 6 Insignien der Verlassenen bei den Leichnamen der Veteranengardisten der Verlassenen.", progress = "Konntet Ihr die Insignien finden?", completion = "Ich werde mich darum kümmern, dass die Insignien auf der Stelle zurück nach Unterstadt gelangen. Der Registrator wird ihre Namen in unsere Verzeichnisse aufnehmen, so dass ihr Opfer nie in Vergessenheit gerät.", sourceObjectiveStatus = "unverified-source-field" }
quests[27181] = { id = 27181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schmach ein Ende bereiten", description = "Es scheint, als sei ein Teil der Wegelagerer hier geblieben. Lasst sie für diese Anmaßung teuer bezahlen! Tötet die Blutfangpirscher auf Olsens Acker. Für Sylvanas! Für die Horde!", sourceObjective = "Tötet 10 Blutfangpirscher.", sourceObjectiveStatus = "unverified-source-field" }
quests[27182] = { id = 27182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Einsiedler des Hexenhügels", description = "Die Marschen scheinen seltsame Auswirkungen auf die Menschen zu haben. So mancher wurde schon wahnsinnig, nur weil er dort lebte.\n\nJeder, der sich im Irrlichtanwesen niedergelassen hat, wurde auf ganz besondere Weise verrückt. Bei dem jetzigen Besitzer, man nennt ihn \"Sumpfauge\" Jarl, machen sich bereits einige Anzeichen bemerkbar.\n\nIch weiß zwar nicht genau, was dort vor sich geht, aber ich wäre Euch sehr dankbar, wenn Ihr dort nach dem Rechten sehen würdet.\n\nDas Anwesen liegt am östlichen Ende des Sumpfs. Lauft Richtung Osten durch das Blaumoor und vorbei an der Nordwacht. Die Gegend, in der das Anwesen liegt, ist ein verwunschener Flecken und heißt Hexenhügel.", sourceObjective = "Sprecht mit \"Sumpfauge\" Jarl beim Irrlichtanwesen.", completion = "Seid Ihr hierhergekommen, um mich auszuspionieren? Nein?\n\nDann seid Ihr vielleicht ein Liebhaber der guten Küche? Gut, ich kann Eure Hilfe gebrauchen!", sourceObjectiveStatus = "unverified-source-field" }
quests[27183] = { id = 27183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marschenfroschschenkel", description = "Ich koche gerne. Gute Sumpfmannskost. Frittierte Grünfroschschenkel und so.\n\nAber ich habe keine Froschschenkel mehr. Im Irrlichtanwesen wimmelt es aber von Fröschen. Riesige Marschenfrösche. Meint Ihr, Ihr könnt ein paar ihrer Schenkel besorgen? Das ist wirklich nicht viel Arbeit. Ihr müsst ihnen nur auf die Köpfe hauen und mir die Schenkel bringen.\n\nDann mach ich Eintopf, und ess den Eintopf, und Ihr könnt auch Eintopf haben.\n\nMögt Ihr Eintopf?", sourceObjective = "Sammelt 10 Marschenfroschschenkel von riesigen Marschenfröschen.", progress = "Gewürze. Gewürze können niemandem schaden. Oder etwa nicht?", completion = "Ah, hier ist das Gewürz! Das nenne ich einen guten Sumpfeintopf.", sourceObjectiveStatus = "unverified-source-field" }
quests[27184] = { id = 27184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jarl braucht Augen", description = "Augensaft ist ein leckeres Getränk. Leider haben die meisten Tierwesen nur zwei Augen.\n\nAber Spinnen haben eine Menge Augen. Jede Menge. Und Graunebelaugensaft ist lecker. Samtig und salzig! Unzerplatzte Spinnenaugen... Ich schmecke sie schon förmlich.\n\nGraunebelspinnen leben westlich von hier in den Graunebelhöhlen. Glaubt Ihr, die Spinnen wurden nach der Höhle benannt... oder ist es umgekehrt?", sourceObjective = "Sammelt 20 unzerplatzte Graunebelaugen von Graunebelspinnen.", progress = "Wo sind diese Augen?", completion = "Ihr habt die Augen! Ihr habt die Augen! Leckere, leckere Spinnenaugen!\n\nManche Augen... wenn man sie anstarrt, starren sie zurück. Die ess ich zuletzt. Sie leisten einem Gesellschaft... draußen im Sumpf.\n\nHallo, kleine Spinnenaugen. Hallo! Ihr seid so lecker wie Hühnchen. Glibberiges, salziges Hühnchen!\n\nMmmh.", sourceObjectiveStatus = "unverified-source-field" }
quests[27185] = { id = 27185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Wettstreiter ausmerzen", description = "Ich werd' keine Spielchen mit Euch spielen. Der purpurrote Hammerschmied des scharlachroten Kreuzzugs war bisher nicht wirklich erwähnenswert, aber nun, da er zu einem von Balnazzars Auferstandenen geworden ist, hat der Schreckenslord ihm beigebracht, alle möglichen mächtigen und dämonischen Waffen herzustellen.\n\nDie Aufgabe ist einfach. Findet die Schmiedepläne und tötet den purpurroten Hammerschmied, wenn er kommt, um sie zu holen. So können wir sicherstellen, dass ihre Armee die dämonischen Waffen nicht in die Hände bekommt. Sie sind jetzt schon viel zu stark!", sourceObjective = "Tötet den purpurroten Hammerschmied.", completion = "Gut gemacht, mein Freund! Ohne die neuen Waffen sind sie genauso einfach zu töten wie damals, als sie noch lebendig waren!", sourceObjectiveStatus = "unverified-source-field" }
quests[27186] = { id = 27186, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jarl braucht eine Klinge", description = "Ich habe zu schneiden. Ich kann Euch nicht sagen, was ich schneiden werde, aber... Ich brauche eine Klinge. Eine ganz bestimmte Klinge...\n\nManche Leute sprechen von einem Schwert. Ich nenne es eine Schwingklinge.\n\nHelft Ihr mir? Diese Fischmenschen, Murlocs, oder wie auch immer die heißen... Einer von ihnen wird Messerwirbel genannt, hat ständig so ein großes Schwert bei sich, lebt nördlich von hier am Strand. Ich brauche sein Schwert!\n\nAber schlaft nicht noch darüber. Was ich schneide, das hält nicht ewig...", sourceObjective = "Besorgt Messerwirbels Schwert", progress = "Habt Ihr meine Klinge???", completion = "Das ist eine gute Klinge. Sie schwingt gut. Es ist eine gute Schwingklinge. Danke. Danke, danke, danke!!! Jetzt möchte ich sie ausprobieren... \n\nSpäter. Ich probiere sie später aus. Aber wie ich schon sagte... danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[27187] = { id = 27187, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Gefallen für die Welt", description = "Hyänen sind im besten Fall ein Ärgernis.\n\nDiese finsteren Wesen sind bösartig veranlagt, haben alle möglichen Krankheiten und sind nicht mehr als eine Seuche auf dem Antlitz der Hundewelt.\n\nTut der Welt einen Gefallen und befreit die Wüsten von Uldum von dieser räudigen Bedrohung.", sourceObjective = "Tötet 12 räudige Hyänen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27188] = { id = 27188, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was sucht den Hexenhügel heim?", description = "Ich bin hierher gereist, um Jarl in seinem neuen Zuhause zu besuchen, aber seit meiner Ankunft nahm der Schrecken hier kein Ende! Hier stimmt etwas nicht... überhaupt nicht. Ich kann nicht der Einzige sein, der diese Dinge sieht.\n\nHabt Ihr die Geister und Leichname gesehen, die um den Hexenhügel umherstreifen? Wenn einer weiß, was hier vor sich geht, so befürchte ich, dass sie es sind. Haltet nach den auferstandenen Gebeinen und auferstandenen Geistern in der Umgebung Ausschau. Bekämpft sie und gewährt ihnen dadurch ihren verdienten Frieden. Verschafft Euch so viele Informationen wie möglich von ihnen, bevor Jarl dem Bösen vollends verfällt!", sourceObjective = "Sammelt Informationen, indem Ihr 10 auferstandene Gebeine oder auferstandene Geister besiegt.", completion = "<Mordant holt ein kleines Blatt Papier und einen Stift hervor und beginnt, sich Notizen über Eure Berichterstattung zu machen.>\n\nIhr konntet herausfinden, dass sich die Geister an diesem Ort auf die Anzahl aller belaufen, die jemals auf diesem Land gelebt haben, und nicht nur auf die vorherigen Besitzer.\n\nEtwas hat sie zu Grunde gerichtet und getötet. Wer der Sache verfällt, erfährt die Wahrheit nicht, bis es zu spät ist. Wir müssen dem Ganzen ein Ende bereiten, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[27189] = { id = 27189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hexenfluch", description = "In meiner Zeit als Kräuterkundiger habe ich oft feststellen können, dass die Natur stets raffinierte Heilmethoden für die ärgerlichsten Probleme bereithält. Ich habe gelesen, dass die unabhängigen Magier und Hexendoktoren häufig den Rauch einer Pflanze, die als Hexenfluch bekannt ist, verwenden, um das Böse aus seinem Versteck zu locken.\n\nFalls dem wirklich so ist, dann müsste Hexenfluch nahe der seichten Gewässer des Hexenhügels wachsen. Ihr solltet die Pflanze an ihren breiten Blättern und rötlichen Stängeln in der Mitte erkennen. Bringt mir so viele Pflanzen, wie Ihr finden könnt, {name}. Es könnte unsere letzte Hoffnung sein.", sourceObjective = "Sammelt 9 Zweige Hexenfluch am Hexenhügel.", progress = "Konntet Ihr ein paar Pflanzen finden? Wir müssen schnell handeln, bevor das Übel, das hinter dieser Heimsuchung steckt, in dieser Gegend vollends überhand nimmt.", completion = "<Mordant nimmt das Pflanzenbündel von Euch entgegen.>\n\nDiese entsprechen exakt der Beschreibung! Während Eurer Abwesenheit habe ich die Fackel vorbereitet. Jetzt müssen wir die Pflanzen nur noch hier am Ende befestigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27190] = { id = 27190, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reinigung des Hexenhügels", description = "Die Fackel ist fertig. Platziert sie am Ende des Anlegestegs und macht Euch darauf gefasst, allem gegenüberzutreten, was erscheinen mag.\n\nIch habe keine Ahnung, was der Rauch der Fackel enthüllen wird... wenn überhaupt etwas passiert. Ich muss zugeben, dass ich dieser Art der Volksmagie nicht viel Vertrauen schenke, aber wir haben keine Zeit für irgendwas anderes. Jarl zuliebe, und auch Euch zuliebe, wünsche ich Euch viel Glück.", sourceObjective = "Platziert die Hexenfluchfackel am Ende des Anlegstegs und besiegt das Böse, das Hexenhügel heimsucht.", progress = "Ist es vorbei?", completion = "Es hat funktioniert?\n\n<Mordant räuspert sich.>\n\nIch meine ... es hat funktioniert! Jarl und ich stehen in Eurer Schuld, {name}. Das nächste Problem ist nun der Möbelgeschmack meines Freundes, und das wird wohl nicht so einfach zu lösen sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[27191] = { id = 27191, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hungrig wie ein Oger!", description = "Hier trifft man schon ab und an jemanden. Nette Leute. Hab mal einen Oger getroffen. Oger werden hungrig, genau wie ich.\n\nIch werde nie vergessen, was er gesagt hat. Er sagte: \"Patsch großer Oger. Ich hungrig. Geht Fische hauen. Bringt Patsch Essen. Ihr füttert Patsch oder Patsch frisst Euch.\"\n\nIch hab ihm also Fische besorgt, und er hat die Fische gegessen. Und seitdem esse ich auch Fisch. Die Köpfe schmecken am besten, die sind so schön glitschig.\n\nZermalmt die Köpfe nicht. Das macht die Fische unglücklich. Traurige Köpfe schmecken nicht gut. Bringt mir glückliche Fischköpfe, und ich werde die Fischköpfe essen und auch glücklich sein.", sourceObjective = "Sammelt 8 Schlammflossenköpfe von den Murlocs der Schlammflossen.", progress = "Jarl hat Hunger. Genau wie der Oger.", completion = "Ich frag mich, wie es ist, ein Oger zu sein. Große Leute müssen mehr essen.\n\nOger müssen noch hungriger sein als ich. Das klingt wirklich nicht witzig.", sourceObjectiveStatus = "unverified-source-field" }
quests[27192] = { id = 27192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der tolle Ezra Grimm", description = "Männer von weit entfernten Orten wie Kul Tiras sprechen von Ezra Grimms tollem Tabak. Dieses Genussmittel wurde von jeder wichtigen Person, die Stratholme je besuchte, konsumiert. König Terenas, Uther der Lichtbringer, Hochlord Fordring ... ja, alle genossen sie Grimms Spezialität.\n\nLeider verblieb Ezra in seinem Laden, als Stratholme überfallen wurde, und er schwor auf sein Leben, dass die Geißel seinen Tabak nicht anfassen würde. Wagt Euch hinein und seht nach, ob etwas von dem Tabak übriggeblieben ist. Er ist sein Gewicht in Gold wert, das kann ich Euch versichern.", sourceObjective = "Bergt eine Schachtel mit Ezra Grimms tollem Tabak.", progress = "Habt Ihr welchen gefunden?", completion = "Ihr habt wahrhaftig den Schnupftabak, aus dem die Träume sind, entdeckt. Es ist fast unmöglich, den Preis für diesen historischen Tabak festzulegen.\n\nHier, nehmt diese Münzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27193] = { id = 27193, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suchen und zerstören", description = "<Die Stimme der Bansheekönigin dringt erneut in Eure Gedanken ein.>\n\nSucht in den nahegelegenen Bauernhäusern nach Nachzüglern der Allianz. Haltet Eure Augen offen nach Informationen, die uns zu Crowley und Blutfang führen könnten. Sucht und zerstört alle, die sich Euch in den Weg stellen, {name}!", sourceObjective = "Durchsucht die Bauernhäuser auf Olsens Acker.", sourceObjectiveStatus = "unverified-source-field" }
quests[27194] = { id = 27194, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Ecke gedrängt und zermalmt!", description = "<Die Stimme der Bansheekönigin spricht zu Euch.>\n\nWir müssen schnell handeln, {name}. Sie dürfen nicht die Gelegenheit bekommen, zu fliehen. Ich werde ein Geschwader meiner mächtigsten Soldaten zur Tiefenfelsmine schicken. Der Reiter wird sie begleiten, um sicherzustellen, dass alles nach Plan verläuft. Trefft ihn in der Tiefenfelsmine, östlich von Olsens Acker und ZERMALMT diese Ratten.", sourceObjective = "Meldet Euch bei Meister Forteski in der Tiefenfelsmine im Silberwald.", completion = "Ich denke mal, erst in die Enge treiben, dann zermalmen, hm?", sourceObjectiveStatus = "unverified-source-field" }
quests[27195] = { id = 27195, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es gibt keinen Ausweg", description = "Die Herrin hat mich beauftragt, die Bande bei dieser Aufgabe zu führen. Unser Hauptziel ist es, in die Mine einzudringen, die Ratten in die Enge zu treiben und sie alle zu töten, auch Blutfang.\n\nIhr habt uns mit der Beschaffung dieser Informationen gute Dienste geleistet, {name}. Habt am Ruhm teil und helft uns dabei, unsere Schwerter durch ihre elenden Schädel zu jagen.\n\nLasst mich wissen, wenn Ihr bereit seid, und ich werde zum Angriff rufen.", sourceObjective = "Begleitet Meister Forteski durch die Tiefenfelsmine.", completion = "WAS!?\n\n<Fürstin Sylvanas kreischt.>\n\nCROWLEY!!!!!\n\nIhr Bastarde. Das waren einige meiner stärksten Soldaten. Ich habe Crowley und Blutfang zum letzten Mal unterschätzt. Ganz eindeutig handelt es sich hier um Feinde, wie wir sie noch nie zuvor gesehen haben - willens, die eigenen Kämpfer in einer Falle wie dieser zu opfern. Das gab es in der Kriegsführung der Allianz noch nie.", sourceObjectiveStatus = "unverified-source-field" }
quests[27196] = { id = 27196, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Irgendetwas geht vor sich", description = "Ihr habt bemerkenswerte Arbeit geleistet! Vor allem für jemanden, der nie einen meiner Kurse besucht hat.\n\nDiese Tafeln geben uns neue Informationen zu verschiedenen Themen.\n\nSie weisen darauf hin, dass diese Obelisken Teil eines riesigen, uralten Mechanismus sind, der diese Gegend einst vor dem Rest der Welt versteckt hielt.\n\nAußerdem zeigen sie auch auf, wie der Mechanismus wieder in Gang gebracht werden kann. Hier kommt der Schaft der Sterne ins Spiel...\n\nMacht Euch bereit, {name}. Es gilt, Geschichte zu schreiben!", sourceObjective = "Begleitet Harrison Jones zur Kammer der Sterne.", progress = "Also, mal sehen, was dieser Stab uns zeigen kann...", completion = "Das ist aber echt mal ein Ort hier!", sourceObjectiveStatus = "unverified-source-field" }
quests[27197] = { id = 27197, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht geht weiter!", description = "Es gibt Nachrichten aus Andorhal, {name}. Die Schlacht hat wieder angefangen.\n\nUnter den Streitkräften der Allianz ist es wohl bekannt geworden, dass Ihr Euch als einer der Helden der ersten Schlacht um Andorhal hervorgetan habt. Thassarian verlangt umgehend nach Eurer Anwesenheit.", sourceObjective = "Meldet Euch bei Thassarian in Andorhal in den Westlichen Pestländern.", completion = "Es heißt, Ihr hättet den Bauern geholfen, sich zu bewaffnen. Und nun haben Sie ohne meinen Befehl angegriffen! Sie zwingen mich zu handeln.\n\nDie Schlacht geht weiter. Dieses Mal kämpfen wir gegen die Verlassenen... und ich kämpfe gegen Koltira, meinen alten Bruder von der Schwarzen Klinge.", sourceObjectiveStatus = "unverified-source-field" }
quests[27198] = { id = 27198, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Truppen unterstützen", description = "Ich bin kein Militärexperte, aber diese Schlacht scheint zu unseren Gunsten zu stehen. Unsere Verteidiger sind nicht besser als die Todeswachen unserer Gegner, aber die Bauernmiliz hat sie mit dem Angriff aus dem Hinterland überrascht. Für die Allianz!\n\nWir müssen trotzdem alles tun, was in unserer Macht steht, um einen Sieg zu sichern. Reist nach Andorhal östlich von hier und tötet die Todeswachen der Verlassenen, die mit unseren Männern kämpfen. Je schneller sie sterben, umso eher können wir Andorhal wieder unser Eigen nennen!", sourceObjective = "Tötet 15 Todeswachen von Andorhal.", completion = "Ihr habt gut gekämpft, {name}. Ich wünschte, ich hätte Eure Fähigkeiten ... und Euren Mut.", sourceObjectiveStatus = "unverified-source-field" }
quests[27199] = { id = 27199, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Asche zu Asche", description = "Östlich von hier, tief im von den Verlassenen gehaltenen Andorhal, werdet Ihr ihre Kommandanten anfinden. Sie kämpfen nicht, sondern befehligen nur von den Rücken ihrer Pferde.\n\nJagt und tötet diese Kommandanten, {name}. Die Verlassenen werden machtlos sein.", sourceObjective = "Tötet 3 Kriegshauptmänner der Todeswache.", completion = "Gut gemacht. Jetzt, da die Kriegshauptmänner ausgeschaltet wurden, habe ich keine Ausreden mehr.\n\nBald muss ich mich Koltira im Kampf stellen, für Ehre und für Andorhal.", sourceObjectiveStatus = "unverified-source-field" }
quests[27200] = { id = 27200, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sirenenlied", description = "Sie ist immer noch anzutreffen... Ophelia, die Sirene des Hochlands! Ihr schreckliches Lied wird Euch in die Tiefen locken. Ich habe geschworen, hier zu bleiben und meine gefallenen Besatzungsmitglieder zu rächen, {class}. Wenn Ihr mich unterstützen wollt, müsst Ihr nur den Mund aufmachen.\n\nWir werden uns an den Mast binden, oh ja. Wir werden unsere Augen schließen. Wir werden unsere Ohren mit Wachs ausstopfen. Und wenn ihre schöne Illusion vergeht... werden wir angreifen.\n\nKann ich auf Euch zählen?", sourceObjective = "Tötet Ophelia, die Sirene des Hochlands.", completion = "Sie hatte mich in ihrem Zauber, {name}. Ich wäre nicht mit dem Leben davongekommen, wenn Ihr nicht gewesen wärt. Ich danke Euch!\n\nVielleicht kann die restliche Flotte der Allianz hier nun in Frieden vor Anker gehen ...", sourceObjectiveStatus = "unverified-source-field" }
quests[27201] = { id = 27201, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff der Val'kyr", description = "Die Val'kyr waren einst die mächtigste Waffe der Geißel. Sie waren nicht nur fähig im Kampf, sondern konnten auch benutzt werden, um Leichen in Diener der Geißel zu verwandeln. Es fällt mir schwer zu glauben, dass Sylvanas sich um der Verlassenen willen zu solchen Methoden herablässt ... \n\nWir müssen die Val'kyr aufhalten, bevor sie uns ausschalten und unsere Armee gegen uns wenden. Tötet so viele, wie Ihr finden könnt. Nehmt ein paar dieser Freiwilligen mit Euch. Wenn sie bis jetzt überlebt haben, haben sie wohl doch etwas Kampfgeschick.", sourceObjective = "Tötet 9 niedrige Val'kyr in Andorhal.", completion = "Mit jeder Val'kyr, die Ihr tötet, rettet Ihr Dutzende unserer Männer ... und hindert die Streitmächte der Verlassenen daran, weiter zu wachsen.\n\nUnd doch machen sie weiter und weiter. Es kann sein, dass wir diese Schlacht doch nicht gewinnen werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27202] = { id = 27202, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bruder gegen Bruder", description = "Unsere Miliz wurde fast vollständig ausgemerzt. Nur ich und diese paar Bauern sind noch übrig.\n\nDiese beflügelten Kreaturen ... sie haben die Leichen unserer Männer genommen ... und sie in laufende, untote Leichname verwandelt! Mit jedem einzelnen, den sie von uns genommen haben, haben sie ihre eigenen Ränge verstärkt.\n\nEs fällt mir schwer es zuzugeben, aber Ihr werdet auch sie bekämpfen müssen, zusammen mit den Todeswachen und den Val'kyr. Wie sie es auch in ihrem früheren Leben gemacht haben, jagen sie in Gruppen. Nehmt ein paar der Freiwilligen mit Euch.", sourceObjective = "Tötet 20 Reitersoldaten der Verlassenen in Andorhal.", completion = "Ihr habt beherzt gekämpft, aber es bringt uns nichts. Jeder Kämpfer, der fällt, treibt ihre Streitmächte weiter voran.", sourceObjectiveStatus = "unverified-source-field" }
quests[27203] = { id = 27203, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Mahlstrom", description = "Dank den Geistern, dass Ihr hier seid, {name}.\n\nWir wissen nicht, wie lange wir den Riss im Mahlstrom noch erhalten können.\n\nUnsere mächtigsten Mitstreiter, die von Thrall angeführt werden, können den Einriss kaum aufhalten.\n\nDer letzte Stand ist, dass unsere einzige Hoffnung darin liegt, durch die Öffnung zu steigen und zu versuchen, sie von der anderen Seite aus zu stabilisieren.\n\nIch werde ein Portal herbeizaubern. Benutzt es und meldet Euch bei Thrall, so bald Ihr könnt.", sourceObjective = "Geht durch das Portal in den Mahlstrom und sprecht mit Thrall.", completion = "<Thralls Muskeln spannen sich an, als urtümliche Energie ihn durchfließt. Sein Blick gleitet zu Euch, er bemerkt Eure Anwesenheit.>\n\nEs freut mich, Euch zu sehen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27204] = { id = 27204, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aradne", description = "Unsere letzte Hoffnung auf einen Sieg ist die Bezwingung der Val'kyr. Bisher habt Ihr gute Arbeit geleistet... Ihr seid aber auch nur <ein Mann/eine Frau> gegen wortwörtlich Dutzende, die Zerstörung auf das Schlachtfeld bringen.\n\nEine riesige Val'kyr sitzt auf einem Turm südlich von hier... Ihr könnt sie von hier sehen. Wenn wir sie beseitigen, werden die restlichen Val'kyr sich vielleicht zerstreuen.\n\nEs ist unsere einzige Hoffnung. Nehmt ein paar von Grants Männern mit. Ihr werdet für diesen Kampf Schutz benötigen.", sourceObjective = "Tötet Aradne auf dem Turm im westlichen Teil von Andorhal.", completion = "Ich habe Euren Sieg von hier unten verfolgt. Ihr habt gut gekämpft, doch letztendlich war alles umsonst.\n\nDie Val'kyr und die Verlassenen kämpfen weiter und werden uns bald übermannen. Wir haben Andorhal verloren.", sourceObjectiveStatus = "unverified-source-field" }
quests[27205] = { id = 27205, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verderbtheit der Verlassenen", description = "Wir haben diese Schlacht fast gewonnen, {name}. Ich kann den Sieg förmlich schmecken. Die Verlassenen hatten nie ein...\n\nWas zum Teufel ist das!?", sourceObjective = "Findet heraus, was Thassarian anschaut.", completion = "Val'kyr? Koltira hat Val'kyr zu diesem Kampf mitgebracht? Ist er verrückt geworden?\n\nNein, das ist nicht Koltiras Werk. Das war Sylvanas.", sourceObjectiveStatus = "unverified-source-field" }
quests[27206] = { id = 27206, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weh dir, Andorhal", description = "Begebt Euch nach Süden, nach Zugwindlager. Berichtet Kommandant Ashlam Ehrenschlag von allem, was hier vorgefallen ist.\n\nIch? Ich gehe nach Westen, nach Tirisfal.\n\nMeine Schlacht ist noch nicht abgeschlossen. Ich habe ein Treffen mit einer Harpyie, die sich die Bansheekönigin nennt ... und ich werde herausfinden, was sie Koltira angetan hat.", sourceObjective = "Berichtet Kommandant Ashlam Ehrenschlag von den Ereignissen der Schlacht von Andorhal.", completion = "Verloren? Nein... als Nächstes werden sie sich dann wohl Zugwind vornehmen. Das war ein schwerer strategischer Rückschlag für die Pläne der Allianz in Lordaeron.\n\nNun gut. Ich werde das Ergebnis dieser Schlacht König Wrynn melden. Er wird wohl nicht gerade glücklich darüber sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[27208] = { id = 27208, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schreckenslord Balnazzar", description = "Mit dem Untergang des Scharlachroten Kreuzzugs entließ der getarnte dämonische Anführer Balnazzar den besessenen Körper des Obersten Kreuzfahrers Dathrohan und begab sich auf einen Amoklauf, bei dem er auch den letzten überlebenden Kreuzfahrer in den Tod riss. Dann nutzte er seine nekromantischen Kräfte, um sie zu widerwärtigen untoten Sklaven zu machen.\n\nBalnazzar nennt diese neue Armee die Auferstandenen. Wir können nicht zulassen, dass diese Armee noch größer wird. Diese Krieger sind äußerst mächtig, und im Gegensatz zu Arthas' Geißel wird Balnazzar seine Streitmächte nicht zurückhalten. Tötet ihn, solange wir noch in der Lage dazu sind, {class}.", sourceObjective = "Tötet Balnazzar.", completion = "Es ist gut, dass wir Balnazzar fürs Erste aufhalten konnten. Es wird nicht mehr lange dauern, bis seine Armee ganz Stratholme eingenommen hat, und ihm so ein mächtiges Herzstück für sein neues, unheiliges Reich bietet.", sourceObjectiveStatus = "unverified-source-field" }
quests[27210] = { id = 27210, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verräter unter uns", description = "Schön, Euch zu sehen, {class}. Ich bin nach Theramore gekommen, um bei der Lösung des Problems mit den Deserteuren zu helfen. Einige der Männer haben nicht nur ihren Posten verlassen, nein, sie haben sich zurück in die Stadt geschlichen.\n\nDiese Agenten der Deserteure verbreiten Lügen und Propaganda. Sie erhoffen sich davon, andere von ihrer Sache zu überzeugen, damit sie sich ihnen anschließen.\n\nSie sind nahezu bei jedem Wachposten der Stadt und bei den Docks. Findet sie, entlarvt sie und diskreditiert sie. Im Moment würde alles andere nur dazu führen, dass sie an Sympathie gewinnen.", sourceObjective = "Konfrontiert 5 Aufwiegler der Deserteure in Theramore.", completion = "Gut gemacht, {name}. Ich glaube, wir haben sie überrascht. Ihre Agenten wähnten sich innerhalb der Stadt vermutlich in Sicherheit.\n\nMit der Zeit werden die Aufwiegler zurückkehren und ihre Lügen wieder verbreiten. Wir werden die Zeit, die Ihr uns verschafft habt, nutzen, um die Deserteure weiter auszusperren.", sourceObjectiveStatus = "unverified-source-field" }
quests[27211] = { id = 27211, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Propagandakrieg", description = "Die Agenten der Deserteure haben weitaus mehr getan, als nur die Wachen zu beschwatzen. Wir haben eine Reihe von Handzetteln gefunden, die die Deserteure offenbar auf einem Schiff zu den Docks geschmuggelt haben.\n\nDas Schiff, auf dem die Handzettel geladen waren, liegt noch immer in Theramore bei dem am weitesten entfernten Dock vor Anker. Wenn Ihr Euch heimlich an Bord schleichen und das restliche Propagandamaterial in Beschlag nehmen könntet, würden die Agenten ihre wichtigste Waffe verlieren. Seid auf der Hut! Das Schiff ist mit erfahrenen Freibeutern bemannt und die Fracht befindet sich womöglich in der Kajüte des Kapitäns.", sourceObjective = "Erhaltet das Propagandamaterial der Deserteure vom Schiff am Ende der Docks in Theramore.", progress = "Konntet Ihr die restlichen Propagandahandzettel finden und beschlagnahmen?", completion = "<Die SI:7-Agentin nickt zustimmend.>\n\nAusgezeichnet. Jetzt müssen wir die Deserteure nur noch diskreditieren, damit sie in Theramore nie wieder Fuß fassen können. Ich weiß auch schon wie.", sourceObjectiveStatus = "unverified-source-field" }
quests[27212] = { id = 27212, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diskreditierung der Deserteure", description = "Ich habe die Handzettel, die Ihr den Söldnerkumpanen der Deserteure beim Dock abgenommen habt, verfälscht. Jeder, der diese Zettel jetzt lesen wird, erhält mit Sicherheit einen ganz anderen Eindruck von den Deserteuren und ihren Absichten.\n\nWenn wir genug davon an die Wachen verteilen, wird es den Deserteuren einfach zu peinlich sein, hier jemals wieder Fuß zu fassen.\n\n<Calia überreicht Euch einen Stapel verfälschte Handzettel.>\n\nFangt doch schon einmal an, während ich den nächsten Schritt plane.", sourceObjective = "Verteilt verfälschte Handzettel an 6 Wachen von Theramore.", progress = "Ich dachte, ich hätte Gelächter bei den Kasernen gehört. Habt Ihr die Handzettel verteilt, die ich Euch gegeben habe?", completion = "<Calia kichert, als Ihr von der Reaktion der Wachen auf das Propagandamaterial berichtet.>\n\nGenau wie ich gehofft hatte! Ich bin mir sicher, dass jeder Agent der Deserteure, der versucht Theramore zu infiltrieren, sofort ausgelacht wird!", sourceObjectiveStatus = "unverified-source-field" }
quests[27213] = { id = 27213, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ende der Deserteure", description = "Jetzt, da wir die Deserteure aus Theramore vertrieben haben, ist es an der Zeit, unseren Plan zu Ende zu bringen. Meine Kontakte vor Ort haben mir berichtet, dass die Operationsbasis der Deserteure ein Schiff ist, das bei einer kleinen Insel südöstlich der Docks vor Anker liegt.\n\nDie Festnahme ihres Anführers, Gavis Grauschild, wird die anderen entmutigen. Macht ihn innerhalb des Schiffs ausfindig und überzeugt ihn davon, zu kapitulieren. Es würde mich nicht überraschen, wenn er sich mit einem spektakulären Kampf zur Wehr setzt, aber aufgibt, sobald er verstanden hat, dass er nicht gewinnen kann.", sourceObjective = "Besiegt Gavis Grauschild auf dem Schiff südöstlich von Theramore.", completion = "Gavis' Forderung ist nicht so haarsträubend wie sie scheint. Wenn man sie richtig behandelt, gelingt es Lady Jaina vielleicht sogar die Deserteure wieder in unsere Gemeinschaft zu integrieren. Doch diese Entscheidung obliegt alleine ihr.\n\nEs war mir eine große Freude mit Euch zu arbeiten, {name}! Ohne Eure Hilfe wäre die gesamte Operation sicherlich nicht halb so glatt gelaufen. Ich werde Euch in meinem Bericht an Sturmwind lobend erwähnen, so dass alle wissen, dass es Euer Einsatz war, der der Bedrohung durch die Deserteure ein Ende gesetzt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[27214] = { id = 27214, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beunruhigende Berichte", description = "Unsere Spähpatrouillen haben in letzter Zeit Beunruhigendes zu Tage gefördert. Sie berichten von Männern mit roten Kopftüchern der Defias, die entlang der Schreckensmoorküste nördlich von Theramore umherwandern.\n\nWrackteile in dieser Gegend lassen darauf schließen, dass es sich um Überlebende eines Schiffbruchs handelt, aber uns mangelt es an Informationen. Hauptmann Wymor bei der Späherwacht, einem Wachturm nördlich der Stadt, sucht nach einem Helfer, der diesen Berichten nachgeht.", sourceObjective = "Erstattet Hauptmann Wymor bei der Späherwacht Bericht.", completion = "<Der Hauptmann versucht ganz offensichtlich Eure Fähigkeiten einzuschätzen.>\n\nIhr habt also von dem Schiffswrack an der Küste gehört? Gut, ich könnte noch etwas Hilfe gebrauchen, um meinen Verdacht gegenüber den Überlebenden zu bestätigen. Willkommen an Bord, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27215] = { id = 27215, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Einsiedler beim Irrlichtanwesen", description = "Es gibt da einen Burschen - die Einheimischen nennen ihn \"Sumpfauge\" Jarl - der alleine draußen im Sumpf lebt. Vor nicht allzu langer Zeit hat er sich im Irrlichtanwesen einquartiert, nachdem die vorherigen Bewohner unter geheimnisvollen Umständen verschwunden sind.\n\nVon Zeit zu Zeit schicke ich jemanden aus, um dort nach dem Rechten zu sehen. Wisst Ihr, irgendwie erinnert er mich an meinen Großvater. Manche sagen, dass er nicht alle Tassen im Schrank hat.\n\nFolgt der Straße von Theramore aus in Richtung Nordwesten, und Ihr werdet das Irrlichtanwesen am Hexenhügel finden, bevor die Straße in Richtung Westen abbiegt.", sourceObjective = "Sprecht mit \"Sumpfauge\" Jarl im Irrlichtanwesen.", completion = "Runter von meinem Rasen! Es sei denn, Ihr möchtet dem alten Sumpfauge ein bisschen beim Kochen helfen. Was meint Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[27216] = { id = 27216, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der alte Leuchtturm", description = "Der alte Leuchtturm östlich von hier ist schon seit Langem nicht mehr funktionstüchtig. Babs Zischeldrill hat es sich allerdings in den Kopf gesetzt, ihn wieder zum Laufen zu bringen.\n\nIch weiß zwar nicht, wie sie das alleine bewerkstelligen will, aber sie behauptet, dass die Schiffe und ihre Fracht dann reibungsloser zu den Docks gelangen werden. Was kann ich dagegen schon einwenden? Man sollte sich nicht über die Arbeit auf den Docks beschweren, wenn man bedenkt, dass man genauso gut an vorderster Front stehen könnte, oder?", sourceObjective = "Sprecht mit Babs Zischeldrill am Leuchtturm auf der Insel östlich von Theramore.", completion = "Gut. Ich kann jegliche Hilfe gebrauchen. Das Wichtigste ist, die Lampe wieder zu entzünden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27217] = { id = 27217, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drescheröl", description = "Im alten Logbuch des Leuchtturms steht, dass die Lampe mit dem Öl von Dreschern, die entlang der Küste hier leben, betrieben wurde.\n\n<Babs rümpft bei der Erwähnung dieser veralteten Technologie ihre Nase.>\n\nIch vermute, dass es sich hierbei um eine praktische, wenn auch weniger elegante Lösung handelt. Im Logbuch wurde vermerkt, dass das Öl von jungen Düsterdreschern am besten funktioniert. Sie sind unterhalb der Docks von Theramore zu finden.\n\nWürdet Ihr mir helfen, den Leuchtturm wieder mit Öl zu versorgen?", sourceObjective = "Sammelt 4 Behälter mit Drescheröl von den Düsterdreschern unter den Docks von Theramore.", progress = "Konntet Ihr das Drescheröl bekommen?", completion = "Ich habe immer noch meine Zweifel, aber momentan ist das die einzige Lösung. Sobald wir sie zum Laufen gebracht haben, werden wir sicherlich die Zeit finden, um die Lampe auch anderweitig mit Energie zu versorgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27218] = { id = 27218, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heimtückische Bewohner der Tiefe", description = "Wisst Ihr was? Es ist erstaunlich, was man alles in diesem alten Leuchtturm finden kann. Nachdem ich die Lampe angezündet hatte, bemerkte ich dieses Buch in einem dieser alten Koffer da oben.\n\n<Babs hält das Buch in die Höhe und liest den Titel mit lauter und dramatischer Stimme vor.>\n\n\"Heimtückische Bewohner der Tiefe!\"\n\nBeim Anblick einer dieser Bestien wäre ich bestimmt in Ohnmacht gefallen! Sicherlich ist es den einen oder anderen Lacher wert, aber mir fehlt momentan einfach die Zeit zum Lesen.\n\nIch kenne da aber jemanden, dem diese Lektüre gefallen könnte... der alte Fischhändler bei den Docks, Michael \"Schmutz\" Fink. Er sammelt alte Bücher.", sourceObjective = "Bringt das Buch \"Heimtückische Bewohner der Tiefe\" zu Michael \"Schmutz\" Fink bei den Docks von Theramore.", progress = "Was darf es heute sein? Der Barsch ist ausgezeichnet.", completion = "Nun ja, mir dieses Buch zukommen zu lassen, war ganz schön aufmerksam von der alten Babs. Ich weiß nicht, ob Ihr ein wenig darin geblättert habt, aber in den Geschichten steckt schon die ein oder andere Wahrheit. Seefahrer erfinden so was nicht einfach, versteht Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[27219] = { id = 27219, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ist das wahr?", description = "Oh, ich bin mir sicher, dass Ihr und Babs bei einigen der haarsträubenden Beschreibungen und Zeichnungen im Buch laut lachen musstet. Aber habt Ihr Euch auch mal überlegt, dass an diesen Legenden etwas Wahres dran sein könnte?\n\nWenn Ihr gut genug aufpasst, dann könnt Ihr die Seefahrer mit Sicherheit noch über Tethyr reden hören, die Meereskreatur, die laut dem Buch genau hier lebt! Wenn Ihr sicher gehen wollt, dann könnt Ihr natürlich den alten Nat Pagle fragen.\n\nIhr findet ihn bei seinem Angelplatz auf einer kleinen Insel in Tidenbucht, südwestlich jenseits der Bucht der Düstermarschen.", sourceObjective = "Sprecht mit Nat Pagle bei Nats Angelplatz in Düstermarschen.", completion = "Ihr wollt also mehr über Meeresungeheuer erfahren? Hmm ... also, ich mache Euch einen Vorschlag. Es wird aber viel Alkohol im Spiel sein und für Euch könnte es ein bisschen peinlich werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27220] = { id = 27220, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nats Abmachung", description = "Ihr habt also eine Kopie von \"Heimtückische Bewohner der Tiefe\", ist das so? Nun, aus meiner Erfahrung heraus kann ich Euch sagen, dass alles wahr ist. Ich habe sogar ein paar dieser Biester mit meinen eigenen Augen gesehen.\n\nIhr wollt aber etwas über Tethyr erfahren. Ich sagte ja bereits, dass ich Euch ein Angebot machen würde, also hört gut zu. Ich arbeite an einer neuen Art von Köder, habe diesen hier aber noch nicht getestet.\n\nNehmt diese Paste - ja, sie stinkt etwas faulig - beschmiert Euch damit selbst und schwimmt rüber zu dem Schiffswrack im Südwesten. Solltet Ihr überleben, dann lasst mich wissen, wie es war!", sourceObjective = "Schmiert Euch mit Pagles Fischpaste, extra stark ein und schwimmt dann hinaus in die Tidenbucht.", progress = "Nicht vergessen, kommt erst zurück, wenn Euch etwas gebissen hat!", completion = "Nicht schlecht. An Eurer Stelle würde ich allerdings so schnell wie möglich ein Bad nehmen.\n\nJetzt zu Eurem Meeresungeheuer...\n\nNehmt Euch ruhig ein Bier oder zwei, während ich Euch die Geschichte erzähle.", sourceObjectiveStatus = "unverified-source-field" }
quests[27221] = { id = 27221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh, es ist wahr!", description = "Ja, Tethyr gibt es wirklich. Das Monster lebt in den Gewässern rund um Theramore.\n\nEs mag sehr gerne helle Lichter, deshalb hat man den Leuchtturm überhaupt erst geschlossen, versteht Ihr...\n\nWenn Ihr den Turm wieder in Betrieb nehmt, wird das Biest sofort wieder auftauchen. Natürlich würde niemand mit gesundem Menschenverstand dergleichen tun.\n\nIhr solltet Euch also darum kümmern. Es war schön, bei einem Bierchen mit Euch plaudern zu können, aber gebt dem alten Nat bloß nicht die Schuld, wenn Tethyr Euch WIRKLICH in einen Fischköder verwandelt. Bevor Ihr Euren Plan in die Tat umsetzt, sprecht auf jeden Fall mit Major Mühlens bei den Docks von Theramore.", sourceObjective = "Sprecht mit Major Mühlens bei den Docks von Theramore.", completion = "<Ihr berichtet von Eurem Erlebnis mit Nat Pagle, seid jedoch bemüht, den Teil der Geschichte mit dem 'Ködertest' auszulassen.>\n\nNun, es scheint, als haben wir etwas zu tun. Ich mache mich an die Vorbereitungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27222] = { id = 27222, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bezwingt Tethyr!", description = "Meeresungeheuer hin oder her, wir werden auf keinen Fall die Sicherheit unserer Schiffe aufs Spiel setzen. Ich habe unsere besten Schützen angewiesen, sich auf eine Begegnung mit Tethyr vorzubereiten. Die Artilleristen haben die Verteidigung der Docks mit drei Mörsern verstärkt.\n\nIch werde den Befehl zum Entzünden der Leuchtturmlampe erteilen. Falls Tethyr angreift, müsst Ihr die Mörser bedienen und das Biest bezwingen, bevor es alle Schützen tötet. Ich würde allerdings nicht zu lange an einer Stelle bleiben. Die Verwendung der Mörser wird mit Sicherheit die Aufmerksamkeit des Ungeheuers erregen.", sourceObjective = "Benutzt die Mörser, um Tethyr zu besiegen.", completion = "Gute Arbeit, {name}! Ich gebe zu, dass ich beim ersten Anblick des Biests meine Zweifel hatte, dass wir die Docks verteidigen können, aber Ihr habt die Verteidiger bestens zusammengehalten!", sourceObjectiveStatus = "unverified-source-field" }
quests[27223] = { id = 27223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vergeltung", description = "Dort, wo die Marktgasse auf die Feststraße trifft, werdet Ihr auf den Unverziehenen treffen. Wenn Ihr alle auf dem Kreuzzüglerplatz tötet, werdet Ihr auch Timmy den Grausamen erwischen. Diese beiden ehemaligen Champions haben den Unschuldigen hier gegenüber schreckliche Taten vollbracht, um unheilige Macht zu erlangen.\n\nIhr müsst sie beide besiegen, um Stratholme von ihrer finsteren Anwesenheit zu befreien. Seid wachsam, denn sie waren zu Lebzeiten mächtige Kämpfer, und durch den Erhalt ihrer neuen dunklen Kräfte wurden sie nur noch stärker.", sourceObjective = "Tötet den Unverziehenen und Timmy den Grausamen.", completion = "Erhaltet dies als Belohnung. Ich hab es in der Rüstung einer Geißel gefunden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27225] = { id = 27225, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufforderung von Ander Germaine", description = "Ander Germaine hat verlauten lassen, dass er Euch für Euren meisterhaften Umgang mit den Waffen und Eurer Zuschreibung zur Allianz ehren möchte. Macht Euch auf nach Sturmwind und verlasst das Altstadtviertel durch den südlichen Ausgang. Ihr werdet ihn in seiner Kommandozentrale finden. Ich weiß nicht, was er vorhat, aber ich glaube, er ist von Eurem raschen Fortschritt beeindruckt.", sourceObjective = "Sprecht mit Ander Germaine in der Kommandozentrale von Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[27226] = { id = 27226, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Um ein Seebärenhaar", description = "Dem Kriegshäuptling sei Dank, dass Ihr hier seid, {name}. Mir ist ein schwerwiegender Fehler mit den Seebären unterlaufen und ich brauche Eure Hilfe, um die Sache wieder gerade zu biegen.\n\nIch habe sie stocknüchtern losgeschickt, um gegen die Worgen zu kämpfen, die von der Insel Fenris kamen. Sie haben die Bestien angegriffen und haben ordentlich was einstecken müssen. Viele sind gefallen, aber ein paar leben noch und kämpfen nun um ihr Leben.\n\nBringt dieses Bierfass zu den Verfallenen Feldern östlich von hier und seht zu, dass kein Schluck übrig bleibt.", sourceObjective = "Weckt 8 orcische Seebären auf.", completion = "AHA! Ich wusste es! Da haben wir wohl wieder etwas gelernt. Wir werden nicht wieder so versagen. Ich werde sicherstellen, dass immer Bier an vorderster Front bereitsteht.", sourceObjectiveStatus = "unverified-source-field" }
quests[27227] = { id = 27227, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Baron Aurius Totenschwur", description = "Diese Kapelle ist das letzte Licht in der wachsenden Dunkelheit. Ras Frostraunen nahm sich auf dem Schlachthof sein Leben und schlitzte vor dem Lichkönig sein Gesicht in ein makabres Lächeln. Der Lichkönig nahm sich seiner an und machte ihn zu dem Lich, der jetzt Scholomance heimsucht.\n\nDer Ort, an dem diese Gräueltat geschah, ist nun heiliger Boden der Geißel, und wurde vom Lichkönig mit der dunkelsten aller Magie gesegnet. Baron Aurius Totenschwur, der neue Herrscher von Stratholme, bewacht diesen Ort und führt die grausame Arbeit seines Meisters fort. Tötet ihn, ohne zu zögern.", sourceObjective = "Tötet Baron Aurius Totenschwur.", completion = "Stratholme wird zum Symbol für alles Gute in dieser Welt werden. Ihr habt meinen Dank für Eure Arbeit in dieser Mission.", sourceObjectiveStatus = "unverified-source-field" }
quests[27228] = { id = 27228, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mann gegen Monstrosität", description = "Tief im Inneren werdet Ihr Ramstein den Verschlinger finden. Ich wage es kaum, Euch von den Gräueltaten zu erzählen, die dieses Monster vollbracht hat. Ihr müsst nur wissen, dass er den gesammelten Zorn zahlloser verirrter Seelen zu Gesicht bekommen soll; Zorn, den Ihr über ihn bringen werdet.\n\nHabt keine Gnade. Seid standhaft in Eurer Wut.", sourceObjective = "Tötet Ramstein den Verschlinger.", completion = "Die Macht, mit der Ihr Ramstein getötet habt, verdient meinen Respekt. Wenn echte Wut in den Taten zu sehen ist, kann wohl selbst die Geißel Angst empfinden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27229] = { id = 27229, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "ZERMATSCHT DIE BRUTKÖNIGIN", description = "<Der folgende Text ist in sehr großer Schrift geschrieben.>\n\nSPINNEN IN NORDHÖHLE BÖSE. VERGIFTEN OGER. OGER WERDEN KRANK. SCHLECHT!\n\nGROSSE RIESENSPINNE IN HÖHLE MACHT MEHR SPINNEN. MEHR SPINNEN SCHLECHT!\n\nTÖTET GROSSE SPINNE, AUFHALTEN NEUE SPINNEN. TÖTET GROSSE SPINNE, GROSSE BELOHNUNG! GUT!\n\n<Eine primitive Skizze wurde unter der Nachricht geschmiert.>", sourceObjective = "Beschafft den Pedipalpus der Brutkönigin.", progress = "Seid Ihr wegen des Schilds hier?\n\nIch möchte nicht darüber sprechen, es sei denn, Ihr habt einen Beweis für die Tötung.", completion = "Bei Grom - bin ich froh, dass es vorbei ist. Wenn Ihr das Schild gelesen habt, ist Euch vielleicht klar, wie verzweifelt ich war, nachdem ich versucht hatte, mit diesen schwerfälligen Trotteln zu kommunizieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[27230] = { id = 27230, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waffen für den Krieg", description = "Die Geißel sind Meister im Schmieden mächtiger Waffen für ihre Krieger, und das macht es für unsere Männer schwieriger, sie zu töten! In der Nähe der Ziggurat von Baroness Anastari sind Schmiedekunstpläne, die der Oberste Schwertschmied nutzen wird, um eine äußerst mächtige Waffe für Lord Aurius zu schmieden.\n\nWir werden verhindern, dass diese Waffe geschmiedet wird, und gleichzeitig dafür sorgen, dass sie auch keine normalen Waffen mehr herstellen werden! Nehmt die Schmiedekunstpläne an Euch, und tötet den Schwertschmied der schwarzen Wache, wenn er kommt, um die Pläne zu verteidigen. Das wird unsere Aufgabe erleichtern.", sourceObjective = "Tötet den Schwertschmied der schwarzen Wache.", progress = "Ihr müsst den Schwertschmied töten! Los!", completion = "Großartig! Wir werden durch ihren Verlust einer verlässlichen Bezugsquelle für Waffen siegen!", sourceObjectiveStatus = "unverified-source-field" }
quests[27231] = { id = 27231, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verstärkung aus Fenris", description = "Diejenigen, die Euren Angriff auf die Insel Fenris überlebten, konnten das Blut des Wolfes trinken. Sie wurden zu wilden Worgen, die nichts anderes als Rache im Sinn haben. Nun schwimmen sie über den Lordameresee und greifen meine Seebären an. Viele wurden bereits getötet. Die Worgenmonster müssen aufgehalten werden!\n\nMacht Euch auf den Weg zur verfallenen Fähre östlich von hier und tötet die Worgen des Hügellands, die diese Gegend heimsuchen. Sobald Ihr sie getötet habt, macht Euch auf den Weg zur Kommunikationskonsole der Horde bei den Docks. Ich werde mich mit Euch in Verbindung setzen.", sourceObjective = "Tötet 10 Worgen des Hügellands.", completion = "<Hatchets Kommunikationsgerät rauscht.>\n\nHatchet hier, sind alle tot?", sourceObjectiveStatus = "unverified-source-field" }
quests[27232] = { id = 27232, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rot gefärbte Gewässer ...", description = "<Das Kommunikationsgerät brummt.>\n\nDie Worgen, die Ihr getötet habt, waren der Spähtrupp. Hunderte von ihnen sind auf dem Weg! Es scheint, als haben Crowley und Blutfang allen Menschen in Lordaeron das Blutopfer angeboten.\n\nNehmt eine von diesen Kanonen der Horde und schickt sie dorthin zurück, wo sie herkommen. Färbt die Wasser des Lordameresees rot mit ihrem Blut!", sourceObjective = "Tötet 50 Worgen des Hügellands mit der Kanone der Horde.", completion = "Auch wenn Ihr viele der neuen Worgen getötet habt, können wir sicher sein, dass noch viel mehr von ihnen erscheinen werden. Ihr Angriff wurde jedoch geschwächt. Gute Arbeit, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[27233] = { id = 27233, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Stätte der Heiler", description = "Nun kann ich die Ausbildung selbst in die Hand nehmen. Falls Ihr nach Arbeit sucht, kann ich Euch empfehlen, der Straße nach Nordwesten zu folgen. Die Cenarischen Druiden und der Argentumkreuzzug haben dort auf Dalsons altem Hof ihr Lager aufgeschlagen. Vielleicht können sie Euch beschäftigen, bis wir hier wieder Hilfe benötigen.", sourceObjective = "Meldet Euch bei Außenagent Kaartish in der Stätte der Heiler in den Westlichen Pestländern.", completion = "Willkommen, {class}. Wie Ihr sehen könnt, besteht unser Lager aus einer Gemeinschaftsexpedition des Argentumkreuzzugs und Druiden des Zirkels des Cenarius. Wir heißen jedoch alle willkommen, die bei der Heilung des Landes helfen wollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27234] = { id = 27234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defias in Düstermarschen?", description = "Meine Späher haben von einem Schiffswrack nahe des Strands im Nordosten berichtet. Schiffswracks sind hier draußen zwar nichts Ungewöhnliches, aber den Berichten zufolge tragen die Überlebenden alle rote Kopftücher. Das ist das Symbol der Defias!\n\nAnscheinend hält sich ihr Anführer auf einer großen Insel in der Nähe der Küste nordöstlich des Turms auf. Tötet ihn, und nehmt alle Unterlagen an Euch, die Ihr bei ihm findet.", sourceObjective = "Erhaltet die Befehle der Defias von Garn Mathers.", progress = "Konntet Ihr ihren Anführer finden?", completion = "<Hauptmann Wymor nimmt die Befehlspapiere entgegen und liest sie durch.>\n\nWas könnte wohl mit 'wertvoller Fracht' gemeint sein? Die Defias haben öfter kleine Schmuggelaktionen in Sturmwind durchgeführt, aber das hier scheint in einer ganz anderen Größenordnung zu sein. Die Sprache, in der diese Befehle verfasst wurden, ist die eines Reichens oder Adligen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27235] = { id = 27235, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renn McGill", description = "Die von Euch erlangten Befehle weisen darauf hin, dass die Defias besonders erpicht darauf sind, ihre Fracht auszumachen und zu bergen.\n\nDer SI:7 arbeitete rund um Theramore eine Zeit lang mit dem Bergungstaucher Renn McGill zusammen. Als er von dem Schiffswrack erfuhr, machte sich Renn sofort auf den Weg nach Norden, um in der Nähe der Inseln, die von den Defias besetzt werden, zu tauchen.\n\nWenn wir vor den Defias an die Fracht gelangen wollen, werden wir seine Hilfe benötigen. Haltet in den Gewässern nordöstlich einer kleinen Insel nach ihm Ausschau. Sie liegt im Norden der Insel, die Ihr zuvor schon einmal besucht habt.", sourceObjective = "Bringt die Befehle der Defias zu Renn McGill in den Gewässern nahe Schreckensmoorküste.", progress = "Seid gegrüßt, {class}. Was führt Euch hierher?", completion = "<Renn liest die Befehle durch.>\n\nEs war also wirklich wertvolle Fracht auf dem Schiff! Wir müssen sie finden, bevor die Defias uns zuvorkommen. Diese Jungs sind keine Taucher, aber wir brauchen einen Teil ihrer Ausrüstung, damit Ihr mir helfen könnt, die Fracht zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27236] = { id = 27236, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tauchausrüstung aus zweiter Hand", description = "Zwischen hier und der Insel Alcaz liegen zahlreiche Wrackteile auf dem Meeresgrund. Die Defias haben bereits Taucher entsandt, die die Gewässer absuchen. Mithilfe einiger ihrer Ausrüstungsteile könnten wir Euch so ausstatten, dass Ihr Euch der Jagd anschließen könnt. Ihr müsstet allerdings erst einen Weg finden, wie Ihr an diese \"Leihgabe\" kommt.\n\nSucht diese Insel nach einer Kiste mit Tauchausrüstung und etwas zum Reparieren ab. Wenn Ihr das Material gefunden habt, bringt es zu mir und ich werde es in null Komma nichts einsatzbereit machen!", sourceObjective = "Bringt den Werkzeugsatz und die beschädigte Tauchausrüstung zu Renn McGill in Düstermarschen.", progress = "Mal sehen, was Ihr so von den Defias \"leihen\" konntet.", completion = "Oha, die Ausrüstung ist in schlechterer Verfassung, als ich gedacht hatte, und das Werkzeug...\n\nNaja, ich habe gesagt, dass ich es für Euch einsatzbereit machen kann, also mache ich mich besser mal an die Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[27237] = { id = 27237, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bergt die Fracht!", description = "Nun, ich konnte die Ausrüstung so reparieren, dass Ihr damit zumindest eine Weile lang tauchen könnt. Allerdings würde ich das Ganze nicht allzu lange auf die Probe stellen.\n\nDie Wrackteile des Schiffs sind auf dem Meeresgrund zwischen der Ostküste dieser Insel und der Insel Alcaz verstreut. Solange dieser Taucherhelm funktioniert, solltet Ihr versuchen, Teile des Wracks zwischen hier und Alcaz auszumachen. Verwendet diese Bergungsausrüstung, um die Wrackteile nach Spuren der Fracht zu durchsuchen. Gebt Acht, dass Ihr der Insel Alcaz nicht allzu nahe kommt. Die Hydras dort sind gefährlich.", sourceObjective = "Sammelt 1 geborgene Geldkassetten.", progress = "Habt Ihr bei der Durchsuchung der Wrackteile etwas über die Fracht der Defias in Erfahrung bringen können?", completion = "<Renn durchwühlt die Inhalte der Geldkassetten, die Ihr geborgen habt.>\n\nGute Arbeit. Sehen wir nach, ob die 'wertvolle Fracht' auch hier drin ist ...", sourceObjectiveStatus = "unverified-source-field" }
quests[27238] = { id = 27238, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jaina muss davon erfahren", description = "Ihr müsst Lady Jaina sofort von unserem Fund berichten! Wenn die Defias einen Gefangenen an Bord hatten, dann ist es schwierig, herauszufinden, wer es ist und ob diese Person noch am Leben ist!\n\nEines ist jedoch sicher, {name}. Die Defias würden all diese Schwierigkeiten nicht aus bloßer Gehässigkeit auf sich nehmen. Ihr Gefangener muss jemand von Wichtigkeit sein. Lady Jaina kann mit Sicherheit mehr als jeder andere mit diesen Fundstücken anfangen. Ihr findet sie hoch oben im Magierturm im Zentrum von Theramore.", sourceObjective = "Sprecht mit Lady Jaina Prachtmeer in Theramore.", completion = "Ihr und Renn habt ausgezeichnete Arbeit geleistet, diese Informationen zu Tage zu bringen und sofort Bericht zu erstatten. Jetzt müssen wir den Fund bestätigen. Es würde schwerwiegende Ausmaße annehmen, wenn wir falsch liegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27239] = { id = 27239, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beobachtet die Insel Alcaz", description = "Offenbar hatte Renn mit seinen Vermutungen über die Insel Alcaz Recht. Wir müssen diese Insel beobachten. Dazu bräuchten wir allerdings eine ganze Brigade von Soldaten.\n\nTheramores Verteidigung könnte einen derartigen Schlag nicht überstehen, also habe ich mich mit Cassa Purpurschwinge, dem Greifenmeisterlehrling von Theramore, abgesprochen. Sie wird uns eines ihrer Tiere für die Beobachtung der Insel Alcaz aus der Luft überlassen.\n\nDie Insel birgt den Schlüssel zum Geheimnis darüber, inwiefern die Defias in diese Entführung verwickelt sind.", sourceObjective = "Sprecht mit Cassa Purpurschwinge und nutzt einen ihrer Greifen, um die Insel Alcaz zu beobachten.", completion = "<Lady Jaina hört aufmerksam zu, als Ihr von Euren Funden der Luftbeobachtung berichtet.>\n\nEin Runenzirkel, Drachkin? Die Defias haben sich mit IHR verbündet? Der Verräterin?\n\n<Lady Jaina beruhigt sich und bereitet sich vor, die Situation zu erklären.>", sourceObjectiveStatus = "unverified-source-field" }
quests[27240] = { id = 27240, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beweis des Verrats", description = "Onyxia wurde zwar entlarvt und vom Hofe entfernt, doch noch müssen die Defias, die ihren Plan ausgeführt haben, bestraft werden. Bringt König Varian Wrynn in Burg Sturmwind die Nachricht, dass die Defias für seine Entführung verantwortlich sind. Ich hege kaum Zweifel daran, dass der König die darin Verwickelten schnell und grausam bestrafen lassen wird.\n\nIch kann Euch mithilfe meiner Magie schneller nach Sturmwind bringen. Sagt einfach Bescheid, sobald Ihr bereit seid, {name}.", sourceObjective = "Sprecht mit Jaina, sobald Ihr bereit seid, nach Sturmwind zu reisen und König Varian Wrynn zu treffen.", completion = "Es waren die Defias, die Onyxia bei diesem Plot unterstützt haben?\n\n<Das Gesicht des Königs wird rot vor Wut, und er ballt seine Hände zu Fäusten.>\n\nIhr und Lady Jaina habt Sturmwind an diesem Tag einen großen Dienst erwiesen. Die Verräter werden nicht lange genug leben, um ihre Verbrechen zu bereuen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27241] = { id = 27241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Jaina", description = "Ich muss mich darum kümmern, die Reste der Defias zu beseitigen. Bitte überbringt Lady Jaina in Theramore meinen Dank. Sie ist schon immer ein treuer Freund und loyaler Verbündeter gewesen.\n\nGeht zum Magierviertel im Westen der Stadt und sprecht dort am Fuße des Turms mit Erzmagier Malin. Er wird Euch rasch wieder nach Theramore bringen.", sourceObjective = "Kehrt zu Lady Jaina Prachtmeer in Theramore zurück.", completion = "Ich habe keine Zweifel daran, dass der König jedes einzelne Wort ernst gemeint hat, als er Euch von seinen Plänen unterrichtete, die Defias ein für alle Mal zu vernichten. Er ist kein Mann leerer Versprechen, und die Feinde Sturmwinds sollten das wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27242] = { id = 27242, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raptorenfänger", description = "Im nordöstlichen Sumpfgebiet lebt eine ganz besonders gefährliche Raptorenart. Wir haben schon mehr als einen unachtsamen Soldaten an sie verloren. Ich denke jedoch, dass wir sie gegen unsere unliebsamen Nachbarn, die Grimmtotem, einsetzen könnten.\n\nNehmt dieses Seil und fangt damit Blutsumpfraptoren oder Blutsumpfkreischer ein, die Ihr zuvor überwältigt habt. An Eurer Stelle würde ich sie zunächst im Kampf schwächen, bevor ich versuchen würde, sie einzufangen. Das wird ein ganz schön harter Kampf werden.", sourceObjective = "Benutzt den strapazierfähigen Strick, um 6 Blutsumpfraptoren oder Blutsumpfkreischer zu fangen.", progress = "Konntet Ihr diese Raptoren einfangen?", completion = "Ihr seht ein wenig zerkratzt aus, aber das sollten keine schlimmen Wunden sein. Ihr seid sicherlich in einem besseren Zustand als die Grimmtotem in Kürze sein werden, wenn wir unsere neuen Raptorenfreunde auf sie loslassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27243] = { id = 27243, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst die Raptoren los", description = "Jetzt, da wir unsere Raptoren haben, ist der nächste Schritt, sie zu einem Angriff auf die Grimmtotem im Dorf der Schwarzhufe im Nordwesten zu \"animieren\".\n\nIch habe hier noch eine übriggebliebene Lende von einem ... nun, eigentlich ist es völlig egal, was es ist. Ihr werdet dieses Fleisch als Köder verwenden. Platziert es in der Nähe der Windmühle im Zentrum des Dorfes der Schwarzhufe. Die Raptoren sollten sich um den Rest kümmern, falls das Training funktioniert hat.", sourceObjective = "Platziert den Raptorköder in der Nähe der Windmühle im Dorf der Schwarzhufe.", completion = "<Der Unteroffizier versucht gar nicht erst, sein Grinsen zu unterdrücken.>\n\nGut. Das sollte den einen oder anderen Angriff verhindern.", sourceObjectiveStatus = "unverified-source-field" }
quests[27244] = { id = 27244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der verlorene Bericht", description = "Beim Durchsuchen der lockeren Erde wird die abgetrennte Hand eines Orcs gefunden. Die Hand hält eine aus Knochen geschnitzte Röhre umklammert. Und in der Röhre befindet sich ein fleckiges Pergament.\n\nDas Pergament ist ein Bericht von einem Orc, der die Stadt Theramore über Wochen ausspionierte.\n\nAls Ihr das Pergament überflogen habt, ist klar, dass es zum orcischen Spionagemeister in Brackenwall gebracht werden muss.", sourceObjective = "Bringt den Bericht des Spions zu Nazeer Blutlanze in Brackenwall.", progress = "Habt Ihr etwas für mich?", completion = "Gute Arbeit, {name}. Unser Agent Marg Nachtauge war außerhalb von Theramore stationiert. Seine Aufgabe war es, die Stadt auszuspionieren. \n\nDas ist sein jüngster Bericht und könnte sein letzter sein; nach Eurer Aussage fürchte ich, dass Marg im Sumpf sein Ende fand...", sourceObjectiveStatus = "unverified-source-field" }
quests[27245] = { id = 27245, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefangene der Grimmtotem", description = "Wir tun, was wir können, um die Räuber der Grimmtotem in Schach zu halten, aber sie greifen den Turm immer wieder an. Was noch viel schlimmer ist, die Späher unserer Patrouillen, die vom Hauptmann entsandt werden, um Informationen zu sammeln und die Straße zu sichern, wurden von ihnen entdeckt und entführt.\n\nIch vermute, dass die Gefangenen zum Dorf der Schwarzhufe im Nordwesten gebracht wurden. Wie ich die Grimmtotem kenne, tragen die Verteidiger des Dorfes die Schlüssel zu den Käfigen der Gefangenen bei sich. Mir ist egal wie, {class}, aber bringt mir meine Männer lebend zurück.", sourceObjective = "Erlangt die Schlüssel der Grimmtotem von den Taurendruiden der Grimmtotem im Dorf der Schwarzhufe und benutzt sie, um 5 Gefangene von Theramore zu befreien.", completion = "Die befreiten Gefangenen sind bereits auf dem Heimweg vom Dorf der Schwarzhufe. Die Informationen, die der Hauptmann von den Gefangenen erhalten wird, werden uns in unserem nächsten Kampf gegen die Grimmtotem einen Vorteil verschaffen.\n\nIhr habt den Dank meiner Männer und mir.", sourceObjectiveStatus = "unverified-source-field" }
quests[27246] = { id = 27246, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Orcbericht", description = "Beim Durchsuchen der lockeren Erde wird die abgetrennte Hand eines Orcs gefunden. Die Hand hält eine aus Knochen geschnitzte Röhre umklammert. Und in der Röhre befindet sich ein fleckiges Pergament.\n\nDas Pergament ist in der Sprache der Orcs verfasst ... und sieht wichtig aus.", sourceObjective = "Bringt den Spionbericht zu Leutnant Aden in Theramore.", progress = "Habt Ihr etwas zu berichten?", completion = "Hm ... Mein Orcisch ist nicht sehr gut, aber dieses Schriftstück sieht aus wie ein Report, der von einem orcischen Spion geschrieben wurde.", sourceObjectiveStatus = "unverified-source-field" }
quests[27247] = { id = 27247, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hauptmann Mumm", description = "Hauptmann Mumm sollte den Orcbericht sehen, den Ihr gefunden habt, {name}. Er kennt die Sprache der Orcs besser als die meisten. Und er sollte wissen, dass sich Spione der Horde bei Theramore aufhalten!\n\nDer Hauptmann befindet sich in der Kaserne auf der nordöstlichen Seite der Insel Theramore.", sourceObjective = "Bringt den Spionbericht zu Hauptmann Garran Mumm.", progress = "Ihr habt etwas für mich?", completion = "Der Report von einem Orcspion! Wie habt Ihr das gefunden? Egal - erst sollten wir sehen, was hier steht ...", sourceObjectiveStatus = "unverified-source-field" }
quests[27248] = { id = 27248, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission nach Morastwinkel", description = "Das Dampfdruckkartell hat vor Kurzem im südlichen Teil von Düstermarschen einen neuen Außenposten errichtet. Man taufte ihn Morastwinkel und er befindet sich entlang der Hauptstraße, südlich von Tabethas Hof und den Ruinen der Steinbrecher.\n\nDas ist eine hervorragende Gelegenheit für uns, neue Handelskontakte zu knüpfen, und Lady Jaina möchte, dass ich einen Abgesandten dorthin schicke, um Kontakt aufzunehmen. Wärt Ihr bereit, die Reise für uns aufzunehmen?", sourceObjective = "Sprecht mit Drazzit Tropfhahn in Morastwinkel.", completion = "Theramore ist also am Handel interessiert? Das ist kein Angebot, dass ich abschlagen möchte. Uns gehen die Vorräte hier auch langsam aus, und wir können alle Geschäftskontakte brauchen, die wir finden können!", sourceObjectiveStatus = "unverified-source-field" }
quests[27249] = { id = 27249, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untersuchung der Ruinen", description = "Der arme James, er ist nie wirklich über die Zerstörung des Gasthauses \"Zur Süßen Ruh\" und den Tod seiner Familie hinweggekommen. Die Jungs und ich versuchen unser Bestmögliches, um die Monster, die dafür verantwortlich sind, zu finden.\n\nIch habe unseren besten Ermittlungsbeamten, Inspektor Tarem, zu den Ruinen geschickt. Einer allein wird mit dieser Aufgabe aber wohl kaum fertigwerden. Wir würden es wirklich zu schätzen wissen, wenn Ihr Tarem helfen würdet. Beim Licht, wir würden alle gern da draußen sein und mithelfen.\n\nDie Hauptstraße führt Euch direkt zum Gasthaus, aber seid vorsichtig. Auf dieser Reise seid Ihr auf Euch selbst gestellt. Meine Soldaten können Euch keinen Schutz bieten.", sourceObjective = "Sprecht mit Inspektor Tarem beim Gasthaus \"Zur Süßen Ruh\".", completion = "Gut, dass Hauptmann Mumm endlich auch andere Leute in die Untersuchung einbindet.\n\nIch habe hier im Umkreis reflektierenden Staub verwendet.\n\nEr wird ungewöhnliche Gegenstände und Markierungen ans Licht bringen. So könnt Ihr Euch besser auf Eure Anstrengungen konzentrieren. Betrachtet alles genau, was vom Staub erleuchtet wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[27250] = { id = 27250, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WIEDERVERARBEITUNG - SCHLECHTE KOPIE", description = "Bevor ich im Blauen Eremiten angefangen habe, wurde ich von einem der besten Köche und Gastwirte ausgebildet, die ich je getroffen habe. James Hyal hieß er. Meinen gesamten Besitz und Alles, was ich in meinem Leben je erreicht habe, verdanke ich ihm.\n\nIch frage mich, wie es ihm geht. Sein Bruder Vincent und er arbeiten in einer Taverne im Hafen von Menethil, aber ich habe schon länger nichts mehr von ihm gehört.\n\nFalls Ihr Euch jemals auf dem Weg nach Menethil wiederfindet, könntet Ihr im vielleicht meine Grüße ausrichten.", sourceObjective = "Sprecht mit Vincent Hyal im Hafen von Menethil.", sourceObjectiveStatus = "unverified-source-field" }
quests[27251] = { id = 27251, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie nennen ihn den lächelnden Jim", description = "Der alte Jim da tut mir leid, ich kann mir nicht helfen. Er war nicht immer so. Hatte eine Zeitlang ein Gasthaus im Sumpf, ein wunderbares Lokal.\n\nAber eigentlich möchte ich nicht darüber sprechen. Besprecht es mit Hauptmann Mumm, wenn es sein muss. Ihr findet ihn auf der obersten Etage der Wehrzitadelle, der großen Kaserne östlich von Lady Jainas Turm.", sourceObjective = "Sprecht mit Hauptmann Garran Mumm auf der obersten Etage der Wehrzitadelle.", completion = "James Hyal ist sein richtiger Name. Er hat ein Gasthaus am Randes des Brachlands eröffnet. Er wollte Reisenden einen netten Ort für Übernachtungen anbieten...\n\nKönnte schon sein, dass er zu hochfliegende Pläne hatte, aber das Gasthaus lief eine Weile ganz gut. Dann haben wir die Kontrolle über die Straßen in den Marschen verloren und die Ogers haben alles übernommen.\n\nJames war zu stur, um seinen Traum gegen die Sicherheit innerhalb unserer Mauern einzutauschen und das Gasthaus \"Zur Süßen Ruh\" wurde niedergebrannt. Wir untersuchen den Vorfall noch, hatten bisher aber nicht viel Glück. Wenn Ihr helfen wollt, seht, was Ihr in den Trümmern finden könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27252] = { id = 27252, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schwarze Schild", description = "Ein Eisenschild, von dem Feuer geschwärzt, das in dem Gasthaus wütete, ist an dem verfallenen Kamin befestigt, einer der wenigen erhaltenen Teile des Gebäudes, das einmal das Gasthaus \"Zur Süßen Ruh\" war.\n\nDer Schild lässt sich von den Mauersteinen des Kamins ablösen.", sourceObjective = "Bringt den geschwärzten Eisenschild zu Hauptmann Garran Mumm in Theramore.", progress = "Habt Ihr in den Ruinen vom Gasthaus \"Zur Süßen Ruh\" Beweise gefunden?", completion = "Hm, ich bin kein Experte, was die Herstellung von Waffen und Rüstung angeht. Wie man sie handhabt, ja, aber nicht, wie man sie herstellt.\n\nDieser Schild scheint mir sehr gewöhnlich zu sein, bis auf den Schaden durch das Feuer, das im Gasthaus wütete.", sourceObjectiveStatus = "unverified-source-field" }
quests[27253] = { id = 27253, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untersuchung der Ruinen", description = "Wenn Ihr der Straße vom Dorf aus nach Süden und dann westlich in Richtung Brachland folgt, werdet Ihr auf die Ruinen des Gasthauses \"Zur Süßen Ruh\" stoßen.\n\nTheramore hat einen Ermittlungsbeamten entsandt, um herauszufinden, von welchem Schicksal das Gasthaus heimgesucht wurde. Ich habe in dem Gasthaus einen Spion untergebracht und ich vertraue nicht darauf, dass diese Menschen kompetent genug sind, um in Erfahrung zu bringen, was damals passiert ist.\n\nEgal was Ihr findet, seht zu, dass der Ermittlungsbeamte es nicht in die Hände bekommt. Wir werden uns der Sache selbst annehmen.", sourceObjective = "Erforscht das Gasthaus \"Zur Süßen Ruh\" an der Grenze Brachlands in Düstermarschen.", completion = "<Der Inspektor mustert Euch voller Geringschätzung und Argwohn.>\n\nVerlasst diesen Ort, Bote, oder ich werde dafür sorgen, dass ich das nächste Mal mit einer Gefolgschaft Wachen herkomme, um Euch zu verdeutlichen, was ich meine.", sourceObjectiveStatus = "unverified-source-field" }
quests[27254] = { id = 27254, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schwarze Schild", description = "Ein Eisenschild, von dem Feuer geschwärzt, das in dem Gasthaus wütete, ist an dem verfallenen Kamin befestigt, einer der wenigen erhaltenen Teile des Gebäudes, das einmal das Gasthaus \"Zur Süßen Ruh\" war.\n\nDer Schild lässt sich von den Mauersteinen des Kamins ablösen.", sourceObjective = "Bringt den geschwärzten Eisenschild zu Krog in Brackenwall.", progress = "Was habt Ihr da, {name}? Beweise aus den Ruinen vom Gasthaus \"Zur Süßen Ruh\"?", completion = "Ich gebe zu, dass Menschen nicht die besten Inneneinrichter sind, aber würden sie wirklich einen einfachen Eisenschild wählen, um ihren Kamin zu schmücken? Vielleicht wurde der Schild von denjenigen hinterlassen, die das Gasthaus in Flammen setzten.\n\nEine Warnung? Eine Drohung?", sourceObjectiveStatus = "unverified-source-field" }
quests[27255] = { id = 27255, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schwarze Schild", description = "Hmm ... Ich sehe nichts Außergewöhnliches an diesem Schild. Wir sollten ihn Do'gol dem Schmied zeigen. Vielleicht kann er uns mehr verraten, aber ich würde keine Hoffnung hegen ...", sourceObjective = "Zeigt den geschwärzten Eisenschild Do'gol in Brackenwall.", progress = "Ihr habt etwas für mich, {class}?", completion = "Das ist ein guter Schild. Sehr stark, schwer, wirklich gut. Aber Do'gol kann damit nichts anfangen. Ich mache Schilde, und kaufe sie nicht, {name}.\n\nIhr solltet das wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27256] = { id = 27256, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schwarze Schild", description = "Hmmm, hier am Rand des Schildes steht etwas geschrieben, aber durch die Brandspuren kann man es kaum lesen.\n\nIch brauche Säure, um ihn zu reinigen. Das Gift der Graunebelspinnen sollte dafür ausreichen. Die Spinnen haben sich in einer alten Mine in den Graunebelhöhlen nordwestlich der Siedlung eingenistet. Bringt mir ihre Giftsäcke und ich kann den Schild reinigen.", sourceObjective = "Sammelt 5 Säuregiftbeutel von Graunebelspinnen.", progress = "Habt Ihr die Beutel von den Spinnen?", completion = "Ich mag Spinnen nicht, die so groß sind, dass ich sie nicht einfach zerquetschen kann.\n\nDanke, dass Ihr das erledigt habt, {name}. Jetzt muss ich die Giftbeutel nur aufreißen und das Gift auf den Schild schütten ...", sourceObjectiveStatus = "unverified-source-field" }
quests[27257] = { id = 27257, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schwarze Schild", description = "Oh, ich glaube, ich habe zu viel Säure auf den Schild geschüttet. Lasst mich ein wenig rubbeln ...\n\nHm, schwer zu lesen, sieht aber aus wie der Name Mosarn. Nie von ihm gehört. Vielleicht kennt Krog ihn. Krog kennt viele Leute.", sourceObjective = "Sprecht mit Krog in Brackenwall.", completion = "Mosarn? Kommt mir bekannt vor... Ich komm' nicht drauf. Vielleicht fällt es mir später wieder ein.\n\nIst wahrscheinlich nicht so wichtig. Ein Schild kann von überall herkommen und nichts bedeuten...", sourceObjectiveStatus = "unverified-source-field" }
quests[27258] = { id = 27258, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schwarze Schild", description = "Ah, jetzt erinnere ich mich! Mosarn ist ein angesehener Schmied in Donnerfels. Ich wusste, dass ich den Namen irgendwo schon einmal gehört habe.\n\nAus Dankbarkeit hat mir der Irdene Ring eine Rüstung verliehen, die von Mosarn angefertigt wurde. Sehr gute Arbeit.\n\nVielleicht kann er Euch mehr über den Schild erzählen, den er hergestellt hat.\n\nEs ist nicht viel, aber da wir von Reethe nichts Nützliches in Erfahrung bringen konnten, ist es alles, was wir vorweisen können.", sourceObjective = "Zeigt den geschwärzten Eisenschild Mosarn in Donnerfels.", progress = "Hallo, {class}. Wie kann ich Euch helfen?", completion = "Ja, Ihr liegt richtig. Das ist ein Schild, den ich angefertigt habe.\n\nAllerdings kann ich Euch leider nicht sehr viel mehr darüber erzählen, {name}. Ich stelle so viele Schilder und Rüstungen her, dass ich nicht über alle Bescheid wissen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[27259] = { id = 27259, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdächtige Hufabdrücke", description = "Hufspuren führen von den noch rauchenden Überresten des Gasthauses \"Zur Süßen Ruh\" weg. Wenigstens einige Abdrücke sind deutlich erkennbar, und weitere Abdrücke sind im weichen Schlamm des Sumpfs zu sehen, wenn man ganz genau hinsieht.", sourceObjective = "Berichtet Krog in Brackenwall von den verdächtigen Abdrücken beim Gasthaus \"Zur Süßen Ruh\".", completion = "Hufabdrücke... Ich denke, das waren möglicherweise die Stacheleber. Oder vielleicht ein Zentaur. Im Brachland gibt es recht viele von ihnen und es dürfte ihnen nicht schwerfallen, so eine Tat zu verüben\n\nHabe ich übrigens erwähnt... Nicht nur das Gasthaus wurde niedergebrannt. Die Frau und das Kind des Besitzers wurden getötet. Ganz üble Sache, das.\n\nNichtsdestotrotz, ich werden Kagoro schicken, um nachzusehen, wo die Spuren hinführen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27260] = { id = 27260, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leutnant Paval Reethe", description = "Unter dem Geröll erregt ein Funkeln Eure Aufmerksamkeit. Nachdem Schmutz und Asche von dem Objekt gewischt wurden, kommt das Emblem eines goldenen Ankers auf einer weißen Emailleoberfläche zum Vorschein: das Zeichen von Theramore.\n\nUnter dem Anker ist der Name \"Leutnant Paval Reethe\" eingeprägt.", sourceObjective = "Bringt Reethes Abzeichen zu Krog in Brackenwall.", progress = "Habt Ihr weitere Hinweise auf die Geschehnisse im Gasthaus \"Zur Süßen Ruh\" gefunden?", completion = "Hmm ... also das ist interessant.", sourceObjectiveStatus = "unverified-source-field" }
quests[27261] = { id = 27261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befragt Reethe", description = "Es hat lange gedauert, aber ich habe Reethe gefunden. Für einen Menschen hatte er sich gut versteckt.\n\nOgron hatte Angst, nach dem langen Aufenthalt im Sumpf könnte er verrückt geworden sein. Ihr kommt mit mir, denn wir brauchen Antworten von ihm.", sourceObjective = "Folgt Ogron und sprecht mit Reethe.", completion = "Hmpf. Es ist gut, dass Reethe nicht mehr im Sumpf herumlungert. Ein Jammer, dass Menschen so empfindlich sind, dass er sich nicht von einer kleinen Pfeilwunde erholen konnte.\n\nOffenbar hat dieser Teil des Rätsels nirgendwohin geführt und wir müssen es anderswo versuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27262] = { id = 27262, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdächtige Hufabdrücke", description = "Hufspuren führen von den noch rauchenden Überresten des Gasthauses \"Zur Süßen Ruh\" weg. Wenigstens einige Abdrücke sind deutlich erkennbar, und weitere Abdrücke sind im weichen Schlamm des Sumpfs zu sehen, wenn man ganz genau hinsieht.", sourceObjective = "Berichtet Hauptmann Garran Mumm in Theramore von den verdächtigen Abdrücken beim Gasthaus \"Zur Süßen Ruh\".", completion = "Hufabdrücke also? Es stimmt, in den Ländern nahe der Düstermarschen gibt es außergewöhnlich viele Zentauren. Bei unseren kurzen Ausflügen ins Brachland haben wir ihre Lager und Besitztümer im ganzen Gebiet verstreut gefunden.\n\nIch werde Falgran Hastil, einen unserer Spurenleser, ausschicken, um nachzusehen, wohin die Spuren führen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27263] = { id = 27263, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leutnant Paval Reethe", description = "Unter dem Geröll erregt ein Funkeln Eure Aufmerksamkeit. Nachdem Schmutz und Asche von dem Objekt gewischt wurden, kommt das Emblem eines goldenen Ankers auf einer weißen Emailleoberfläche zum Vorschein: das Zeichen von Theramore.\n\nUnter dem Anker ist der Name \"Leutnant Paval Reethe\" eingeprägt.", sourceObjective = "Bringt Reethes Abzeichen zu Hauptmann Garran Mumm in Theramore.", progress = "Habt Ihr in den Ruinen vom Gasthaus \"Zur Süßen Ruh\" etwas Interessantes gefunden?", completion = "Das Abzeichen einer Wache bringt nie gute Neuigkeiten mit sich.\n\nManchmal handelt es sich um jemanden, der im Kampf gefallen ist, und dann liegt es an mir, die Nachrichten der trauernden Familie zukommen zu lassen. Manchmal finden wir nicht einmal heraus, was passiert ist. Und dann gibt es noch Situationen, die sogar schlimmer sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[27264] = { id = 27264, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leutnant Paval Reethe", description = "Ich kenne den Namen Leutnant Paval Reethe nicht. Am besten erkundigt Ihr Euch bei Adjutant Tesoran. Er hat alle Aufzeichnungen über die Wachen von Theramore, vom Personal bis hin zur Ausrüstung.\n\nEr sollte Euch nach einem Blick in seine Bücher sagen können, wer dieser Reethe ist.", sourceObjective = "Findet bei Adjutant Tesoran in Theramore mehr über Reethe heraus.", completion = "Hallo, {name}. Möchtet Ihr Informationen über ein bestimmtes Mitglied der Wache von Theramore? Reethe, sagt Ihr?\n\nGebt mir einen Moment, damit ich das richtige Buch suchen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[27265] = { id = 27265, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lord Grayson Schattenbruch", description = "Lord Grayson Schattenbruch, einer der führenden Paladine im Realm, hat Euch zu einem persönlichen Gespräch aufgefordert. Ich weiß nicht, was er vorhat, aber ich glaube, er ist von Eurem raschen Fortschritt beeindruckt.\n\nIhr solltet Euch umgehend nach Sturmwind aufmachen und ihn in der Kathedrale des Lichts aufsuchen.", sourceObjective = "Sprecht mit Lord Grayson Schattenbruch in der Kathedrale des Lichts in Sturmwind.", completion = "Es erfreut mich, dass meine Nachricht Euch erreicht hat, {name}. Wir haben viel zu besprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27266] = { id = 27266, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wulf ruft", description = "Wulf Hansreim beaufsichtigt die Ausbildung und Koordination der Jäger im Dienst von Sturmwind. Er hat Euch zu einem persönlichen Gespräch gebeten. Reist nach Sturmwind, sobald es Euch möglich ist, und verlasst das Altstadtviertel durch das südliche Tor, um zu seinem Quartier zu gelangen.\n\nIch weiß nicht, was er vorhat, aber ich glaube, er ist von Eurem raschen Fortschritt beeindruckt.", sourceObjective = "Sprecht mit Wulf Hansreim in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[27267] = { id = 27267, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nehmt zum SI:7 Kontakt auf", description = "Es scheint, als zeigten die Anführer von SI:7 Interesse an Eurem Fortschritt und Euren Diensten für die Allianz. Osborne der Nachtmensch, ein hochrangiges Mitglied von SI:7, wünscht ein Gespräch mit Euch. Ihr findet ihn im südlichen Teil von Sturmwinds Altstadt.\n\nIch weiß nicht, was Osborne von Euch will, aber es schien wichtig.", sourceObjective = "Sprecht mit Osborne dem Nachtmensch in Sturmwinds Altstadt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27268] = { id = 27268, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eilt zur Kathedrale", description = "Ich habe eine dringende Nachricht aus Sturmwind für Euch, {name}. Es scheint, als wünsche Hohepriesterin Laurena Euch in der Kathedrale des Lichts am Kathedralenplatz in Sturmwind zu sprechen. Der Botschafter lies nicht verlauten, um welches Anliegen es gehe, doch er gab den Rat, die Reise nach Sturmwind nicht aufzuschieben.", sourceObjective = "Sprecht mit Hohepriesterin Laurena in der Kathedrale des Lichts in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[27269] = { id = 27269, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Tempel des Mondes", description = "Ich habe eine dringende Nachricht aus Darnassus für Euch. Die Nachricht ist von der Hohepriesterin Elunes, Tyrande Wisperwind, persönlich! Der Botschafter lies nicht verlauten, um welches Anliegen es gehe, doch er gab den Rat, die Reise zum Tempel des Mondes in Darnassus nicht aufzuschieben und die Hohepriesterin so schnell wie möglich zu treffen.", sourceObjective = "Sprecht mit Tyrande Wisperwind im Tempel des Mondes in Darnassus.", completion = "Willkommen im Tempel des Mondes, {name}. Ich bin froh, dass Ihr meiner Aufforderung so schnell nachkommen konntet.", sourceObjectiveStatus = "unverified-source-field" }
quests[27270] = { id = 27270, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Audienz bei der Scharfseherin", description = "Ich habe eine dringende Nachricht aus Sturmwind für Euch, {name}. Es sieht aus, als würde Scharfseherin Umbrua darum bitten, mit Euch zu sprechen, wenn Ihr das nächste Mal in der Stadt seid.\n\nDer Bote hat mir keine Erklärung für die Einladung der Scharfseherin gegeben, aber Ihr solltet nach Sturmwind reisen und Scharfseherin Umbrua im Goldenen Fass im Zwergenviertel treffen, sobald Ihr könnt.", sourceObjective = "Sprecht mit Scharfseherin Umbrua im Gasthaus Zum Goldenen Fass im Zwergendistrikt in Sturmwind.", completion = "Willkommen, {name}. Ich bin froh, dass Ihr meine Einladung angenommen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27271] = { id = 27271, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reise zum Sanktum des Magiers", description = "Soeben kam eine Nachricht aus Sturmwind an, {name}. Einer der angesehensten Magier Sturmwinds, Maginor Dumas, hat Euch zu einem Besuch im Magierviertel in Sturmwind eingeladen. Ihr werdet ihn im Sanktum des Magiers oben auf dem großen Turm im Herzen des Magierviertels finden.\n\nIch weiß nicht, was er vorhat, aber ich glaube, er ist von Eurem raschen Fortschritt beeindruckt.", sourceObjective = "Sprecht mit Maginor Dumas im Sanktum des Magiers in Sturmwinds Magierviertel.", sourceObjectiveStatus = "unverified-source-field" }
quests[27272] = { id = 27272, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demisette schickt Kunde", description = "Es scheint, als haben die Ältesten in unseren Rängen von Euren Fortschritten und Eurer Hingabe erfahren, {name}. Demisette Cloyce, eine der ältesten und geachtetsten Mitglieder unseres Kreises, hat Kunde geschickt, dass Sie Euch sprechen möchte. Ihr solltet eine Einladung wie diese sehr ernst nehmen. Die Meisten sprechen nur während ihrer Kurse mit ihr, aber wenn Sie Euch zu einem persönlichen Gespräch lädt, muss es sich um etwas Wichtiges handeln.\n\nEilt zurück nach Sturmwind und sucht sie im Gasthaus \"Zum Geschlachteten Lamm\" im Magierviertel auf.", sourceObjective = "Sprecht mit Demisette Cloyce im Gasthaus \"Zum Geschlachteten Lamm\" in Sturmwinds Magierviertel.", sourceObjectiveStatus = "unverified-source-field" }
quests[27273] = { id = 27273, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Einladung aus Mondlichtung", description = "Ihr habt den Botschafter aus Mondlichtung gerade verpasst, {name}. Er hat wenig Preis gegeben, meinte aber, er habe eine dringende Nachricht von Loganaar, einem der ehrwürdigen Ausbilder des Zirkels des Cenarius. Brecht umgehend nach Mondlichtung auf, {name}. Es scheint sich um eine wichtige Angelegenheit zu handeln.\n\nIhr werdet Loganaar in dem Dorf Nachthafen auffinden.", sourceObjective = "Sprecht mit Loganaar in Nachthafen in Mondlichtung.", completion = "Gut, dass Ihr sicher in Nachthafen angekommen seid, {name}. Ich heiße Euch mit der Gastfreundschaft des Zirkels des Cenarius willkommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27274] = { id = 27274, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Chefchirurgin", description = "Ich habe eine dringende Nachricht aus Sturmwind für Euch, {name}. Chefchirurgin Schnittschweißer hat Euch gebeten, sie in Sturmwind aufzusuchen. Die Nachricht gibt keinerlei Informationen über das Anliegen der Chefchirurgin, Ihr solltet die Reise nach Sturmwind jedoch nicht aufschieben. Sucht Chefchirurgin Schnittschweißer im Zwergendistrikt der Stadt auf.", sourceObjective = "Sprecht mit Chefchirurgin Schnittschweißer im Zwergendistrikt in Sturmwind.", sourceObjectiveStatus = "unverified-source-field" }
quests[27275] = { id = 27275, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiedervereint", description = "Wir haben uns darum gekümmert, die Schildwache zu heilen und neu auszustatten. Ich habe sie bereits wieder zum Einsatz geschickt.\n\nGeht zurück nach Düsterwolkengipfel. Sie wird Euch dort treffen.", sourceObjective = "Sprecht mit der Schildwache von Feralas in Düsterwolkengipfel in Tausend Nadeln.", completion = "Schön Euch wiederzusehen, {name}. Lasst uns den Grimmtotem Angst vor der Göttin einjagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27276] = { id = 27276, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiedervereint", description = "Wir haben uns darum gekümmert, den Kriegerhelden zu heilen und neu auszustatten. Ich habe ihn bereits wieder zum Einsatz geschickt.\n\nGeht zurück nach Düsterwolkengipfel. Er wird Euch dort treffen.", sourceObjective = "Sprecht mit dem Kriegerheld des Freiwindpostens in Düsterwolkengipfel in Tausend Nadeln.", completion = "Ich fühle mich durch Eure Gegenwart geehrt, {name}. Lasst uns den Grimmtotem Angst vor der Erdenmutter einjagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27277] = { id = 27277, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Audienz bei Ureda", description = "Ich habe eine dringende Nachricht aus Orgrimmar für Euch, {name}. Die berühmte Magierin Ureda wünscht, Euch in Orgrimmar zu empfangen. Ich bin mir nicht sicher, worum es hier geht, aber wenn ich Ihr wäre, würde ich so schnell wie möglich in die Hauptstadt reisen und Ureda in der Kluft der Schatten aufsuchen.", sourceObjective = "Sprecht mit Ureda in der Kluft der Schatten.", completion = "Ah, gut. Meine Nachricht hat Euch anscheinend erreicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[27278] = { id = 27278, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf der Grimmschlag", description = "Ein Bote aus Orgrimmar hat gerade eine Nachricht für Euch gebracht. Ich soll Euch ausrichten, dass Ormak Grimmschlag, der Jägerlehrer aus Orgrimmar, Euch treffen möchte.\n\nReist schnell nach Orgrimmar und sucht Ormak im Tal der Ehre auf.", sourceObjective = "Sprecht mit Ormak Grimmschlag im Tal der Ehre.", sourceObjectiveStatus = "unverified-source-field" }
quests[27279] = { id = 27279, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zerschmetterte Hand", description = "Ein Bote aus Orgrimmar kam gerade mit einer Mitteilung für Euch an. Gordul, der leitende Schurkenlehrer aus Orgrimmar, schickt nach Euch. Ihr müsst Euch sofort nach Orgrimmar begeben und ihn in der Kluft der Schatten aufsuchen.\n\nWenn Gordul ein Treffen einberuft, ist es weise, der Aufforderung zu folgen. Lasst ihn nicht warten, {name}.", sourceObjective = "Sprecht mit Gordul in der Kluft der Schatten in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[27280] = { id = 27280, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Traumsucher ruft", description = "Kardris Traumsucher, eine Schamanin, deren Weisheit bei der Horde legendär ist, hat Kunde geschickt, dass sie Euch sprechen möchte. Der Botschafter ließ nicht verlauten, was so dringlich sei. Er meinte nur, Ihr solltet schnellstmöglich nach Orgrimmar aufbrechen und Kardris im Tal der Weisheit aufsuchen. Sie wird dort mit anderen Ausbildern zusammentreffen, um junge Schamanen zu unterrichten.", sourceObjective = "Sprecht mit Kardris Traumsucher im Tal der Weisheit.", completion = "Ich sehe, Ihr seid sowohl folgsam als auch talentiert, {name}. Erhaltet diese Tugenden aufrecht, und Ihr werdet es in der Horde weit bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27281] = { id = 27281, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grezz Zornfaust", description = "Soeben kam die Nachricht, dass Ihr in Orgrimmar gebraucht werdet, {name}. Grezz Zornfaust, der ehrenhafte Kriegerlehrer der Stadt, hat nach Euch verlangt. Diese Aufforderung zu ignorieren wäre unklug.\n\nReist schnell nach Orgrimmar zum Tal der Ehre, wo Grezz auf Eure Ankunft wartet.", sourceObjective = "Sprecht mit Grezz Zornfaust im Tal der Ehre.", sourceObjectiveStatus = "unverified-source-field" }
quests[27282] = { id = 27282, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zevrosts Befehl", description = "{name}, soeben kam die Nachricht, dass Ihr wieder in Orgrimmar gebraucht werdet. Zevrost, einer der erfahrensten Hexenmeisterlehrer in der Kluft der Schatten, hat etwas Wichtiges mit Euch zu besprechen. Es scheint sich um etwas zu handeln, dass nicht aufgeschoben werden kann.\n\nMacht Euch auf den Weg und geht zurück nach Orgrimmar. Sprecht so bald wie möglich mit ihm.", sourceObjective = "Sprecht mit Zevrost in der Kluft der Schatten in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[27283] = { id = 27283, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Reise nach Mondlichtung", description = "Wie Ihr sicher wisst, ist Mondlichtung die Heimat des Zirkels des Cenarius, der Bruderschaft der Druiden. Alle Bewohner leben dort unter dem Frieden des Cenarius. Ausbilder Loganaar hat die Einladung nach Mondlichtung unter Anbetracht dieser Tatsache ausgesprochen.\n\nIhr werdet ihn in dem Dorf Nachthafen auffinden.", sourceObjective = "Sprecht mit Loganaar in Nachthafen.", completion = "Willkommen in Mondlichtung, {name}. Ich habe mich auf unser Treffen gefreut.", sourceObjectiveStatus = "unverified-source-field" }
quests[27284] = { id = 27284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schwarze Schild", description = "Ich kann Euch leider nicht weiterhelfen, {name}, aber ich kann Euch verraten, wer Euch helfen könnte. Caz Doppelspross, einer unserer besten Schmiede, arbeitet in der Schmiede.\n\nBringt ihm den Schild und hört Euch an, was er zu sagen hat.", sourceObjective = "Zeigt den geschwärzten Eisenschild Caz Doppelspross in Theramore.", progress = "Etwas, das ich mir anschauen soll?", completion = "Hm ... das ist ein interessantes Stück Eisen! Ganz sicher wurde der Schild von keinem der Schmiede hergestellt, die ich auf dieser Seite des Meeres kenne. Und ich kann auch mit Sicherheit sagen, dass die Arbeit nicht von mir stammt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27285] = { id = 27285, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schwarze Schild", description = "Ah, das hier hätte ich fast übersehen ... Der Lederriemen auf der Rückseite hat das Feuer wohl nicht überstanden, aber ich glaube, er wurde für eine große Person angefertigt. Ich würde auf einen Tauren tippen.\n\nAber mehr kann ich leider auch nicht ausmachen. Sagt Hauptmann Mumm, es tut mir leid, dass ich nicht mehr helfen konnte.", sourceObjective = "Sprecht mit Hauptmann Garran Mumm in Theramore.", completion = "Das ist nicht viel, mit dem wir etwas anfangen können, aber wir werden es im Kopf behalten. Hoffentlich werden uns noch andere Informationen etwas mehr Klarheit verschaffen und uns einen Überblick über das, was geschehen ist, verschaffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27286] = { id = 27286, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daelins Männer", description = "Reddon ... Oh, da haben wir ihn! Leutnant Paval Reethe.\n\nTrat den Wachen von Theramore zusammen mit den meisten Rekruten bei, die mit Lady Prachtmeer über das Meer kamen. Trat mit sechzehn Jahren den Marinesoldaten von Kul Tiras bei. Herausragende Dienste, Beförderungen ...\n\nIst als vermisst eingetragen.", sourceObjective = "Kehrt mit den Informationen über Reethe zu Hauptmann Garran Mumm in Theramore zurück.", completion = "Vermisst? Das ist Tesorans Art, \"Verräter\" zu sagen.\n\nZweifellos ist er einer dieser Narren, die Admiral Daelin so blindlings treu ergeben sind, dass sie zu Verrätern wurden. Ist das nicht eine delikate Ironie? Die Deserteure beschuldigen uns, die Allianz zu verraten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27287] = { id = 27287, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Deserteure", description = "Es war ein ständiger Kampf, in den Marschen präsent zu bleiben, aber durch die Kraft unserer Entschlossenheit konnten wir mehrere Wachtürme in diesem Gebiet zur Verteidigung halten.\n\nDie aktuellsten Informationen und Späherberichte, die ich bekam, deuten darauf hin, dass eine Gruppe Deserteure sich in unserem alten Turm bei der Verlassenen Wacht, südöstlich des Gasthauses, eingenistet hat.\n\nDer örtliche Anführer der Deserteure ist ein Mann namens Balos Jacken. Seht zu, ob Ihr Informationen von ihm bekommen könnt.\n\nSeid gewarnt, {name}. Er könnte sich als harte Nuss herausstellen.", sourceObjective = "Sammelt Informationen über Reethe von Balos Jacken und den Deserteuren in Düstermarschen.", completion = "Hat Mumm Euch geschickt? Konnte seine schmutzige Arbeit nicht selber machen, nicht wahr?", sourceObjectiveStatus = "unverified-source-field" }
quests[27288] = { id = 27288, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Deserteure", description = "Reethe? Der Feigling?\n\nWir warfen ihn aus dem Lager hinaus, weil er dauernd die Vorräte der Oger in Brackenwall plündern wollte. So viele sind wir nicht, als dass wir es mit diesen hirnlosen Schlägern aufnehmen könnten.\n\nEr hat das Fass zum Überlaufen gebracht, daher haben wir ihn sich selbst überlassen.\n\nNun, ich habe Euch also geholfen ... Nun könnt Ihr uns helfen und vergessen, dass Ihr uns gefunden habt.", sourceObjective = "Sprecht mit Hauptmann Garran Mumm in Theramore über Reethe.", completion = "Ich werde Leutnant Kaldenbrunn schicken, damit er sich um die Deserteure an der Verlassenen Wacht kümmert. Zusätzlich werde ich ihn instruieren, Reethe zu suchen. Die Marschen sind nicht so groß und auch dort gibt es Spuren. Es sollte ihm nicht allzu schwerfallen, ihn zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[27289] = { id = 27289, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mumms Bericht", description = "Ihr habt gute Arbeit geleistet, {name}, die Beste, die ich je von einem Amateur sah.\n\nLady Prachtmeer bat mich, sie über diese delikate Situation auf dem Laufenden zu halten, aber ich habe eine Weile nicht mit ihr gesprochen.\n\nIch wollte ihr meinen Bericht später bringen, aber es scheint mir passender, wenn Ihr mit ihr darüber sprecht. Ihr könnt ihre Fragen wahrscheinlich besser beantworten als ich.", sourceObjective = "Bringt Mumms Bericht zu Lady Jaina Prachtmeer in Theramore.", sourceObjectiveStatus = "unverified-source-field" }
quests[27290] = { id = 27290, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zum Gefechtsstand der Verlassenen", description = "Die Zeit, Crowley, Blutfang und jeden Hund unter ihrem Kommando zu töten, ist gekommen. Dazu muss man so gerissen und genau planen, wie wir es uns nie haben träumen lassen!\n\nAls einer der Soldaten, denen ich am meisten vertraue, müsst Ihr, {name}, zum Gefechtsstand der Verlassenen in Gilneas gehen und Euch bei Todespirscherkommandant Belmont melden. Ich habe Belmont bereits mit meinen Plänen vorausgeschickt. Er erwartet Eure Ankunft.\n\nArthura wird Euch zum Gefechtsstand der Verlassenen begleiten. Sagt mir, wenn Ihr bereit seid, und ich werde Euch auf den Weg bringen.", sourceObjective = "Meldet Euch in Gilneas am Gefechtsstand der Verlassenen bei Todespirscherkommandant Belmont.", completion = "Na, wenn das nicht Bröttinub ist!\n\nIch hoffe, Ihr seid bereit zum Kampf, denn das ist alles, was Euch in diesem Höllenloch erwartet. Wir sind mitten im umkämpften Gebiet und diese Straßenköter von Worgen wollen nicht nachgeben!", sourceObjectiveStatus = "unverified-source-field" }
quests[27291] = { id = 27291, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Endlich Frieden", description = "Ich wünschte, wir könnten James Hyals Ehefrau und Sohn wissen lassen, dass ihre Mörder Gerechtigkeit erfahren haben.\n\n<Hauptmann Mumm holt einen kleinen Blumenkranz hervor.>\n\nManche sagen, dass ihre Geister dennoch die Wahrheit erfahren, auch, wenn wir sie nicht selbst kontaktieren können. Es ist nicht viel, aber könntet Ihr diesen Kranz beim Monument der Familie Hyal niederlegen? Es ist einer der größeren Grabsteine auf dem Friedhof nördlich der Tore von Theramore.", sourceObjective = "Hauptmann Garran Mumm bei der Wehrzitadelle möchte, dass Ihr den Kranz bei dem Monument der Familie Hyal niederlegt.", completion = "<Hauptmann Mumm hat ein kleines Lächeln im Gesicht, als Ihr von den Ereignissen am Familiengrab der Hyal berichtet.>\n\nEs beruhigt mich zu wissen, dass sie es verstanden haben. Ihr habt aber nichts von James gesagt, oder?\n\nIch werde ihm die Nachricht seiner Frau ausrichten, aber ich bezweifle, dass er sie verstehen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[27292] = { id = 27292, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Krog", description = "Hoffentlich konnte ich Euch weiterhelfen. Es tut mir leid, dass ich Euch keine bessere Auskunft geben konnte. Meine Lehrlinge und ich fertigen solch eine große Menge an Waffen und Rüstungen an, dass es fast unmöglich ist, sich an detaillierte Informationen zu jedem Stück zu erinnern.\n\nWir statten nicht nur die mutigen Verteidiger der Taurenländer aus, nein, auch die Grimmtotem hegen eine besondere Vorliebe für meine Arbeit. Ein erfahrener Krieger erkennt gutes Handwerk, wenn er es sieht.", sourceObjective = "Sprecht mit Krog in Brackenwall.", completion = "Er hat wirklich gesagt, dass die Grimmtotem seine besten Kunden sind? Mosarn hat uns weit mehr geholfen, als er ahnt. Mit dieser Menge an Hinweisen, die die Grimmtotem belasten, dürften wir unsere Hauptverdächtigen gefunden haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[27293] = { id = 27293, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verschwörung der Grimmtotem", description = "Nachdem die Aktivitäten der Grimmtotem in Tausend Nadeln ans Licht gekommen sind, werden sie von mehr und mehr Tauren mit Argwohn betrachtet. Wir haben gesehen, wie sich hochrangige Vertreter der Grimmtotem an Morden und Entführungen beteiligten, um ihre eigenen Interessen voranzutreiben. Ich fürchte, wir könnten ihr nächstes Ziel sein.\n\nDas Dorf der Schwarzhufe im Nordosten, in der Nähe von Blaumoor, ist eine große neue Siedlung der Grimmtotem. Alle ihre Anführer, die Ältesten, dürften Anordnungen von Donnerfels bei sich tragen. Versucht, an die Pläne heranzukommen und setzt sie zusammen, um mehr über die Verschwörung der Grimmtotem zu erfahren.", sourceObjective = "Erlangt 4 Notizen der Grimmtotem von den Ältesten der Grimmtotem. Setzt die Teile zusammen, um die Schlachtpläne der Grimmtotem ganz zu sehen.", progress = "Konntet Ihr die Befehle ausfindig machen?", completion = "<Krog überfliegt die Schlachtpläne.>\n\nIch bin mir sicher, dass die Grimmtotem einen Angriff auf die Menschen planen. Allerdings weiß ich nicht, was ihre Absichten uns gegenüber sind. Wir wussten nichts von diesen Plänen und bedauern deswegen nun den Verlust eines guten Mannes. Ich kann mich nicht darauf verlassen, dass wir nicht auch auf ihrer Liste sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[27294] = { id = 27294, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein bloßer Zufall", description = "Wir haben die Ruinen des Gasthauses so gut es ging nach Beweisen abgesucht. Die Ergebnisse unserer Ermittlungen beunruhigen mich, aber wir müssen die Wahrheit erfahren.\n\nDie Hufabdrücke und der Schild mit Mosarns Prägung deuten darauf hin, dass die Grimmtotem ihre Finger im Spiel haben. Sie haben erst kürzlich eine Siedlung im Sumpf errichtet, das Dorf der Schwarzhufe nordöstlich von hier. Reist zum Dorf der Schwarzhufe und sucht nach weiteren Waffen, die von Mosarn angefertigt wurden.", sourceObjective = "Sammelt 7 Waffen der Schwarzhufe im Dorf der Schwarzhufe.", progress = "Was konntet Ihr im Dorf der Schwarzhufe finden?", completion = "<Krog betrachtet die Waffen und die Rüstung, die Ihr aus dem Dorf der Schwarzhufe mitgebracht habt.>\n\nDas ist ganz unverkennbar die Arbeit von Mosarn. Ihn weiter auszufragen würde zu viel Aufmerksamkeit erregen, aber bei Angelegenheiten mit den Grimmtotem haben wir etwas mehr Handlungsfreiheit.", sourceObjectiveStatus = "unverified-source-field" }
quests[27295] = { id = 27295, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sucht Tabetha auf", description = "Die Waffen, die Ihr im Dorf der Schwarzhufe gefunden habt, wurden außer zu Übungszwecken noch nie im Kampf eingesetzt. Dies bedeutet, dass die Grimmtotem, die für das Feuer im Gasthaus \"Zur Süßen Ruh\" verantwortlich sind, noch immer auf freiem Fuß sind.\n\nIm Süden, im Herzen des Morasts, lebt die Hexe Tabetha. Sie ist zwar ein Mensch, doch in der Vergangenheit hat sie uns treue Dienste geleistet und einige unserer Magier ausgebildet.\n\nBittet sie, Euch beim Aufspüren der Grimmtotem, die für den Überfall auf das Gasthaus verantwortlich sind, zu helfen. Die Allianz soll nicht auf den Gedanken kommen, dass wir etwas damit zu tun hätten.", sourceObjective = "Sprecht mit Tabetha auf ihrem Hof im Morast.", completion = "<Tabetha lächelt.>\n\nKrog möchte, dass ich die Grimmtotem ausfindig mache, ja? Nun gut, dafür braucht es aber keine Magie.\n\nAnscheinend haben wir einen gemeinsamen Feind. Die Grimmtotem haben in der Nähe einen Außenposten errichtet und sind mir und meinen Schülern ein ständiger Dorn im Auge.", sourceObjectiveStatus = "unverified-source-field" }
quests[27296] = { id = 27296, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brennt den Grollhornposten nieder!", description = "Man muss nicht Hellsehen können, um zu wissen, welche Schwierigkeiten meine neuen \"Nachbarn\" hier heraufbeschwören. Falls es sich bei ihnen wirklich um diejenigen handelt, die das Gasthaus \"Zur Süßen Ruh\" niedergebrannt haben, dann gibt es keinen Grund mehr, sie hier noch länger zu dulden.\n\nNehmt diese Fackel und brennt ihr Lager nieder! Der Grollhornposten liegt nördlich von meinem Hof, in der Nähe der Straße. Ihr könnt ihn nicht verfehlen, wirklich. Die Grimmtotem haben ganze Arbeit geleistet und ihre Anwesenheit durch das Aufstellen ihrer Totems förmlich angekündigt.", sourceObjective = "Benutzt Tabethas Fackel, um das nördliche Zelt, das östliche Zelt und das nordöstliche Zelt am Grollhornposten in Flammen zu setzen.", progress = "Hat die Fackel ihren Zweck erfüllt?", completion = "Unsere Nachricht dürfte bei den Grimmtotem problemlos angekommen sein.\n\nWas Euch betrifft, so solltet Ihr Eurer Kontaktperson in Brackenwall von Eurem Erfolg berichten. So wie ich ihn kenne, wird ihm der Nachgeschmack der Rache gefallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27297] = { id = 27297, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Walten der Gerechtigkeit", description = "Ich bezweifle, dass die Grimmtotem ihren Plan, die Menschen aus den Marschen zu vertreiben, aufgeben werden, allerdings habe ich den Eindruck, dass Euch das nicht weiter stört. Zumindest haben wir die Schuldigen für ihre Verbrechen am Gasthaus \"Zur Süßen Ruh\" bestraft.\n\nGeht und berichtet Eurem Anführer, dass die Rache gestillt wurde.", sourceObjective = "Kehrt zu Krog in Brackenwall zurück.", completion = "<Krog hört sich Euren Bericht an.>\n\nIch bin beeindruckt, {name}. Ich hatte vermutet, dass die verbrecherischen Grimmtotem nicht so einfach auszumachen sind. Die Allianz ist wirklich unfähig.\n\nUm ehrlich zu sein wollte ich eigentlich nur eine Antwort auf den Tod einer meiner Männer, aber in diesem Fall hatte ich wohl mehr Glück, als ich erwartet hatte. Falls die Grimmtotem sich rächen wollen, wird dies wohl durch einen Schlag gegen die Allianz passieren. Vielleicht haben wir sogar bald genügend Streitmächte, um diesen Haufen Dreck ein für alle Mal von unseren Küsten zu vertreiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[27298] = { id = 27298, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sucht Meister Pyreanor auf", description = "Meister Pyreanor, ein erfahrener Blutritter und Berater des Kriegshäuptlings, verlangt nach Eurer Anwesenheit in Orgrimmar. Er zeigt Interesse an Eurer Ausbildung, {name}, und es ist von äußerster Wichtigkeit, dass Ihr sofort mit ihm sprecht.\n\nDie Nachricht, die ich erhalten habe, gibt keinen Grund für Euren Besuch an, aber Ihr solltet Euch umgehend nach Orgrimmar aufmachen. Ihr könnt Meister Pyreanor in der Burg im Zentrum vom Tal der Stärke finden.", sourceObjective = "Sprecht mit Meister Pyreanor im Tal der Stärke in Orgrimmar.", completion = "Ich habe viel von Euch gehört, {name}. Ihr habt in der Horde eine strahlende Zukunft vor Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[27299] = { id = 27299, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerrissener Boden", description = "Ihr werdet nich' viel Überzeugungsarbeit leisten müss'n, um uns gegen den Schattenhammer aufzubringen - wir mögen die eh nicht. Wir sind aber schon wegen 'ner Schlacht hier, also brauchen wir vielleicht Eure Hilfe, bevor wir uns der Festung zuwenden können.\n\nDie Schattenhammerkultisten haben Iso'rath schon aus dem Boden im Süden geholt, habt Ihr sicher bemerkt. Seine Tentakel sind überall um uns 'rum aus dem Boden geschossen. Wir könnten 'ne helfende Hand gebrauchen, um sie niederzuschlagen. Was meint Ihr?", sourceObjective = "Tötet 3 Tentakel von Iso'rath.", progress = "Glück mit den Tentakeln gehabt?", completion = "Danke, {class}. 'N bisschen Platz zum Atmen hilft wirklich.", sourceObjectiveStatus = "unverified-source-field" }
quests[27300] = { id = 27300, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurückstoßen", description = "Die Schattenhammerkultisten haben 'ne Siedlung des Drachenmals im Süden zerstört und halten von dort aus Beschwörungsrituale ab. Gebt ihnen keine Gelegenheit, zur Ruhe zu kommen und zu ihren Zaubern zurückzukehren. Bringt die Schlacht zu ihnen!", sourceObjective = "Tötet 12 Schattenhammer in den Ruinen des Lagers der Drakgor.", completion = "Rache is' bittersüß, aber ich bin froh, dass jemand so mächtig wie Ihr die Sache in die Hand nimmt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27301] = { id = 27301, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungebrochen", description = "Wir bereiten ein Ritual vor, dass dabei helfen könnte, Iso'rath zu zerstören, die alte, von den Göttern gezüchtete Monstrosität, die vom Schattenhammer aus den Tiefen geholt wurde. Die Zeit läuft uns jedoch davon, denn unsere mächtigste Mitstreiterin wurde bei dem Angriff auf ihr Lager festgehalten.\n\nErdenruferin Yevaa befindet sich in den Ruinen südlich von hier. Sie ist noch am Leben, davon bin ich überzeugt. Bitte, rettet sie. Wenn einer von uns Eure Hilfe verdient, dann ist sie es.", sourceObjective = "Findet Erdenruferin Yevaa in den Ruinen von Drakgor.", completion = "Den Elementen sei Dank, dass Ihr gekommen seid. Haben meine Brüder Euch geschickt?", sourceObjectiveStatus = "unverified-source-field" }
quests[27302] = { id = 27302, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einfache Lösungen", description = "Ich bin neu hier. Ganz neu. Aber wisst Ihr was? Ich hab wenigstens Aussichten!\n\nIch hab ein paar Freunde, Schamanen, die haben Großes vor sich, aber die sind so festgefahren; sie vertrauen gänzlich auf Elemente und vergessen, die normalen Rohstoffe in ihrer Umgebung zu nutzen.\n\nBei den Ruinen südlich von hier habe ich gesehen, wie die Schläger des Schattenhammers Fass um Fass entflammbares Öl abtransportiert haben. Sie haben das Öl benutzt, um unsere Siedlung niederzubrennen. Ich schlage vor, wir tun es ihnen gleich.", sourceObjective = "Sammelt 10 Scheiterhaufenbrandölfässer.", progress = "Ich frage mich, was passiert, wenn man das Zeug über einen Elementar kippt. Ob ein Super-über-Leuchtfeuer-Elementar entsteht? Ich glaube fast schon. Das müssen wir ausprobieren.", completion = "Ha, genau das hab ich gemeint! Stellt Euch nur vor, was man damit alles machen kann! Mir fällt sicher nur ein Bruchteil ein. Aber die Nutzungsmöglichkeiten, die mir in den Sinn kommen, gefallen mir auf jeden Fall!", sourceObjectiveStatus = "unverified-source-field" }
quests[27303] = { id = 27303, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mitleid mit den Gebundenen", description = "Natürlich hatte ich kein Bedürfnis, dort zu bleiben, aber es gab dort ein paar Materialien, die wir für das Ritual brauchen ... Ich war nicht schnell genug, alles einzusammeln, und das hat dann dazu geführt, dass sie mich geschnappt haben.\n\nIch werde zum Kreis zurückkehren, aber ich wäre Euch sehr dankbar, wenn Ihr an meiner Stelle diese Aufgabe abschließen könntet. Wir brauchen die Herzen der gebundenen Feuerelementare, die die Schattenhammerkultisten im westlichen Teil des Lagers gefangen halten.\n\nDie Elementare können nicht gerettet werden, aber durch dieses Opfer können sie Rache ausüben.\n\nTrefft mich im Lager.", sourceObjective = "Sammelt 5 Fleischbrennerherzen.", progress = "Konntet Ihr die Herzen einholen?", completion = "Ich danke Euch, {name}. Ihr seid sehr fähig. Ich bin Euch äußerst dankbar, dass Ihr Euch entschlossen habt, uns zu helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27304] = { id = 27304, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Sonne hinterher", description = "Sonnenwandler Atohmo schickt Kunde aus Orgrimmar. Er möchte Euch sprechen, wenn Ihr in der Stadt seid. Ich muss Euch wohl kaum daran erinnern, dass Atohmo ein ehrenhaftes Mitglied unseres Orden ist und seine Aufforderung nicht ignoriert werden sollte.\n\nWenn Ihr das nächste Mal in Orgrimmar seid, begebt Euch zum Tal der Weisheit und sprecht mit ihm.", sourceObjective = "Sprecht mit Sonnenwandler Atohmo im Tal der Weisheit in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[27305] = { id = 27305, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von Liebe und Familie", description = "In der Scharlachroten Bastion befindet sich ein Gemälde, dass für Hochlord Tirion Fordring persönlich äußerst wertvoll ist. Sucht nach einem Gemälde unseres Zwillingsmondes. Wenn Ihr die oberste Farbschicht abkratzt, werdet Ihr darunter das Meisterwerk 'Von Liebe und Familie' vorfinden.\n\nMöge das Licht Euch den Weg weisen. Oh, bitte seid äußerst vorsichtig mit dem Gemälde.", sourceObjective = "Findet 'Von Liebe und Familie'.", progress = "Das Gemälde, {name}. Habt Ihr das Gemälde?", completion = "Meister Fording wird überglücklich sein, das Gemälde zurück zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[27306] = { id = 27306, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprecht mit Ogron", description = "Ich kenne diesen Menschen, Paval Reethe. Lächerlich, selbst für einen seiner Art. Er ist ein Deserteur und hat seine Kameraden hintergangen. Jetzt versteckt er sich in den Wäldern.\n\nIch habe Ogron geschickt, um ihn ausfindig zu machen. Ein paar von den anderen glauben, dass er von unseren Vorräten gestohlen hat. Ich glaube, Ogron ist in Richtung Südosten unterwegs.", sourceObjective = "Findet Ogron südöstlich von Brackenwall.", completion = "Ogron? Jo, das bin ich.\n\nSchhh. Seid leise. Kroks hören Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[27310] = { id = 27310, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Waffen für Grimmtotem!", description = "Nun gut, diese Feiglinge wollen kämpfen? Mal sehen, wie sie das ohne jegliche Waffen anstellen wollen.\n\nIhr habt doch sicherlich eine Fackel oder etwas in der Art.\n\nBrennt ihre Waffenregale nieder. Brennt sie alle nieder!", sourceObjective = "Brennt 8 Grimmtotemwaffenständer nieder.", completion = "Wir werden sehen, wie sie ihren Krieg jetzt führen!", sourceObjectiveStatus = "unverified-source-field" }
quests[27311] = { id = 27311, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Waffen für Grimmtotem!", description = "Die Grimmtotem wollen kämpfen? Mal sehen, wie sie das ohne ihre Waffen anstellen wollen. \n\nIhr habt doch sicherlich irgendwas, das brennt. Brennt ihre Waffenständer nieder, {class}.\n\nLasst die Natur die Arbeit verrichten.", sourceObjective = "Brennt 8 Grimmtotemwaffenständer nieder.", completion = "Mal sehen, wie gut sie ohne ihre Waffen kämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27312] = { id = 27312, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimmtotem in Düsterwolkengipfel", description = "Es geht nicht anders. Wenn man einen Kampf gewinnen will, muss Blut vergossen werden. Und in diesem Fall viel Blut.\n\nIhr wisst, was zu tun ist.", sourceObjective = "Tötet 20 Tauren der Grimmtotem in Düsterwolkengipfel.", completion = "Das hat ihre Zahlen verringert! Es ist ja nicht so, als hätten sie es nicht verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[27313] = { id = 27313, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimmtotem in Düsterwolkengipfel", description = "Es gibt keine Alternative; wenn man einen Kampf gewinnen will, muss man das Blut des Feindes vergießen. Und in diesem Fall leider viel Blut.\n\nIhr wisst, was zu tun ist.", sourceObjective = "Tötet 20 Tauren der Grimmtotem in Düsterwolkengipfel.", completion = "Die Erdenmutter duldet Gewalt wie diese nicht, aber wir hatten keine andere Wahl. Die Grimmtotem haben ihre Lehren schon zu lange ignoriert, und ernten nun, was sie gesät haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[27314] = { id = 27314, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Häuptlinge der Grimmtotem: Isha Düsteraxt", description = "Grundlagen der Schildwachenausbildung: wenn der Anführer ausgelöscht ist, wird der Rest der Streitmacht bald zerfallen. Und genau das werden wir tun, {class}.\n\nIsha Düsteraxt ist von den Häuptlingen der Grimmtotem am wenigsten weit entfernt. Mal sehen, ob wir es mit ihr aufnehmen können.", sourceObjective = "Tötet Isha Düsteraxt.", completion = "Sie war ein stärkerer Gegner, als ich erwartet hatte. Wir haben gut zusammengearbeitet, aber wir müssen sicherstellen, dass wir die anderen Häuptlinge der Grimmtotem nicht unterschätzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27315] = { id = 27315, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Häuptlinge der Grimmtotem: Isha Düsteraxt", description = "Die Grundlagen der Kriegerheldenphilosophie legen fest, dass durch den Tod eines Anführers die restlichen Streitmächte bald den Mächten der Verwirrung zum Opfer fallen. Und genau das werden wir tun, {class}.\n\nIsha Düsteraxt ist von den Häuptlingen der Grimmtotem am wenigsten weit entfernt. Wir werden sie und ihre Axt auf die Probe stellen, und sie wird kläglich scheitern.", sourceObjective = "Tötet Isha Düsteraxt.", completion = "Sie war ein außerordentlicher Gegner, weitaus besser, als ihr Ruf vermuten lässt. Obwohl wir gut zusammengearbeitet haben, müssen wir sicherstellen, dass wir die anderen Häuptlinge der Grimmtotem nicht unterschätzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27316] = { id = 27316, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rassel der Knochen", description = "Eine Rassel der Tauren liegt hier und strahlt übernatürliche Macht aus. Ohne seine Hüter ist das Artefakt ungeschützt.\n\nVielleicht kann die Schildwache uns Einblicke in seine Bedeutung geben?", sourceObjective = "Gebt die Rassel der Knochen der Schildwache von Feralas in Düsterwolkengipfel in Tausend Nadeln.", progress = "Das ist die sagenhafte Rassel der Knochen, {name}!", completion = "Es ist also wahr! Aber was macht sie hier? Wenn die Rassel hier ist, bedeutet das, dass auch die Niederschrift und die Trommeln in der Nähe sein müssen!\n\nVielleicht gibt es eine Verbindung zwischen der Rassel und der Windnatter, die eben erschienen ist? Ich habe eine Ahnung, was es mit dieser Kreatur auf sich haben könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[27317] = { id = 27317, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rassel der Knochen", description = "Eine Rassel der Tauren liegt hier und strahlt übernatürliche Macht aus. Ohne seine Hüter ist das Artefakt ungeschützt.\n\nVielleicht kann der Kriegerheld uns Einblicke in seine Bedeutung geben?", sourceObjective = "Gebt die Rassel der Knochen dem Kriegerheld des Freiwindpostens in Düsterwolkengipfel in Tausend Nadeln.", progress = "Die sagenhafte Rassel der Knochen, {name}!", completion = "Es ist also wahr! Aber was macht sie hier? Wenn die Rassel hier ist, bedeutet das, dass auch die Niederschrift und die Trommeln in der Nähe sein müssen!\n\nVielleicht gibt es eine Verbindung zwischen der Rassel und der Windnatter, die eben erschienen ist? Ich glaube, ich weiß, was es mit dieser Kreatur auf sich hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[27318] = { id = 27318, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Häuptlinge der Grimmtotem: Ältester Sturmhuf", description = "Der Älteste Sturmhuf ist ein Schamane mit ernormer Macht. Anscheinend ist er die rechte Hand von Magatha Grimmtotem, der Ältestengreisin und Anführerin des Grimmtotemklans.\n\nWir wissen, dass er hier ist und damit beschäftigt ist, Geomanten auszubilden. Wir müssen ihn töten, {class}.", sourceObjective = "Tötet den Ältesten Sturmhuf.", completion = "Das wären zwei. Bleiben noch zwei.\n\nIch frage mich, was er mit \"auserwählt\" gemeint hat?", sourceObjectiveStatus = "unverified-source-field" }
quests[27319] = { id = 27319, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Häuptlinge der Grimmtotem: Ältester Sturmhuf", description = "Der Älteste Sturmhuf ist ein Schamanenhäuptling mit ernormer Macht. Er wurde von Magatha Grimmtotem unterrichtet, der Ältestengreisin und Anführerin des Grimmtotemklans.\n\nWir wissen, dass er hier ist und damit beschäftigt ist, Geomanten auszubilden. Wir müssen ihn töten, {class}.", sourceObjective = "Tötet den Ältesten Sturmhuf.", completion = "Das war kein Spaß. Ich frage mich, was er damit gemeint hat, als er Euch \"auserwählt\" genannt hat?", sourceObjectiveStatus = "unverified-source-field" }
quests[27320] = { id = 27320, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Niederschrift der Geschichte", description = "In der Mythologie der Shu'halo ist die Rassel der Knochen eng mit der Niederschrift der Geschichte und den Trommeln des Krieges verknüpft. Es handelt sich dabei anscheinend um wertvolle Artefakte der Tauren.\n\nWir müssen unsere Augen offen halten, wenn wir die anderen zwei Artefakte finden wollen. Wenn man den Geschichten Glauben schenken will, sieht die Niederschrift wohl aus wie eine Schriftrolle mit Piktogrammen.", sourceObjective = "Findet die Niederschrift der Geschichte.", progress = "Wir brauchen die echte Niederschrift, nicht irgendeine Schriftrolle der Tauren.", completion = "Ich bin mir relativ sicher, dass es die Niederschrift ist. Das ist sehr verwunderlich, {name}. Was haben die hier zu suchen? Werden sie als Waffen benutzt?\n\nDie Windnatter ist nordwestlich zum nächsten Felsen geflogen. Vielleicht sind die Trommeln dort?", sourceObjectiveStatus = "unverified-source-field" }
quests[27321] = { id = 27321, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Niederschrift der Geschichte", description = "Die Rassel der Knochen ist Teil der uralten Mythologie der Shu'halo. Sie wurde schon immer mit der Niederschrift der Geschichte und den Trommeln des Krieges in Verbindung gebracht. Es handelt sich dabei anscheinend um wertvolle Artefakte der Tauren, Geschenke von der Erdmutter, wenn man den Geschichten Glauben schenken soll. Allerdings kann ich mir nicht vorstellen, dass die Erdmutter mit den Trommeln wirklich etwas zu tun hat.\n\nWir müssen aufmerksam sein, wenn wir die anderen zwei Artefakte finden wollen. Wenn ich mich recht erinnere, sieht die Niederschrift wohl aus wie eine Schriftrolle mit Piktogrammen.", sourceObjective = "Findet die Niederschrift der Geschichte.", progress = "Wir brauchen die echte Niederschrift, nicht irgendeine Schriftrolle.", completion = "Das ist sehr aufregend, aber auch Besorgnis erregend, {name}. Was haben die Artefakte hier zu suchen? Und werden sie von den Grimmtotem als Waffen gegen uns verwendet?\n\nDie Windnatter ist nordwestlich zum nächsten Felsen geflogen. Vielleicht sind die Trommeln dort?", sourceObjectiveStatus = "unverified-source-field" }
quests[27322] = { id = 27322, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Korok der Koloss", description = "Das Monster ist gefallen und hat den Soldaten der Verlassenen an der Front so eine kurze Atempause verschafft.\n\nBringt Koroks zweiten Kopf zu Vorpostenkommandant Ansturm am Gefechtsstand der Verlassenen.", sourceObjective = "Bringt Koroks zweiten Kopf zu Vorpostenkommandant Ansturm am Gefechtsstand der Verlassenen in den Ruinen von Gilneas.", progress = "Korok ist tot?", completion = "Dieses riesige Ungetüm hat hunderte unserer Soldaten in den Tod gerissen. Ihr habt heute gute Arbeit geleistet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27323] = { id = 27323, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Häuptlinge der Grimmtotem: Grundig Finsterwolke", description = "Einer der berüchtigten Anführer der Grimmtotem von Steinkrallengebirge ist zurückgekehrt.\n\nWir sollten diese Gelegenheit nutzen und sicherstellen, dass er nirgendwo anders hingeht.", sourceObjective = "Tötet Grundig Finsterwolke.", completion = "<Die Schildwache versucht, Euch einzuschätzen.>\n\nWas ist mit Euch los? Warum beunruhigt Eure Anwesenheit alle anderen?", sourceObjectiveStatus = "unverified-source-field" }
quests[27324] = { id = 27324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Häuptlinge der Grimmtotem: Grundig Finsterwolke", description = "Einer der versiertesten Anführer der Grimmtotem vom Steinkrallengebirge ist zurückgekehrt.\n\nWir müssen das Beste aus dieser Situation machen und seiner Schreckensherrschaft ein für alle Mal ein Ende setzen.", sourceObjective = "Tötet Grundig Finsterwolke.", completion = "<Der Kriegerheld versucht, Euch einzuschätzen.>\n\nIhr habt etwas Besonderes an Euch, {name}. So viel ist sicher.", sourceObjectiveStatus = "unverified-source-field" }
quests[27325] = { id = 27325, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Trommeln des Krieges", description = "Was auch immer die Grimmtotem mit diesen Trommeln des Krieges machen, wir wollen nicht, dass sie noch länger in ihrem Besitz bleiben.\n\nSorgt Euch nicht, {name}, wir werden eine Lösung finden. Zuerst müssen wir aber alle Teile dieses Rätsels erlangen.", sourceObjective = "Findet die Trommeln des Krieges.", progress = "Die Tauren lieben Trommeln. Ich kann mir jedoch vorstellen, dass die Trommeln des Krieges sich von normalen Trommeln unterscheiden.", completion = "Das war sicher die Stimme der Ältestengreisin!\n\nWir müssen uns vorsehen, {name}. Vor uns liegen große Gefahren, wenn Magatha Grimmtotem Euch bemerkt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[27326] = { id = 27326, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Trommeln des Krieges", description = "Was auch immer die Grimmtotem mit den Trommeln des Krieges machen, wir wollen nicht, dass sie sie behalten.\n\nSorgt Euch nicht, {name}, wir werden herausfinden, was hier vor sich geht. Zuerst müssen wir aber alle Artefaktteile finden.", sourceObjective = "Findet die Trommeln des Krieges.", progress = "Krieg ist keine Alternative für diejenigen, die sich an den Lehren der Erdmutter orientieren.", completion = "Das war sicher die Stimme der Ältestengreisin!\n\nWir müssen uns vorsehen, {name}. Vor uns liegen große Gefahren, wenn Magatha Grimmtotem Euch bemerkt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[27327] = { id = 27327, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Häuptlinge der Grimmtotem: Der Häuptling aller Häuptlinge", description = "Die Zeit ist gekommen, dem Anführer aller Grimmtotem in Düsterwolkengipfel ein Ende zu bereiten: Arnak Grimmtotem.\n\nEs wird gesagt, dass er der in Ungnade gefallene Neffe von Magatha Grimmtotem ist, der Ältestengreisin und Matriarchin des Grimmtotemklans. Seine Taktlosigkeit hat wohl dazu geführt, dass sie ihm gegenüber nicht wohlgesinnt ist.\n\nAll dies ist aber jetzt nicht wichtig. Nur sein Tod ist für uns von Wichtigkeit. Sein endgültiger Tod.", sourceObjective = "Tötet Arnak Grimmtotem.", completion = "Aus irgendeinem Grund meinen alle, dass Ihr von Magatha Grimmtotem gesandt wurdet. Ich weiß, dass es etwas mit der Windnatter zu tun hat, die hier in letzter Zeit rumlungerte.\n\nIst aber auch egal. Ihr Anführer ist tot. Es ist nur eine Frage der Zeit, bis die Tauren den Freiwindposten wieder ihre Heimat nennen können.\n\nWenn ich einer von denen wäre, würde ich wohl ein bisschen Druck machen, um die Grimmtotem eine Lektion zu lehren. Aber das machen sie wahrscheinlich nicht. Sie sind immerhin Tauren.", sourceObjectiveStatus = "unverified-source-field" }
quests[27328] = { id = 27328, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Häuptlinge der Grimmtotem: Der Häuptling aller Häuptlinge", description = "Die Zeit ist gekommen, um uns dem Anführer aller Grimmtotem in Düsterwolkengipfel zuzuwenden: Arnak Grimmtotem.\n\nEr ist der in Ungnade gefallene Neffe von Magatha Grimmtotem, der Ältestengreisin und Matriarchin des Grimmtotemklans. Seine Taktlosigkeit hat dazu geführt, dass sie ihm gegenüber nicht wohlgesinnt ist.\n\nAll dies ist aber jetzt nicht wichtig. Von Wichtigkeit ist nur, dass wir uns seiner annehmen. Ein für alle Mal.", sourceObjective = "Tötet Arnak Grimmtotem.", completion = "Alle haben geglaubt, dass Ihr von Magatha Grimmtotem geschickt wurdet. Man kann immerhin nicht leugnen, dass ihr Begleiter Arikara hier ist.\n\n<Der Kriegerheld blickt Euch lange an.>\n\nEs ist nicht wirklich wichtig. Arnak ist tot. Es ist nur eine Frage der Zeit, bis wir Freiwindposten zurückerobern.\n\nVielleicht wird es uns nun möglich sein, dauerhaften Frieden mit den Grimmtotem zu schließen?", sourceObjectiveStatus = "unverified-source-field" }
quests[27329] = { id = 27329, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Windnatter entfernen", description = "Ich kenne diese Artefakte. Ich glaube, sie wurden von Magatha Grimmtotem persönlich hierher gebracht. Sie ist aber nicht bei den Grimmtotem in Düsterwolkengipfel. Sie ist gleich nach ihrer Ankunft wieder aufgebrochen, und niemand weiß, wo sie jetzt ist.\n\nVielleicht können wir es herausfinden.\n\nNehmt die Rassel, die Niederschrift, und die Trommeln mit zu Arikaras Steinkreis. Wenn ich richtig liege, wird die Windnatter wieder auftauchen. Ihr müsst sie besiegen, um über Magathas Versteck Hinweise zu erhalten.", sourceObjective = "Bezwingt Arikara.", completion = "Sie wurde also von den Schattenhammerkultisten gefangen genommen. Ich kann nicht sagen, dass ich großes Mitleid empfinde, aber in deren Händen könnte sie sich als noch gefährlicher herausstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27330] = { id = 27330, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Windnatter entfernen", description = "Ich kenne diese Artefakte. Ich glaube, sie wurden von Magatha Grimmtotem persönlich hierher gebracht. Sie ist aber nicht bei den Grimmtotem in Düsterwolkengipfel. Sie ist gleich nach ihrer Ankunft wieder aufgebrochen, und niemand weiß, wo sie jetzt ist.\n\nVielleicht können wir es herausfinden.\n\nNehmt die Rassel, die Niederschrift, und die Trommeln mit zu Arikaras Steinkreis. Wenn ich richtig liege, wird die Windnatter wieder auftauchen. Ihr müsst sie besiegen, um über Magathas Versteck Hinweise zu erhalten.", sourceObjective = "Bezwingt Arikara.", completion = "Sie wurde also von den Schattenhammerkultisten gefangengenommen. Ich kann nicht sagen, dass ich großes Mitleid empfinde, aber in deren Händen könnte sie sich als noch gefährlicher herausstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27331] = { id = 27331, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ruf der Seherin", description = "Soeben kam die Nachricht, dass Ihr in Orgrimmar gebraucht werdet, {name}. Seherin Liwatha bittet Euch, so schnell wie möglich in die Stadt zurückzukehren. Ihre Nachricht enthielt keine weiteren Informationen, aber es schien dringlich zu sein.\n\nSucht Seherin Liwatha im Tal der Weisheit in Orgrimmar auf.", sourceObjective = "Sprecht mit Seherin Liwatha im Tal der Weisheit in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[27332] = { id = 27332, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sucht den Schattenläufer auf", description = "Der Schattenläufer Zuru fordert Eure sofortige Anwesenheit in Orgrimmar, {name}. Lasst ihn nicht warten, denn es klang, als sei es eine wichtige Angelegenheit.\n\nIhr werdet den Schattenläufer im Tal der Geister in Orgrimmar vorfinden.", sourceObjective = "Sprecht mit Schattenläufer Zuru im Tal der Geister in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[27333] = { id = 27333, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haltlos", description = "Ich weiß nicht, wie lange wir die Stellung noch halten können, {name}. Die Worgen von Crowley und Blutfang kennen jedes noch so kleine Versteck und jeden sicheren Ort in Gilneas. In der einen Minute stehen sie vor Euch und in der nächsten Minute sind sie schon wieder weg! Wir werden diesen Krieg durch ihre Gelegenheitsangriffe verlieren, obwohl wir zahlenmäßig gesehen die Oberhand haben.\n\nMami hat aber keinen Aufgeber aus mir gemacht! Ich bin ein Verlassener bis zum bitteren Ende.\n\nBegebt Euch in die Mark und helft unseren Soldaten an vorderster Front. Tötet die angreifenden Rebellen der Worgen!", sourceObjective = "Tötet 12 Rebellen der Worgen.", completion = "Wenn ich noch Luft bekommen würde, würde ich jetzt erleichtert aufatmen.\n\nMacht es Euch nicht zu gemütlich, {name}. Eure Mission fängt hier erst an.", sourceObjectiveStatus = "unverified-source-field" }
quests[27334] = { id = 27334, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkle Klerikerin Cecille", description = "Ich habe soeben eine Nachricht von der Dunklen Klerikerin Cecille aus Orgrimmar erhalten. Sie fordert Euch auf, sie in ihrem Audienzgemach in der Feste Grommash aufzusuchen. Sie empfängt dort eine Delegation aus Unterstadt. Die Klerikerin hat nicht gesagt, worum es bei Eurem Besuch geht, aber es ist ganz offensichtlich wichtig. Beeilt Euch, {name}.", sourceObjective = "Sprecht mit der dunklen Klerikerin Cecille in Feste Grommash im Tal der Stärke in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[27335] = { id = 27335, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reise nach Orgrimmar", description = "Ein Botschafter hat mich gebeten, Euch diese Einladung zu geben. Sie ist von Tyelis, einem Priesterlehrer und Abgesandten von Silbermond.\n\nEr fordert Euch auf, ihn in der Feste Grommash in Orgrimmar zu treffen. Ihr solltet sofort aufbrechen, {name}. Die Einladung klingt wichtig.", sourceObjective = "Sprecht mit Tyelis in Feste Grommash im Tal der Stärke in Orgrimmar.", completion = "Willkommen, {name}. Ich bin froh, dass Ihr meine Einladung angenommen habt. Wir haben viel zu besprechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27336] = { id = 27336, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Waffe der Grimmtotem", description = "Bevor ich während des letzten Angriffs der Grimmtotem verwundet wurde, konnte ich noch ein recht seltsames Totem an mich bringen, das von unseren Feinden gegen uns eingesetzt wurde.\n\nIm Kampf lässt es wohl wilde Energieblitze von sich. Leider konnte ich mit keinem meiner Experimente herausfinden, wie es funktioniert. Wenn Ihr versprecht, mir zu helfen, werde ich Euch das Totem leihen.\n\nDie Wasserflächen, die den Hof umgeben, beheimaten aggressive scheckige Staubsuhlerkrokilisken und Staubsuhlerdolchrachen. Versucht, die Krokilisken in Reichweite des Totems zu bekämpfen.", sourceObjective = "Platziert das erbeutete Totem auf dem Boden und tötet 10 scheckige Staubsuhlerkrokilisken oder Staubsuhlerdolchrachenen, um den Effekt des Totems zu testen.", progress = "Konntet Ihr das Totem erfolgreich testen?", completion = "<Der Lehrling hört Euch zu, als Ihr den Verlauf des Experiments schildert.>\n\nDunst und ein paar Blitze? Sonst nichts? Das Totem muss mehr können als nur das! Die Grimmtotem würden so etwas nicht mit aufs Schlachtfeld bringen, wenn es nicht irgendeinen wirklichen Nutzen hat!", sourceObjectiveStatus = "unverified-source-field" }
quests[27337] = { id = 27337, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine passende Waffe", description = "Schon zu Beginn haben Eure Lehrer Euch für ein Naturtalent gehalten, {name}. Euer rascher Fortschritt und Eure Hingabe haben Euch zu einem wahren Vorbild gemacht.\n\nIn Anerkennung Eurer Dienste hat König Wrynn den königlichen Waffenschmied gebeten, eine besondere Waffe für Euch anzufertigen.\n\nDen Legenden zufolge ist die verfluchte Burg Schattenfang im Silberwald der Ort, an dem einige der Materialien zu finden sind, die Ihr dafür benötigt. Reist dorthin und findet das verlorene Schwert der Familie Silberlein, eine Ladung Mondstahlbarren und Sehnen der Ghule und Spuke, die die Burg heimsuchen.", sourceObjective = "Reist zu Burg Schattenfang und erhaltet das Schwert der Familie Silberlein von Baron Silberlein, 5 Kisten Mondstahlbarren und 5 ewige Sehnen.", progress = "Habt Ihr die Materialien besorgt, die ich für Eure Waffe benötige?", completion = "Ander hat gesagt, ich soll Euch erwarten. Es ist eine Ehre, für Euch eine Waffe zu schmieden, {name}. Mit diesen Materialien wird es wahrhaftig eine ausgezeichnete Klinge.", sourceObjectiveStatus = "unverified-source-field" }
quests[27338] = { id = 27338, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsere Jungs an der Küste", description = "Die Lage hier in Hochland ändert sich minütlich. Unser Ziel ist es, die Bastion des Zwielichts zu stürmen, aber ich kann nicht mal eine Landezone an der Küste sichern, ohne dass die verfluchte Horde Ärger macht.\n\nIch brauche Männer, die hier am Strand die Landung sichern, während ich die Überreste der Flotte zusammensuche.\n\nMeldet Euch bei Leutnant Emry an der Küste und helft seinen Marinesoldaten, die Horde zurückzudrängen!", sourceObjective = "Meldet Euch bei Leutnant Emry in Zwielichtufer im Schattenhochland.", completion = "Zieht Euren Kopf ein, bevor er ihn verliert, {class}!\n\nDas hier ist MEIN Strand.\n\nDie Horde WILL meinen Strand.\n\nSie werden meinen Strand nicht BEKOMMEN.\n\nIst die Strandsituation damit geklärt?", sourceObjectiveStatus = "unverified-source-field" }
quests[27339] = { id = 27339, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Reagenziendieb", description = "Wenn es eine Sache gibt, auf die man sich bei Lehrling Morlann verlassen kann, dann ist es sein ewiges Genörgel über fehlende Reagenzien.\n\nNormalerweise versuche ich einfach, ihn zu ignorieren, aber das funktioniert nicht. Dieses Mal werde ich etwas anderes versuchen.\n\nVielleicht lässt er mich in Ruhe, wenn ich fehlende Reagenzien ersetze, bevor ihm überhaupt auffällt, dass etwas fehlt. Das von uns am häufigsten genutzte Reagenz ist Marschengift. Ihr findet es bei Dunkelzahnkrabblern und giftigen Schreddern in den Marschen nördlich des Hofs. Wenn Ihr mir das Gift bringt, werde ich die Vorräte auffrischen, bevor Morlann merkt, dass etwas gefehlt hat.", sourceObjective = "Sammelt 6 Phiolen Marschengift von Dunkelzahnkrabblern oder giftigen Schreddern.", progress = "Habt Ihr das Gift bekommen? Morlann wird jeden Moment bemerken, dass nichts mehr da ist ...", completion = "<Lehrling Garion überprüft das Gift.>\n\nAbsolut perfekt! Der Unterschied wird ihm nie auffallen!", sourceObjectiveStatus = "unverified-source-field" }
quests[27340] = { id = 27340, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Räuber des Grollhornpostens", description = "Die Grimmtotem hoch oben in Grollhornposten werden von Tag zu Tag frecher. Nachts hört man oft, wie sie in Chören von ihren Taten im Kampf gegen die Bewohner der Gegend singen.\n\nSie sind festentschlossen, uns von Tabethas Hof zu vertreiben, obwohl schon Generationen von Lehrlingen hier ausgebildet wurden. Wir haben den Hof so gut es ging verteidigt, aber Lehrling Garion wurde beim letzten Angriff verwundet.\n\nBegebt Euch nach Grollhornposten und tötet alle Grimmtotem, die Ihr finden könnt! Diese Angriffe müssen ein Ende finden.", sourceObjective = "Tötet 12 Grimmtotem in Grollhornposten.", completion = "<Lehrling Morlann nickt.>\n\nGut. Ich werde ihre Anwesenheit nicht vermissen, wenn man es denn Anwesenheit nennen kann. Man sollte meinen, dass man wenigstens mitten im Sumpf ein wenig unter sich ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[27341] = { id = 27341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Späht den Strand aus", description = "Es ist ganz einfach, wir oder sie, {class}. Nur eine Fraktion kann diesen Strand einnehmen.\n\nNördlich von hier ist ein kleiner Hügel, von dem man die ganze Küstenlinie überblicken kann. Wer diesen Hügel einnimmt, erlangt sofort die Oberhand an der ganzen Küste.\n\nIch muss wissen, was die aktuelle Lage ist. Späht den Brückenkopfkontrollpunkt aus. Ihr erkennt ihn an den großen Flaggen. Kehrt anschließend zu mir zurück.\n\nIhr müsst nicht versuchen, ihn einzunehmen, es sei denn, Ihr dürstet nach einem Kampf ...", sourceObjective = "Späht den Brückenkopfkontrollpunkt in Zwielichtufer aus. Ihr müsst den Kontrollpunkt nicht einnehmen. Wenn Ihr ihn einnehmt, wird Eure Seite jedoch Vorteile im Kampf haben und Ihr werdet für PvP gekennzeichnet.", completion = "So ist das Land nun mal beschaffen. Wenn Ihr Schwierigkeiten mit dem Kampf an der Küste habt, könnt Ihr Euch vielleicht überlegen, hier auszuhelfen und versuchen, mit uns den Hügel einzunehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27342] = { id = 27342, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zeit löst alle Rätsel", description = "Die Dunkle Fürstin hat Euch und Arthura für eine ganz besondere Aufgabe einberufen. Bevor ich Euch jedoch mehr verrate, müssen wir erst einige Vorbereitungen treffen.\n\nBegebt Euch zum Wald von Gilneas östlich von hier und sucht in der Nähe der Bäume und Steine in der Gegend nach einer besonderen Pflanze, die als Wolfsbann bekannt ist. Sammelt so viel Wolfsbann, wie Ihr tragen könnt und kehrt zu mir zurück.\n\nUnsere Aufgabe hier übersteigt die Aufgaben auf dem Schlachtfeld, {name}. Ich werde Euch zu gegebener Zeit mehr verraten.", sourceObjective = "Sammelt 6 Wolfsbann.", progress = "Konntet Ihr den Wolfsbann finden?", completion = "<Belmont nimmt Euch den Wolfsbann ab.>\n\nGut. Von jetzt an folgt den Befehlen von Vorpostenkommandant Ansturm. Versucht, Euch so gut wie möglich in die Reihen der Soldaten einzufinden. Wir wollen nicht, dass die Gilnearische Befreiungsfront auf Euch aufmerksam wird.\n\nOh, Ihr wusstet nicht, dass sie uns beobachten? In diesem Augenblick sind die Augen von fünf Spionen der Worgen direkt auf uns gerichtet. Bleibt ruhig und befolgt alle Befehle. Ich werde Euch Bescheid geben, wenn wir weitermachen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[27343] = { id = 27343, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hand des Lichts", description = "Ich habe Eure Fortschritte verfolgt, {name}, und ich kann nur schließen, dass das Licht strahlend auf Euch scheint. Ihr seid wahrhaftig <ein vorbildlicher/eine vorbildliche:c> {class}.\n\nUm Eurer Hingabe Anerkennung zu zollen, hat König Wrynn den königlichen Waffenschmied beauftragt, eine besondere Waffe für Euch anzufertigen.\n\nDie Materialien zur Herstellung dieser Waffe sind einzigartig und können nur in der verfluchten Burg Schattenfang im Silberwald gefunden werden. Reist dorthin und findet das verlorene heilige Symbol von Kommandant Grüntal, eine Ladung Mondstahlbarren, und Sehnen der Ghule und Spuke, die die Burg heimsuchen.", sourceObjective = "Reist nach Burg Schattenfang und findet das heilige Symbol des Kommandanten von Kommandant Grüntal, 5 Kisten Mondstahlbarren und 5 ewige Sehnen.", progress = "Konntet Ihr die Materialien für Eure Waffe finden?", completion = "Lord Grayson hat mir viel von Euch und Eurer Hingabe zum Licht und der Allianz erzählt. Es wird mir eine große Ehre sein, einen Hammer für Euch anzufertigen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27344] = { id = 27344, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine wohlverdiente Belohnung", description = "Nicht nur ich bin von Eurem Fortschritt beeindruckt, {name}. Wie Ihr Bogen und Begleiter meistert, und auch Eure Hingabe zur Allianz, sind König Wrynn zu Ohren gekommen.\n\nIn Anerkennung Eurer Dienste hat der König seinen königlichen Bogenmacher beauftragt, eine besondere Waffe für Euch anzufertigen.\n\nDie verfluchte Burg Schattenfang im Silberwald ist der Ort, an dem Ihr die einzigartigen Bestandteile finden könnt, die für diese Waffe benötigt werden. Reist dorthin und findet das Zielfernrohr von Lord Godfreys Gewehr, eine Ladung mondbestrahltes Holz und Sehnen der Ghule und Spuke, die die Burg heimsuchen.", sourceObjective = "Reist nach Burg Schattenfang und erhaltet Godfreys Kristallzielfernrohr von Lord Godfrey, 5 Bündel mondbestrahltes Holz und 5 ewige Sehnen.", progress = "Habt Ihr die Materialien besorgt, die ich für Eure Waffe benötige?", completion = "Wer hätte gedacht, dass in einer verfluchten Burg so wertvolle Gegenstände zu finden sind? Ich sehe es als Ehre an, sie in eine wunderbare Waffe für Euch zu verarbeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27345] = { id = 27345, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das K.d.V.", description = "Die Kommunikation zu allen unseren Außenposten an der Front ist abgebrochen, {name}. Jetzt gerade habe ich nicht die leiseste Ahnung, wie es unseren Truppen in Gilneas ergeht. Wir müssen die Kommunikation wieder herstellen.\n\nBegebt Euch nach Westen in die Mark und findet unseren Außenposten an der Küste. Die Soldaten dort sind wahrscheinlich alle tot, aber ihr K.d.V. könnte noch funktionieren. Nehmt das Gerät an Euch und kehrt zu mir zurück.", sourceObjective = "Findet die Kommunikationsvorrichtung der Verlassenen.", progress = "Findet das K.d.V.", completion = "Mit diesem Gerät kann ich mich während Eurer Einsätze mit Euch in Verbindung setzen. Jetzt müssen wir uns daran machen, unsere Außenposten an der Front zu überprüfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27346] = { id = 27346, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zeppelinabsturz", description = "Vor Kurzem ist östlich von hier ein Zeppelin der Goblins abgestürzt. Eine Beauftragte des Dampfdruckkartells kam hier vor ein paar Tagen vorbei.\n\nSie wollte Informationen über die Ladung des Zeppelins und den Piloten, Beezil, erhalten. Von uns hat den Absturz aber niemand wirklich gesehen. Ich bezweifle, dass sie das Zeppelinwrack alleine lichten kann, und noch viel weniger, dass sie je erfahren wird, welche Ladung an Bord war.\n\nWenn Ihr Zeit habt, könntet Ihr ihr vielleicht bei Beezils Wrack helfen. Es ist östlich von hier, in der Nähe der Berge.", sourceObjective = "Sprecht mit Moxie Stahlgrill bei Beezils Wrack.", completion = "Die Einsiedlermagier haben Euch geschickt? Wie soll ich wissen, dass ich Euch vertrauen kann?\n\nHilfe kann ich wohl gebrauchen. Hier gibt es auch nicht wirklich viel, für das sich Magier interessieren könnten.", sourceObjectiveStatus = "unverified-source-field" }
quests[27347] = { id = 27347, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Korrosionsschutz", description = "Seht Euch nur um! Alles ist voller Schlamm. Wenn wir nicht bald eine Möglichkeit finden, ihn unter Kontrolle zu bekommen, wird er das Wrack und die gesamte Zeppelinladung zersetzen und unbrauchbar machen!\n\nIch kann nicht mit leeren Händen zurückkehren, {class}! Helft mir, diese Schlamme aufzulösen, bevor sie alles zerstören!\n\nDieses Gerät feuert, sofern es aufgeladen ist, konzentrierte Energie auf einen Schlamm ab und bringt ihn so zur Explosion. Die Kraftkernfragmente des Zeppelins sollten über ausreichend Energie verfügen, um das Gerät anzutreiben. Der Kern beim Hauptwrack funktioniert einwandfrei, doch die anderen Kraftkerne laufen nur gelegentlich.", sourceObjective = "Moxie Stahlgrill möchte, dass Ihr 10 Schlamme auflöst und Euch dann bei Beezils Wrack bei ihr meldet.", progress = "Konntet Ihr gegen die Schlamme etwas ausrichten?", completion = "Naja, es sieht hier schon ein bisschen besser aus ...\n\nIch schätze, es ist an der Zeit, die Bergungsarbeiten fortzusetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27348] = { id = 27348, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bergt die Fracht!", description = "Der Zeppelin hatte Vorräte für die nächsten sechs Monate für Morastwinkel geladen! Glücklicherweise konnte Morastwinkel sich bisher mit Tauschgeschäften über Wasser halten, doch das wird auf die Dauer nicht möglich sein.\n\nIch wurde hierher geschickt, um so viele Vorräte wie möglich zu bergen, doch leider sind die Wrackteile über die gesamten Marschen verteilt. Ich bin ziemlich sicher, dass nur die wenigsten Vorräte den Absturz heil überstanden haben. Würdet Ihr mir ein bisschen bei der Bergung helfen?", sourceObjective = "Moxie Stahlgrill bei Beezils Wrack möchte, dass Ihr 8 Teile der Zeppelinfracht bergt.", progress = "<Moxie sieht aus, als sei ihr vor Sorge ganz schlecht.>\n\nHaben die Vorräte den Absturz überstanden? Konntet Ihr sie finden?", completion = "Wow! Ihr habt in jedem Fall viel mehr gefunden, als ich erwartet hatte. Ich weiß nicht, welche Ausbeute Drazzit von uns erwartet, aber zunächst wird er sich damit zufrieden geben müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27349] = { id = 27349, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kommunikationsabbruch: Außenposten von Schreckenswacht", description = "Ich werde Euch nicht anlügen, {name}. Was ich von Euch verlange ist mehr oder weniger Selbstmord. Die Wahrscheinlichkeit einer Niederlage beträgt 95%.\n\nAlle Kommunikation zum Außenposten der Schreckenswacht ist abgebrochen. Durch die ständigen Angriffe der Worgen haben wir keine Möglichkeit, zur Schreckenswacht aufzubrechen und nach unseren Soldaten zu schauen. Macht Euch auf den Weg in Richtung Süden zum Außenposten und seht nach unseren Soldaten. Ich werde von jetzt an mit Euch über die Kommunikationsvorrichtung der Verlassenen - dem K.d.V. - in Verbindung bleiben.\n\nHALTET EUCH VON DER HAUPTSTRASSE FERN.", sourceObjective = "Erkundet den Außenposten von Schreckenswacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[27350] = { id = 27350, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kommunikationsabbruch: Rutsaks Wacht", description = "<Das K.d.V. brummt.>\n\nUnser nächster Außenposten ist Rutsaks Wacht, östlich von Schreckenswacht. Sucht Rutsak auf und seht zu, dass Ihr den Stürmern der Worgen entgeht, {name}. Diesen Monstern wollt Ihr nicht allein begegnen.\n\nWenn Ihr es in einem Stück dorthin schafft, sucht nach Hauptmann Rutsak.\n\nMacht Euch auf das Schlimmste gefasst.", sourceObjective = "Findet Hauptmann Rutsak in Rutsaks Wacht in den Ruinen von Gilneas.", completion = "Ss...na...na...nachdem wir Gilneas verloren haben, konnten wir auch den Hafen nicht h...h...halten.\n\nMM...MMM...MENSCHEN, HIER SIND MENSCHEN! Verstärkung aus Sturmwind! Sie haben meine Männer abgeschlachtet. Haben mich am Leben gelassen, um von ihrer Stärke zeugen zu können. Um meinen Befehlshabern... um zu berichten, dass die 7. Legion hier ist ...", sourceObjectiveStatus = "unverified-source-field" }
quests[27351] = { id = 27351, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine königliche Belohnung", description = "Der SI:7 hat Eure Fortschritte mit Interesse beobachtet. Eure Dienste für die Allianz sind bekannt und Geschichten über Eure Taten sind dem König zu Ohren gekommen.\n\nIn Anerkennung Eurer Dienste hat König Wrynn den königlichen Waffenschmied gebeten, eine besondere Waffe für Euch anzufertigen.\n\nDie verfluchte Burg Schattenfang im Silberwald ist der Ort, an dem Ihr die fremdartigen Bestandteile finden könnt, die für Eure Waffe benötigt werden. Reist dorthin und beschafft Euch Kommandant Grüntals Wetzstein, eine Ladung Mondstahlbarren, und Sehnen der Ghule und Spuke, die die Burg heimsuchen.", sourceObjective = "Reist zu Burg Schattenfang und erhaltet Grüntals Wetzstein von Kommandant Grüntal, 5 Kisten Mondstahlbarren und 5 ewige Sehnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27352] = { id = 27352, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flüssiges Gold", description = "Nachdem die Geißel wie eine Krankheit durch Stratholme fegte, stellten die Ritter der Silbernen Hand Weihwasser her, um es gegen die Eindringlinge zu nutzen. Sie haben es in kleinen Kisten zusammen mit anderen wichtigen Vorräten gelagert und in der ganzen Stadt verteilt. Leider wurden die Einwohner der Stadt zu Geißeln, bevor die Vorräte je genutzt werden konnten!\n\nDie Vorratskisten werden sich für unsere Zwecke als äußerst nützlich erweisen. Bringt eine Phiole mit Weihwasser von Stratholme zu mir, damit ich es in größeren Mengen herstellen kann.", sourceObjective = "Findet eine Phiole mit Weihwasser von Stratholme.", progress = "Ist das eine Phiole mit Weihwasser von Stratholme?\n\nHe, ist das ganz normales Wasser? Spielt mit dem alten Steinberster keine Spielchen!", completion = "Hervorragend! Ich glaube, in größeren Mengen wird sich das Weihwasser als verheerend herausstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27353] = { id = 27353, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Segen der Elemente", description = "Euer Talent hat in den Kreisen der Schamanen viel Aufsehen erregt, {name}. Geschichten von Eurer Beherrschung der Elemente und Eurer Hingabe zur Allianz können selbst im Palast vernommen werden.\n\nIn Anerkennung Eurer Dienste hat König Wrynn den königlichen Waffenschmied gebeten, eine besondere Waffe für Euch anzufertigen.\n\nDie Materialien für Eure Waffe können nur in der verfluchten Burg Schattenfang im Silberwald gefunden werden. Reist dorthin und erlangt den Talisman von Lord Walden, das Buch der verlorenen Seelen und Essenzen der Geister, die das Schloss heimsuchen.", sourceObjective = "Reist nach Burg Schattenfang und erhaltet den Waldens Talisman, das Buch der verlorenen Seelen und 5 geisterhafte Essenzen.", progress = "Habt Ihr die Materialien besorgt, die ich für Eure Waffe benötige?", completion = "Ich habe nicht oft die Möglichkeit, mit so fremdartigen Materialien zu arbeiten, aber selbst ich spüre die Macht dieser Gegenstände. Es wird mir eine Ehre sein, eine unglaubliche Waffe für Euch herzustellen, {name}. Die Weissagerin hat nicht untertrieben, als sie mir von Euren Fähigkeiten erzählte.", sourceObjectiveStatus = "unverified-source-field" }
quests[27354] = { id = 27354, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beherrschung des Arkanen", description = "Ihr habt Euch als <ausgezeichneter Student und engagierter Diener/ausgezeichnete Studentin und engagierte Dienerin> der Allianz herausgestellt. Selbst der König hat schon von Euren Leistungen gehört.\n\nIn Anerkennung Eurer Dienste hat König Wrynn den königlichen Verzauberer beauftragt, eine besondere Waffe für Euch anzufertigen.\n\nDie Materialien, die für Euren Stab benötigt werden, können nur in der verfluchten Burg Schattenfang im Silberwald gefunden werden. Reist dorthin und findet das verlorene Erbe der Familie Silberlein, etwas mondbestrahltes Holz und die Essenz der Geister, die die Burg heimsuchen.", sourceObjective = "Reist nach Burg Schattenfang und erlangt Silberleins verzauberten Kristall von Baron Silberlein, 5 Bündel mondbestrahltes Holz und 5 geisterhafte Essenzen.", progress = "Habt Ihr die Materialien besorgt, die ich für Eure Waffe benötige?", completion = "Ich habe Euch bereits erwartet, {name}. Maginor Dumas spricht in lobenden Tönen von Euch, und der Auftrag des Königs bestätigt diese Worte. Es ist mir eine Ehre, für Euch einen Stab anfertigen zu können.", sourceObjectiveStatus = "unverified-source-field" }
quests[27355] = { id = 27355, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Segen für die Mächtigen", description = "Dank Eurer Taten bemerkt der König langsam unsere Macht und unseren Wert für die Allianz. Vielleicht werden die Unsrigen langsam akzeptiert.\n\nKönig Wrynn hat in Anerkennung Eurer Dienste den königlichen Verzauberer beauftragt, eine mächtige Waffe für Euch anzufertigen.\n\nDie Materialien dafür sind nur in Burg Schattenfang im Silberwald zu bekommen. Reist dorthin und erlangt die finstere Kugel von Lord Godfrey, das Buch der verlorenen Seelen, und Essenzen der Geister, die das Schloss heimsuchen.", sourceObjective = "Reist nach Burg Schattenfang und erhaltet die Finstere Kugel von Lord Godfrey, das Buch der verlorenen Seelen und 5 geisterhafte Essenzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27356] = { id = 27356, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zukunft des Zirkels", description = "Der Zirkel des Cenarius ist zufrieden mit Eurem Fortschritt, {name}. Ihr seid von Wert für alle Druiden. Wir sehen in Euch und Euren Verbündeten die Zukunft unserer Bruderschaft.\n\nDer Zirkel hat entschieden, Euch mit der Herstellung eines einzigartigen Stabs zu ehren.\n\nDie seltenen und mächtigen Materialien für diesen Stab können nur in Burg Schattenfang im Silberwald gefunden werden. Reist dorthin und findet Lord Waldens Elixiersammlung, eine Ladung mondbestrahltes Holz, und Sehnen der Ghule und Geister, die die Burg heimsuchen.", sourceObjective = "Reist nach Burg Schattenfang und erhaltet Waldens Elixire von Lord Walden, 5 Bündel mondbestrahltes Holz und 5 ewige Sehnen.", progress = "Habt Ihr die Materialien besorgt, die ich für Euren Stab benötige?", completion = "Ah, Ihr müsst der {class} sein, von dem Loganaar erzählt hat. Ich freue mich, Euch endlich zu treffen. Loganaar und andere Mitglieder des Zirkels halten viel von Euch. Es wird mir eine Ehre sein, diesen Druidenstab für Euch anzufertigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27357] = { id = 27357, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die gefangene Braut", description = "Natürlich! Lakota Windweise! Warum ist mir das nicht früher eingefallen?\n\nArnak hat Lakota vor Jahren entführt und versucht, sie in eine Ehe zu zwingen. Sie konnte fliehen, aber in dem Chaos durch die Angriffe auf Freiwindposten in letzter Zeit konnte er sie wieder schnappen.\n\nSie muss hier irgendwo in der Nähe sein. Sie ist in den letzten Jahren recht mystisch geworden. Ich glaube, dass sie weiß, was man mit den Artefakten der Tauren machen kann.", sourceObjective = "Sprecht mit Lakota Windweise in Düsterwolkengipfel in Tausend Nadeln.", completion = "Es ist peinlich, schon wieder von Arnak entführt worden zu sein. Ich habe draußen Kampfgeräusche gehört. Habt Ihr ihn getötet?\n\n<Für einen winzigen Moment sieht die Schamanin traurig aus.>\n\nIch bin froh, wieder frei zu sein. Nun, wie kann ich Euch helfen, {race}?", sourceObjectiveStatus = "unverified-source-field" }
quests[27358] = { id = 27358, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die gefangene Braut", description = "Lakota Windweise! Warum ist mir das nicht früher eingefallen?\n\nArnak hat Lakota vor Jahren entführt und mit Gewalt versucht, sie zu seiner Braut zu machen. Sie konnte mit etwas Hilfe fliehen, aber in dem Chaos durch die Angriffe auf Freiwindposten in letzter Zeit konnte er sie wieder schnappen.\n\nSie muss in der Nähe sein. Sie hat in den letzten Jahren viel Schamanenwissen erworben. Ich bin mir sicher, dass sie uns sagen kann, inwiefern die Rassel, die Niederschrift und die Trommeln wichtig sind.", sourceObjective = "Sprecht mit Lakota Windweise in Düsterwolkengipfel in Tausend Nadeln.", completion = "Es ist peinlich, schon wieder von Arnak entführt worden zu sein. Ich habe draußen Kampfgeräusche gehört. Habt Ihr ihn getötet?\n\n<Für einen winzigen Moment sieht die Schamanin traurig aus.>\n\nIch bin froh, wieder frei zu sein. Nun, wie kann ich Euch helfen, {class}?", sourceObjectiveStatus = "unverified-source-field" }
quests[27359] = { id = 27359, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verstärkung der Argentumdämmerung", description = "Die Geißel haben eine Art Zauber gewirkt, der mich daran hindert, ein Portal zu öffnen. Daher kann auch unserer Verstärkung nun nicht dabei helfen, die Stadt einzunehmen! Es ist wie ein nicht enden wollender Schrei in meinem Kopf! Argh!\n\nIch versuche mein Bestes, um durch die Geräusche dieser Barriere nicht verrückt zu werden. Meine Vermutung ist, dass dieser Schutzwall von den Banshees aufrechterhalten wird. Bringt mir ihre Essenzen – ich glaube, ich kann sie benutzen, um einen Gegenzauber zu wirken, damit die Verstärkung eintreffen kann!", sourceObjective = "Erhaltet 4 Essenzen einer Banshee.", progress = "Konntet Ihr die Essenzen erhalten? Seid vorsichtig, die Banshees sind todbringende Zauberer.", completion = "Oh... die Banshees sind in der Tat geschundene Seelen. Selbst das Halten ihrer Essenz schmerzt dem Gemüt...\n\nAber genug davon. Ich mache mich an den Gegenzauber, damit wir das Portal bald erstellen können. Stratholme wird bald Unser sein, ich weiß es einfach.", sourceObjectiveStatus = "unverified-source-field" }
quests[27360] = { id = 27360, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rache für unsere Soldaten", description = "Die 7. Legion… Sie haben uns mitten in der Nacht überrannt. Ihr Hauptmann hat Befehle gebrüllt, während die Besatzung des U-Boots meine Männer abgeschlachtet hat. Dann kam er zu mir, sah mir direkt in die Augen und sagte etwas, das ich nie vergessen werde:\n\n\"Ich bin Hauptfeldwebel Pietro Zaren, Offizier der 7. Legion. Wenn Ihr in Euren Alpträumen seht - wenn Ihr überhaupt noch schlafen könnt - wie Eure Soldaten massakriert werden, dann erinnert Euch an meinen Namen und zittert!\"\n\nRächt meine Soldaten! Tötet die 7. Legion, die das Kathedralenviertel von Gilneas südwestlich von hier besetzt.", sourceObjective = "Tötet 10 Unterseebootmatrosen der 7. Legion.", completion = "Obwohl wir in der Schlacht bloßgestellt wurden, konnte der Feind keinen Sieg erringen. Ich werde das niemals vergessen, {name}.\n\nWenn ich es heil in den Silberwald zurück schaffe, werde ich mich wahrscheinlich ausmustern. Der Krieg steckt mir nicht im Blut.", sourceObjectiveStatus = "unverified-source-field" }
quests[27361] = { id = 27361, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vom Licht begünstigt", description = "Das Licht scheint wirklich hell auf Euch und Eure Hingabe zur Allianz, {name}. Ihr seid wahrhaftig ein gutes Beispiel für Eure Priesterkameraden und Kampfgenossen.\n\nIn Anerkennung Eurer Taten hat König Wrynn den königlichen Verzauberer beauftragt, einen besonderen Stab für Euch anzufertigen.\n\nDie Materialien für diese Waffe können nur in der verfluchten Burg Schattenfang im Silberwald gefunden werden. Reist dorthin und findet das verlorene heilige Symbol von Kommandant Grüntal, etwas mondbestrahltes Holz und die Essenz der Geister, die die Burg heimsuchen.", sourceObjective = "Reist nach Burg Schattenfang und erhaltet das heilige Symbol des Kommandanten von Kommandant Grüntal, 5 Bündel mondbestrahltes Holz und 5 geisterhafte Essenzen.", progress = "Habt Ihr die Materialien besorgt, die ich für Eure Waffe benötige?", completion = "Ich kann kaum glauben, dass Ihr all diese Materialien wirklich erhalten konntet. Ich persönlich kann mir nicht vorstellen, mich nach Burg Schattenfang zu trauen. Die Geschichten über diesen Ort sind entsetzlich.\n\nAber genug davon. Diese Zeit ist der Anerkennung Eurer Leistungen gewidmet, nicht dem Geschwätz über meine Ängste.", sourceObjectiveStatus = "unverified-source-field" }
quests[27362] = { id = 27362, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elunes Liebling", description = "Ihr seid ein echter Diener Elunes, ein Beispiel für unser Volk, und ein tapferer Diener der Allianz. Der Tempel des Mondes und der Hof von Sturmwind möchten Eure Leistungen ehren.\n\nWir haben den königlichen Verzauberer beauftragt, einen Stab für Euch zu fertigen.\n\nDie Materialien für Euren Stab können nur in der verfluchten Burg Schattenfang im Silberwald gefunden werden. Reist dorthin und findet das verlorene heilige Symbol von Kommandant Grüntal, etwas mondbestrahltes Holz und die Essenz der Geister, die die Burg heimsuchen.", sourceObjective = "Reist nach Burg Schattenfang und erhaltet das heilige Symbol des Kommandanten von Kommandant Grüntal, 5 Bündel mondbestrahltes Holz und 5 geisterhafte Essenzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27363] = { id = 27363, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vielversprechend für den Chirurgenberuf", description = "Ihr habt Euch als fähig in den Reihen der Priester und als wertvoll für die Leute von Gnomeregan erwiesen. Der Hochtüftler und der König von Sturmwind möchten Eure Arbeit für die Allianz ehren.\n\nSie haben den königlichen Verzauberer beauftragt, einen besonderen Stab anzufertigen.\n\nDie Materialien für diese Waffe können nur in der verfluchten Burg Schattenfang im Silberwald gefunden werden. Reist dorthin und findet das verlorene heilige Symbol von Kommandant Grüntal, etwas mondbestrahltes Holz und die Essenz der Geister, die die Burg heimsuchen.", sourceObjective = "Reist nach Burg Schattenfang und erhaltet das heilige Symbol des Kommandanten von Kommandant Grüntal, 5 Bündel mondbestrahltes Holz und 5 geisterhafte Essenzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27364] = { id = 27364, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf wessen Befehl?", description = "<Das K.d.V. summt.>\n\nDie 7. Legion sind besondere Eliteeinheiten. Sie waren hinter den Kulissen für fast alle größeren Offensiven und Militäreingriffe der Allianz zuständig. Das sind schlechte Neuigkeiten. Wie sind sie nur an unseren Kriegsschiffen vorbei gekommen? Und auf wessen Befehl agieren sie?\n\nWir müssen ihre Befehle irgendwie in die Hände bekommen. Dieser Pietro hat sicherlich wichtige Informationen. Findet ihn im Kathedralenviertel von Gilneas und erledigt ihn. Durchsucht danach seinen Leichnam nach Hinweisen.", sourceObjective = "Findet die Befehle des Oberkommandos.", sourceObjectiveStatus = "unverified-source-field" }
quests[27365] = { id = 27365, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine passende Waffe", description = "Schon zu Beginn haben Eure Lehrer gewusst, dass Ihr Euch bei der Horde einen Namen machen werdet. Ihr habt mutig gekämpft und Euren Feinden Grund zur Angst gegeben.\n\nAls Belohnung für Eure Hingabe hat der Kriegshäuptling bei seinem eigenen Schmied eine besondere Waffe in Auftrag gegeben.\n\nDie verfluchte Burg Schattenfang im Silberwald ist der einzige Ort, an dem Ihr die Bestandteile finden könnt, die dazu benötigt werden. Reist dorthin und findet das verlorene Schwert der Familie Silberlein, eine Ladung Mondstahlbarren, und Sehnen der Ghule und Spuke, die die Burg heimsuchen.", sourceObjective = "Reist zu Burg Schattenfang und erhaltet das Schwert der Familie Silberlein vom Baron, 5 Kisten Mondstahlbarren und 5 ewige Sehnen.", progress = "Habt Ihr die Materialien besorgt, die ich für Eure Waffe benötige?", completion = "Grezz Zornfaust hat gesagt, ich soll Euch erwarten. Diese Materialien werden ein ausgezeichnetes Schwert machen. Benutzt es für den Ruhm der Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[27366] = { id = 27366, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Landerschließung", description = "Die Marinesoldaten der Axtbeißer der Horde sind überall an meinem heiß geliebten Strand.\n\n<Der Leutnant deutet in Richtung Norden, entlang der Küste.>\n\nTötet sie.", sourceObjective = "Tötet 12 Marinesoldaten der Axtbeißer am Zwielichtufer im Schattenhochland.", completion = "Tot? Alle?\n\nImmerhin ein Anfang, {class}.\n\nImmerhin ein Anfang.", sourceObjectiveStatus = "unverified-source-field" }
quests[27367] = { id = 27367, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gidwin Goldzopf", description = "Meine Jungs sind mir viel wert, versteht mich nicht falsch. Aber ich habe ihnen GESAGT, dass ich FÜNF MINUTEN brauche, um die Pferde zu versorgen und was machen sie? Schließen eine blöde Wette ab und weg sind sie! Ich hätte es besser wissen müssen... es ist immer das Gleiche.\n\nGidwin ist der kurz Gewachsene. Er hat sich in Richtung Norden aufgemacht, den Fluss entlang. Wenn Ihr in diese Richtung unterwegs sein solltet, könnt Ihr ihm sagen, er soll zurückkommen? Wir müssen zur Kapelle des Hoffnungsvollen Lichts und ich habe kein Problem damit, ihn zurückzulassen.", sourceObjective = "Findet Gidwin Goldzopf in den Östlichen Pestländern.", completion = "Tarenar? Bist du das?\n\nWer immer Ihr seid, würde es Euch etwas ausmachen, mir aus diesem Ding herauszuhelfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[27368] = { id = 27368, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur eingehüllt", description = "Ihr hättet mich im Kampf sehen sollen! Ich hab bestimmt sechs dieser Biester getötet, als...\n\nOh, stimmt, Ihr könnt ja die Leichen sehen. Na gut. Vier der Biester habe ich getötet und dann kam das fünfte an und hat dieses Netz auf mich geschossen. Und noch viel schlimmer: Als es seinen Netzsaft abgeschossen hat, war mein Mund offen!\n\nIch kann dieses Netz nicht zerstören und Ihr werdet es wohl auch nicht können. Aber die Magensäfte von den untoten Spinnendingern könnten das Netz auflösen. Das funktioniert sicher.", sourceObjective = "Erhaltet 8 Phiolen Kryptengalle von den Nerubern im Schreckenstunnel.", progress = "Oh Mann... Fiona wird wütender sein als eine nasse Harpyie. Beeilt Euch bitte.", completion = "Ihr seid zurück?! Dem Licht sei Dank!\n\nBevor Ihr die Säure über mir ausschüttet, habe ich eine Frage: seid Ihr der Typ von vorhin, oder einer dieser achtbeinigen Feiglinge? Ich muss wissen, ob ich Euch eins überbraten sollte, sobald ich hier raus bin.", sourceObjectiveStatus = "unverified-source-field" }
quests[27369] = { id = 27369, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Rad schmieren", description = "Entschuldigt mein Verhalten von eben. Ich war einfach sicher, Ihr wärt eines dieser Spinnenbiester, das sich als {race} ausgeben wollte.\n\nWie geht es Euch? Gidwin Goldzopf, zu Euren Diensten. Ich bin ein bisschen in Eile, weil ich schnell zurück zu meinem Karawanenwagen muss, aber ... könntet Ihr mir vielleicht noch einen Gefallen tun? Meine Freundin Fiona hat einen kleinen Laden und ich glaube, dass einige der Pflanzen, die hier am Flussufer wachsen, für sie von Interesse wären.\n\nIch glaube, wenn ich ihr ein paar tolle Pflanzen mitbringe, wird sie VIEL weniger sauer auf mich sein. Das ist zumindest der Plan.", sourceObjective = "Pflückt 10 Bansheeglocken vom Ufer des Thondroril.", progress = "Hat Giddy Euch mit hineingezogen?", completion = "Ich werde diesen winzigen Paladin in Stücke hauen, noch bevor er... oh, sind das etwa Bansheeglocken? Ihr habt die für mich gepflückt?\n\nOh, Gidwin hat Euch darum gebeten? Das ist wirklich süß von ihm. Na gut. Jetzt kann ich ihm fürs Erste nicht mehr böse sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[27370] = { id = 27370, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tarenar Sonnenhieb", description = "Kaum hatten wir Halt gemacht, haben sie eine Wette abgeschlossen, wer die meisten Untoten in fünf Minuten töten könne.\n\nDas ist jetzt eine Stunde her und ich warte immer noch darauf, dass sie wieder herkommen.\n\nIch habe gesehen, wie Tarenar in Richtung Südosten losgelaufen ist. Aber leider kann ich den Wagen nicht unbeaufsichtigt lassen. Wenn Ihr zufällig in diese Richtung unterwegs sein solltet, könntet Ihr ihn suchen und zu mir zurückschicken?", sourceObjective = "Findet Tarenar Sonnenhieb an der Treppe des Schnitters in den Östlichen Pestländern.", completion = "Ich habe sie gefunden, {race}. Die Geißel. Wie ich mich nach diesem Tag gesehnt habe.", sourceObjectiveStatus = "unverified-source-field" }
quests[27371] = { id = 27371, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ich am besten kann", description = "Ich erinnere mich an die Zeit zurück, als ich jung war und mich oft in die Geisterlande geschlichen habe, um stundenlang Zombies zu verprügeln. Ich habe nicht einmal eine BEZAHLUNG dafür erhalten. Ich hab es einfach so gemacht.\n\nAber jetzt schaut Euch mal um. Das sind ernst zu nehmende Zombies. Ich wollte gerade damit anfangen, sie zu verprügeln, so wie früher. Wollt Ihr mir helfen?", sourceObjective = "Tötet 5 Missgeburten der Treppe des Schnitters an der Treppe des Schnitters in den Östlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[27372] = { id = 27372, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschenk für Fiona", description = "Meine Reisegefährtin, Fiona, hat in ihrem Karawanenwagen einen kleinen Laden. Wir beide und unser Freund Gidwin sind auf dem Weg zur Kapelle des Hoffnungsvollen Lichts. Ihr könnt sicher mit uns reisen, wenn Ihr wollt... obwohl Fiona womöglich ein wenig sauer auf mich sein wird.\n\nFiona vergisst aber immer, dass sie sauer ist, wenn man ihr ein Geschenk macht. Tötet für mich ein paar dieser Seuchenhunde und bringt ihr Blut zu Fiona bei der Karawane unten am Fluss. Sie wird sich über alle Maßen freuen. Wir sehen uns dann dort!", sourceObjective = "Erhaltet 10 Proben des Bluts eines Seuchenhundes.", progress = "Ich hätte es wissen müssen. Tarenar hat dafür gesorgt, dass Ihr mir ein Geschenk macht? Dieser gedankenlose Idiot!\n\nÄhm... Um was für ein Geschenk handelte es sich denn?", completion = "Das ist ganz genau das, was ich gebraucht habe! Na gut, ich werde Tarenar dafür vergeben, dass er davongelaufen ist.\n\nIhr seid hier bei uns jederzeit willkommen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[27373] = { id = 27373, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf zur Kapelle des Hoffnungsvollen Lichts", description = "Jetzt, da die Jungs wieder hier sind, können wir endlich los. Ihr seid in Richtung Osten unterwegs?\n\nEs wäre uns eine Freude, wenn Ihr mit uns reisen würdet. Ich bestehe darauf! Erst gestern bei der Stätte der Heiler habe ich zu Tarenar gesagt: \"Wir haben zwei Paladine und mich, um auf den Laden aufzupassen, aber weißt du, was wir wirklich brauchen? <Einen echten Helden/Eine echte Heldin>!\"\n\nSeht mich nicht so an! Ehrlich! Kommt schon, springt auf!", sourceObjective = "Steigt auf Fionas Karawanenwagen am Thondroril in den Östlichen Pestländern.", completion = "Ich hoffe, die Fahrt war nicht zu holprig für Euch.\n\nSeht Euch einmal in der Gegend um den Turm herum um, solange sich die Pferde ausruhen. Es ist zwar nicht mit der Kapelle des Hoffnungsvollen Lichts zu vergleichen, aber ich bin mir sicher, dass Ihr Euch irgendwie beschäftigen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27374] = { id = 27374, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schlund des Wahnsinns", description = "Ich kann es nicht glauben, {name}. Mein eigener Sohn - mein eigen Fleisch und Blut! Tut sich mit diesen Unholden vom Schattenhammer zusammen. Habt Ihr gesehen, was aus ihm wurde, als er versuchte, die Hochzeit zu zerstören? Oh... warum? Warum?\n\nEs ist diese Bestie, {name}. Der gigantische Schlund, der im Westen aus der Erde ragt. \"Der Schlund des Wahnsinns!\" Mein Sohn sagte, er würde mit ihm sprechen, aber ich dachte, es wären nur Alpträume.\n\nDer Irdene Ring versucht, ihn zu zerstören. Geht zu Erdenrufer Torunskar, westlich von hier, und schaut, ob Ihr helfen könnt!", sourceObjective = "Sprecht am Kreis der Elemente mit Erdenrufer Torunskar.", completion = "Willkommen, Bruder. Ihr habt eine schwere Zeit ausgesucht, um uns beizutreten, aber für uns ist das ein Glück. Wir können Eure Hilfe brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27375] = { id = 27375, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schwärende Wunde", description = "Eine Bestie, {name}! Ich habe eine Bestie gesehen. Ein riesiger Schlund, ein noch größerer Hunger. Ich kann nicht glauben, dass sie wissen, was sie da losgelassen haben.\n\nEs ist hier. Sein schrecklicher formloser Körper bricht in diesem Augenblick in das Hochland herein.\n\nIch habe Euch in meiner Vision gesehen, {name}. Ihr kämpft zusammen mit dem Irdenen Ring, um das Biest zurückzudrängen. Ihr werdet der Dunkelheit gegenübertreten.\n\nGeht jetzt, bevor die Bestie an Macht gewinnt. Sprecht mit Erdenrufer Torunskar am Kreis der Elemente, nordwestlich von hier auf dem Gebirgskamm, hinter dem zerstörten Drakgorlager. Schnell!", sourceObjective = "Sprecht mit Erdenrufer Torunskar am Kreis der Elemente.", completion = "Willkommen, Bruder. Ihr habt eine schwere Zeit ausgesucht, um uns beizutreten, aber für uns ist das ein Glück. Wir können Eure Hilfe brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27376] = { id = 27376, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Maul von Iso'rath", description = "Wir sind bereit, die Bestie anzugreifen. Erst müssen wir ihre Tentakel zerstören, dann wird Yevaa ein Ritual durchführen, um einen mächtigen Feuerelementar zu beschwören, den wir in den Schlund werfen werden.\n\nIch möchte, dass Ihr mit unserer ersten Gruppenattacke ausfliegt. Tut nichts, bis sich eine Gelegenheit bietet, dann tretet dem Kampf bei, indem Ihr mit den anderen Schamanen die Tentakel abschneidet.\n\nNehmt einen unserer Greifen, wenn Ihr für den Angriff bereit seid.", sourceObjective = "Steigt auf einen Greifen, um dem Angriff auf Iso'rath beizutreten.", completion = "Die Tentakel haben uns sogar von den Greifen geschlagen! Sie waren viel beweglicher, als wir angenommen hatten.\n\nEgal. Wir waren auf diese Möglichkeit vorbereitet. Ich kann den Elementar von hier aus beschwören, wenn Ihr mich beschützt.", sourceObjectiveStatus = "unverified-source-field" }
quests[27377] = { id = 27377, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verschlungen", description = "Wir wussten, dass das eine Möglichkeit war, aber wir hatten keine Ahnung, wie sich die Bestie verteidigen würde. Iso'raths Körper reagiert schnell auf unsere Bedrohung.\n\nIch kann die Beschwörung von hier aus beendet, aber nur, wenn Ihr Iso'raths Vereidigung zurückhalten könnt. Beschäftigt sie! Wir werden überleben!", sourceObjective = "Schützt Euch und Erdenruferin Yevaa vor Iso'raths körperlicher Verteidigung.", completion = "Ich habe Euch von der Schwelle des Todes zurückgeholt, Held!\n\nTodesschwinge ist da! Wir brauchen Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[27378] = { id = 27378, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Weltenbrecher", description = "Wir haben keine Zeit! Todesschwinge hat zugeschlagen, bevor wir uns gegen ihn aufstellen konnten. Wenn Ihr ihn nicht aufhaltet, endet der Irdene Ring hier und jetzt!", sourceObjective = "Bezwingt Todesschwinge, den Aspekt des Todes.", completion = "Ihr seid wach! Den Elementen sei Dank! Ich hatte fast die Hoffnung verloren.", sourceObjectiveStatus = "unverified-source-field" }
quests[27379] = { id = 27379, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schrecken des Iso'rath", description = "Wir brauchen Euch! Ihr wart in einer Art Alptraum gefangen. Viele der anderen Schamanen sind das immer noch.\n\nEgal... unser Plan fällt auseinander. Einige unserer Schamanen kanalisieren schützende Auren, die die Verdauungsflüssigkeiten bekämpfen und Euch am Leben halten, aber wir müssen die anderen Schamanen vor den Tentakeln retten. Wir können Iso'rath nicht ohne sie besiegen!\n\nBleibt nicht ohne die anderen Schamanen im Magen, oder Ihr werdet bei lebendigem Leib verdaut!", sourceObjective = "Rettet Hargoth Trübflamm, Erdheiler Duarn, Sturmruferin Jalara und Sturmruferin Mylra.\n\nKehrt in den Schutz der anderen Schamanen zurück, wenn Iso'raths Verteidigung Euch zusetzt.", progress = "Die Schlacht ist noch nicht geschlagen. Die Schamanen innerhalb von Iso'rath zählen auf Euch!", completion = "Zusammen mit dem Irdenen Ring können wir Iso'raths Schrecken überleben. Jetzt ist es an der Zeit, uns zu rächen!", sourceObjectiveStatus = "unverified-source-field" }
quests[27380] = { id = 27380, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alptraum", description = "Iso'raths Hirn liegt frei! Der Schamane, den Ihr gerettet habt, sollte Euch in seiner Verteidigung einigermaßen sicher halten.\n\nGreift das Hirn an und zerstört Iso'rath!", sourceObjective = "Zerstört Iso'raths Gehirn.", completion = "Ihr habt heute viele meiner engsten Vertrauten gerettet, {name}. Ich kann mir kaum vorstellen, was für Schrecken Ihr in Iso'rath gesehen habt, aber Ihr habt den Dank des gesamten Irdenen Rings.", sourceObjectiveStatus = "unverified-source-field" }
quests[27381] = { id = 27381, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reisegefährten", description = "Jetzt wo wir schon hier an diesem Turm sind, können wir auch schauen, ob außer uns noch jemand zur Kapelle des Hoffnungsvollen Lichts unterwegs ist. Je mehr, desto besser, nicht wahr?\n\nFragt doch in der Umgebung, ob uns jemand auf der Reise begleiten möchte. Ich bin sicher, dass wir jemand finden werden, der auch zur Kapelle unterwegs ist.", sourceObjective = "Findet jemanden am Turm der Kronenwache, der sich Eurer Reisegruppe anschließen möchte.", progress = "Wie sieht es aus?", completion = "Argus Leuchtfeuer ... der Alte von hoch oben im Turm? Großartig!\n\nEin Mann seines Alters gehört dem Argentumkreuzzug bestimmt schon ewig an. Vielleicht kann er bei der Kapelle ein gutes Wort für uns einlegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[27382] = { id = 27382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verseuchte Straßen", description = "Der Argentumkreuzzug hat diese Türme als Lichter in der Dunkelheit der Pestländer errichtet. Ich bin auf den Pfaden zwischen den Türmen unterwegs, um sie zu schützen und instand zu halten.\n\nIn letzter Zeit wurden die Straßen aber immer gefährlicher. Verseuchte Wildtiere laufen frei herum und die Fledermäuse greifen nichtsahnende Reisende an. Es würde den nächsten Teil meiner Reise sehr erleichtern, wenn Ihr für mich die wilden Tiere aus dem Weg schaffen könntet.", sourceObjective = "Tötet 13 Seuchenfledermäuse entlang des Wegs zum Lichtschildturm.", completion = "Natürlich war es für einen jungen {race} wie Euch nicht schwierig, ein paar Wildtiere zu beseitigen. Jetzt, da die Straßen geräumt sind, wird meine Reise zum nächsten Turm viel einfacher.", sourceObjectiveStatus = "unverified-source-field" }
